def _rotation_matrix_xyz(angles_deg) -> np.ndarray:
    ax, ay, az = (float(v) for v in angles_deg)
    rx = np.deg2rad(ax)
    ry = np.deg2rad(ay)
    rz = np.deg2rad(az)
    cx, sx = np.cos(rx), np.sin(rx)
    cy, sy = np.cos(ry), np.sin(ry)
    cz, sz = np.cos(rz), np.sin(rz)
    rot_x = np.array([[1.0, 0.0, 0.0], [0.0, cx, -sx], [0.0, sx, cx]], dtype=float)
    rot_y = np.array([[cy, 0.0, sy], [0.0, 1.0, 0.0], [-sy, 0.0, cy]], dtype=float)
    rot_z = np.array([[cz, -sz, 0.0], [sz, cz, 0.0], [0.0, 0.0, 1.0]], dtype=float)
    return rot_z @ rot_y @ rot_x


def _convex_hull_2d(points: np.ndarray) -> np.ndarray:
    pts = np.asarray(points, dtype=float)
    if pts.ndim != 2 or pts.shape[0] < 3 or pts.shape[1] != 2:
        return pts
    pts = pts[np.lexsort((pts[:, 1], pts[:, 0]))]
    unique = [pts[0]]
    for point in pts[1:]:
        if np.linalg.norm(point - unique[-1]) > 1e-9:
            unique.append(point)
    pts = np.asarray(unique, dtype=float)
    if pts.shape[0] < 3:
        return pts

    def cross(o, a, b) -> float:
        return float((a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]))

    lower: list[np.ndarray] = []
    for point in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], point) <= 0.0:
            lower.pop()
        lower.append(point)
    upper: list[np.ndarray] = []
    for point in pts[::-1]:
        while len(upper) >= 2 and cross(upper[-2], upper[-1], point) <= 0.0:
            upper.pop()
        upper.append(point)
    hull = np.asarray(lower[:-1] + upper[:-1], dtype=float)
    return hull


def _profile_from_section_points(yz: np.ndarray, bins: int = 180) -> np.ndarray:
    pts = np.asarray(yz, dtype=float)
    if pts.ndim != 2 or pts.shape[0] < 8 or pts.shape[1] != 2:
        return np.empty((0, 2), dtype=float)
    pts = pts[np.all(np.isfinite(pts), axis=1)]
    if pts.shape[0] < 8:
        return np.empty((0, 2), dtype=float)
    z_vals = pts[:, 0]
    y_vals = pts[:, 1]
    z_min = float(np.min(z_vals))
    z_max = float(np.max(z_vals))
    if not np.isfinite(z_min) or not np.isfinite(z_max) or z_max <= z_min:
        return np.empty((0, 2), dtype=float)
    edges = np.linspace(z_min, z_max, max(int(bins), 24) + 1)
    top: list[tuple[float, float]] = []
    bot: list[tuple[float, float]] = []
    for lo, hi in zip(edges[:-1], edges[1:]):
        mask = (z_vals >= lo) & (z_vals <= hi if hi == edges[-1] else z_vals < hi)
        if not np.any(mask):
            continue
        z_mid = float(np.mean(z_vals[mask]))
        ys = y_vals[mask]
        top.append((z_mid, float(np.max(ys))))
        bot.append((z_mid, float(np.min(ys))))
    if len(top) < 4 or len(bot) < 4:
        return np.empty((0, 2), dtype=float)
    return np.array(top + bot[::-1] + [top[0]], dtype=float)


# ---------------------------------------------------------------------------
#  Analytic STEP export helpers
# ---------------------------------------------------------------------------

def _is_surface_revolution_compatible(sdt_surf) -> bool:
    """True when a KrakenOS surface is rotationally symmetric and can be
    exported as an OpenCascade surface of revolution instead of triangles."""
    if getattr(sdt_surf, 'Cylinder_Rxy_Ratio', 1.0) != 1.0:
        return False
    if len(getattr(sdt_surf, 'Error_map', [])) != 0:
        return False
    znk = getattr(sdt_surf, 'ZNK', None)
    if znk is not None and np.any(np.asarray(znk) != 0):
        return False
    extra = getattr(sdt_surf, 'ExtraData', None)
    if extra is not None and np.any(np.asarray(extra) != 0):
        return False
    if str(getattr(sdt_surf, 'Solid_3d_stl', 'None')) != 'None':
        return False
    if getattr(sdt_surf, 'ShiftX', 0.0) != 0.0:
        return False
    if getattr(sdt_surf, 'ShiftY', 0.0) != 0.0:
        return False
    return True


def _compute_revolution_sag(r: float, sdt_surf) -> float:
    """Sag z(r) for a rotationally symmetric KrakenOS surface (conic +
    even-power aspheric + axicon)."""
    import math as _m
    z = 0.0
    Rc = float(getattr(sdt_surf, 'Rc', 0.0))
    k = float(getattr(sdt_surf, 'k', 0.0))
    if Rc != 0.0:
        c = 1.0 / Rc
        s2 = r * r
        in_root = 1.0 - (k + 1.0) * c * c * s2
        z = c * s2 / (1.0 + _m.sqrt(abs(in_root)))
    aspher = getattr(sdt_surf, 'AspherData', None)
    if aspher is not None:
        for i in range(1, 9):
            coeff = float(aspher[i - 1]) if i - 1 < len(aspher) else 0.0
            if coeff != 0.0:
                z += coeff * r ** (2 * i)
    axicon = float(getattr(sdt_surf, 'Axicon', 0.0))
    if axicon != 0.0:
        z += r * _m.tan(_m.radians(axicon))
    return z


def _make_occ_flat_disc(outer_radius: float, inner_radius: float = 0.0):
    """Planar disc (or annulus) as a single OpenCascade ADVANCED_FACE."""
    from OCC.Core.BRepBuilderAPI import (
        BRepBuilderAPI_MakeEdge,
        BRepBuilderAPI_MakeFace,
        BRepBuilderAPI_MakeWire,
    )
    from OCC.Core.gp import gp_Ax2, gp_Circ, gp_Dir, gp_Pnt

    center = gp_Pnt(0.0, 0.0, 0.0)
    axis = gp_Ax2(center, gp_Dir(0.0, 0.0, 1.0))
    outer_edge = BRepBuilderAPI_MakeEdge(gp_Circ(axis, float(outer_radius))).Edge()
    outer_wire = BRepBuilderAPI_MakeWire(outer_edge).Wire()
    fm = BRepBuilderAPI_MakeFace(outer_wire)
    if inner_radius > 1e-9:
        inner_edge = BRepBuilderAPI_MakeEdge(gp_Circ(axis, float(inner_radius))).Edge()
        inner_wire = BRepBuilderAPI_MakeWire(inner_edge).Wire()
        fm.Add(inner_wire)
    return fm.Face() if fm.IsDone() else None


def _make_occ_revolution_face(sdt_surf, n_profile_points: int = 64):
    """Create an OCC face by revolving the sag profile z(r).

    Flat surfaces produce a proper planar disc instead.  Curved surfaces
    (spherical, conic, aspheric, axicon) yield a single SURFACE_OF_REVOLUTION
    — one ADVANCED_FACE instead of thousands of triangles.
    """
    import math as _m
    from OCC.Core.BRepBuilderAPI import BRepBuilderAPI_MakeEdge
    from OCC.Core.BRepPrimAPI import BRepPrimAPI_MakeRevol
    from OCC.Core.GeomAPI import GeomAPI_PointsToBSpline
    from OCC.Core.TColgp import TColgp_Array1OfPnt
    from OCC.Core.gp import gp_Ax1, gp_Dir, gp_Pnt

    semi_d = float(getattr(sdt_surf, 'Diameter', 0.0)) / 2.0
    semi_in = float(getattr(sdt_surf, 'InDiameter', 0.0)) / 2.0
    if semi_d <= 0:
        return None

    Rc = float(getattr(sdt_surf, 'Rc', 0.0))
    has_aspher = np.any(np.asarray(getattr(sdt_surf, 'AspherData', np.zeros(1))) != 0)
    has_axicon = float(getattr(sdt_surf, 'Axicon', 0.0)) != 0.0

    if Rc == 0.0 and not has_aspher and not has_axicon:
        return _make_occ_flat_disc(semi_d, semi_in)

    # Sample profile in the XZ half-plane
    r_start = max(semi_in, semi_d * 1e-4)
    pts = []
    for i in range(n_profile_points + 1):
        r = r_start + (semi_d - r_start) * i / n_profile_points
        z = _compute_revolution_sag(r, sdt_surf)
        pts.append(gp_Pnt(float(r), 0.0, float(z)))

    arr = TColgp_Array1OfPnt(1, len(pts))
    for i, pt in enumerate(pts):
        arr.SetValue(i + 1, pt)
    try:
        bspline = GeomAPI_PointsToBSpline(arr, 3, 8).Curve()
        edge = BRepBuilderAPI_MakeEdge(bspline).Edge()
    except Exception:
        return None

    axis = gp_Ax1(gp_Pnt(0.0, 0.0, 0.0), gp_Dir(0.0, 0.0, 1.0))
    try:
        revol = BRepPrimAPI_MakeRevol(edge, axis, 2.0 * _m.pi)
        return revol.Shape() if revol.IsDone() else None
    except Exception:
        return None


def _numpy_mat_to_occ_trsf(mat_4x4):
    """Convert a 4x4 numpy affine matrix to gp_Trsf (rotation + translation)."""
    from OCC.Core.gp import gp_Trsf
    m = np.asarray(mat_4x4, dtype=float)
    if m.shape != (4, 4):
        return None
    trsf = gp_Trsf()
    try:
        trsf.SetValues(
            m[0, 0], m[0, 1], m[0, 2], m[0, 3],
            m[1, 0], m[1, 1], m[1, 2], m[1, 3],
            m[2, 0], m[2, 1], m[2, 2], m[2, 3],
        )
    except Exception:
        return None
    return trsf


def _numpy_mat_to_occ_gtrsf(mat_4x4):
    """Convert a 4x4 numpy affine matrix to gp_GTrsf."""
    from OCC.Core.gp import gp_GTrsf

    m = np.asarray(mat_4x4, dtype=float)
    if m.shape != (4, 4):
        return None
    trsf = gp_GTrsf()
    try:
        for row in range(3):
            for column in range(4):
                trsf.SetValue(row + 1, column + 1, float(m[row, column]))
    except Exception:
        return None
    return trsf


def _affine_from_point_sets(source_points: np.ndarray, target_points: np.ndarray, *, max_samples: int = 5000) -> np.ndarray | None:
    source = np.asarray(source_points, dtype=float)
    target = np.asarray(target_points, dtype=float)
    if source.ndim != 2 or target.ndim != 2 or source.shape != target.shape or source.shape[1] < 3:
        return None
    source = source[:, :3]
    target = target[:, :3]
    finite = np.all(np.isfinite(source), axis=1) & np.all(np.isfinite(target), axis=1)
    source = source[finite]
    target = target[finite]
    if source.shape[0] < 4:
        return None
    if source.shape[0] > max_samples:
        indices = np.linspace(0, source.shape[0] - 1, max_samples, dtype=int)
        source = source[indices]
        target = target[indices]
    design = np.column_stack([source, np.ones(source.shape[0], dtype=float)])
    try:
        coeffs, *_ = np.linalg.lstsq(design, target, rcond=None)
    except Exception:
        return None
    matrix = np.eye(4, dtype=float)
    matrix[:3, :3] = coeffs[:3, :].T
    matrix[:3, 3] = coeffs[3, :]
    return matrix


def _read_step_shape(path: Path):
    try:
        from OCC.Core.STEPControl import STEPControl_Reader
    except Exception as exc:
        raise RuntimeError(f"pythonocc-core is required for native STEP export: {exc}") from exc
    source = Path(path).expanduser()
    reader = STEPControl_Reader()
    if reader.ReadFile(str(source)) != 1:
        raise RuntimeError(f"Could not read STEP file: {source}")
    if reader.TransferRoots() <= 0:
        raise RuntimeError(f"Could not transfer STEP roots: {source}")
    shape = reader.OneShape()
    if shape.IsNull():
        raise RuntimeError(f"STEP file produced a null shape: {source}")
    return shape


def _shape_with_affine(shape, mat_4x4):
    from OCC.Core.BRepBuilderAPI import BRepBuilderAPI_GTransform

    gtrsf = _numpy_mat_to_occ_gtrsf(mat_4x4)
    if gtrsf is None:
        raise RuntimeError("Could not build OpenCascade affine transform")
    transformed = BRepBuilderAPI_GTransform(shape, gtrsf, True)
    if not transformed.IsDone():
        raise RuntimeError("OpenCascade shape transform failed")
    result = transformed.Shape()
    if result.IsNull():
        raise RuntimeError("OpenCascade shape transform produced a null shape")
    return result


def _write_meshes_to_faceted_step(
    mesh_items: list[tuple[str, object]],
    target_path: Path,
    *,
    max_facets_per_mesh: int = 4000,
) -> tuple[int, int]:
    """Write PyVista surface meshes as renderable shell-based STEP.

    This is the compatibility path for imported vendor CAD.  The earlier
    per-triangle compound produced one OPEN_SHELL/shape representation per
    face, which made downstream viewers spend a long time healing tolerances.
    Building one shell per displayed mesh keeps the file renderable in STEP
    viewers while avoiding the AP242 tessellation entities that some viewers
    import but do not draw.
    """
    try:
        from OCC.Core.BRep import BRep_Builder
        from OCC.Core.BRepBuilderAPI import BRepBuilderAPI_MakeFace, BRepBuilderAPI_MakePolygon
        from OCC.Core.IFSelect import IFSelect_RetDone
        from OCC.Core.Interface import Interface_Static
        from OCC.Core.STEPControl import STEPControl_AsIs, STEPControl_Writer
        from OCC.Core.TopoDS import TopoDS_Compound, TopoDS_Shell
        from OCC.Core.gp import gp_Pnt
    except Exception as exc:
        raise RuntimeError(f"pythonocc-core is required for STEP export: {exc}") from exc

    target_path = Path(target_path).expanduser()
    target_path.parent.mkdir(parents=True, exist_ok=True)

    compound = TopoDS_Compound()
    builder = BRep_Builder()
    builder.MakeCompound(compound)
    mesh_count = 0
    triangle_count = 0

    for _label, mesh in mesh_items:
        prepared_mesh = _mesh_points_and_triangles_for_step(
            mesh,
            max_facets_per_mesh=max_facets_per_mesh,
        )
        if prepared_mesh is None:
            continue
        points, triangles = prepared_mesh
        shell = TopoDS_Shell()
        builder.MakeShell(shell)
        added_for_mesh = 0
        for a, b, c in triangles:
            tri_points = points[[int(a) - 1, int(b) - 1, int(c) - 1], :3]
            polygon = BRepBuilderAPI_MakePolygon()
            for x, y, z in tri_points:
                polygon.Add(gp_Pnt(float(x), float(y), float(z)))
            polygon.Close()
            if not polygon.IsDone():
                continue
            face = BRepBuilderAPI_MakeFace(polygon.Wire())
            if not face.IsDone():
                continue
            builder.Add(shell, face.Face())
            added_for_mesh += 1
        if added_for_mesh:
            builder.Add(compound, shell)
            mesh_count += 1
            triangle_count += added_for_mesh

    if triangle_count <= 0:
        raise RuntimeError("No valid 3D surface triangles were available for STEP export")

    writer = STEPControl_Writer()
    try:
        Interface_Static.SetCVal("write.step.unit", "MM")
    except Exception:
        pass
    try:
        stdout_fd = os.dup(1)
        stderr_fd = os.dup(2)
        with open(os.devnull, "w", encoding="utf-8") as devnull:
            os.dup2(devnull.fileno(), 1)
            os.dup2(devnull.fileno(), 2)
            writer.Transfer(compound, STEPControl_AsIs)
            status = writer.Write(str(target_path))
    except Exception:
        writer.Transfer(compound, STEPControl_AsIs)
        status = writer.Write(str(target_path))
    finally:
        for src_fd, dst_fd in ((locals().get("stdout_fd"), 1), (locals().get("stderr_fd"), 2)):
            if src_fd is None:
                continue
            try:
                os.dup2(int(src_fd), dst_fd)
                os.close(int(src_fd))
            except Exception:
                pass
    if status != IFSelect_RetDone or not target_path.exists() or target_path.stat().st_size <= 0:
        raise RuntimeError("STEP writer failed")
    return mesh_count, triangle_count


def _mesh_points_and_triangles_for_step(
    mesh,
    *,
    max_facets_per_mesh: int,
) -> tuple[np.ndarray, np.ndarray] | None:
    if mesh is None:
        return None
    try:
        surface = mesh.extract_surface(algorithm="dataset_surface").triangulate().clean()
        face_count = int(getattr(surface, "n_cells", 0))
        if face_count > max_facets_per_mesh > 0:
            reduction = 1.0 - (float(max_facets_per_mesh) / float(face_count))
            try:
                surface = surface.decimate_pro(
                    min(max(reduction, 0.0), 0.98),
                    preserve_topology=False,
                ).triangulate().clean()
            except Exception:
                # Some vendor STL meshes have non-manifold regions where VTK
                # decimation fails. Exporting the cleaned triangles is still
                # safer than falling back to per-triangle BRep shells.
                surface = surface.triangulate().clean()
        points = np.asarray(surface.points, dtype=float)
        faces = np.asarray(surface.faces, dtype=int)
    except Exception:
        return None

    if points.ndim != 2 or points.shape[0] < 3 or points.shape[1] < 3 or faces.size == 0:
        return None

    triangles: list[tuple[int, int, int]] = []
    cursor = 0
    while cursor < int(faces.size):
        vertex_count = int(faces[cursor])
        ids = [int(value) for value in faces[cursor + 1: cursor + 1 + vertex_count]]
        cursor += vertex_count + 1
        if vertex_count < 3:
            continue
        for tri_index in range(1, vertex_count - 1):
            tri = (ids[0], ids[tri_index], ids[tri_index + 1])
            tri_points = points[list(tri), :3]
            if not np.all(np.isfinite(tri_points)):
                continue
            area2 = float(np.linalg.norm(np.cross(tri_points[1] - tri_points[0], tri_points[2] - tri_points[0])))
            if area2 <= 1e-12:
                continue
            # Keep triangle indices 1-based so both STEP writers and validators
            # can use them without another conversion pass.
            triangles.append((tri[0] + 1, tri[1] + 1, tri[2] + 1))

    if not triangles:
        return None
    return points[:, :3], np.asarray(triangles, dtype=int)


def _write_step_with_analytic_surfaces(
    system,
    rows: list,
    edge_mesh_items: list[tuple[str, object]],
    target_path: Path,
    *,
    max_edge_facets: int = 300,
    profile_points: int = 64,
) -> tuple[int, int, int]:
    """Write STEP using analytic revolution surfaces for optical elements.

    Optical surfaces that are rotationally symmetric (spherical, conic,
    aspheric, axicon) are exported as a single SURFACE_OF_REVOLUTION face
    each.  Edge geometry and imported meshes use faceted fallback with
    aggressive decimation.

    Returns (analytic_count, faceted_mesh_count, triangle_count).
    """
    try:
        from OCC.Core.BRep import BRep_Builder
        from OCC.Core.BRepBuilderAPI import (
            BRepBuilderAPI_MakeFace,
            BRepBuilderAPI_MakePolygon,
            BRepBuilderAPI_Transform,
        )
        from OCC.Core.IFSelect import IFSelect_RetDone
        from OCC.Core.Interface import Interface_Static
        from OCC.Core.STEPControl import STEPControl_AsIs, STEPControl_Writer
        from OCC.Core.TopoDS import TopoDS_Compound
        from OCC.Core.gp import gp_Pnt
    except Exception as exc:
        raise RuntimeError(f"pythonocc-core is required for STEP export: {exc}") from exc

    target_path = Path(target_path).expanduser()
    target_path.parent.mkdir(parents=True, exist_ok=True)

    compound = TopoDS_Compound()
    builder = BRep_Builder()
    builder.MakeCompound(compound)

    sdt = getattr(system, 'SDT', [])
    trans_2a = getattr(system, 'TRANS_2A', [])

    analytic_count = 0
    faceted_mesh_count = 0
    tri_count = 0

    # --- Phase 1: analytic optical surfaces ---
    n_surf = min(len(sdt), len(rows))
    for j in range(n_surf):
        surf_label = getattr(rows[j], 'surface', '')
        if surf_label in {"Object", "Image"}:
            continue
        surf = sdt[j]
        if not getattr(surf, 'Drawing', 1):
            continue
        if float(getattr(surf, 'Diameter', 0)) <= 0:
            continue
        if not _is_surface_revolution_compatible(surf):
            continue

        occ_shape = _make_occ_revolution_face(surf, profile_points)
        if occ_shape is None:
            continue

        if j < len(trans_2a):
            trsf = _numpy_mat_to_occ_trsf(trans_2a[j])
            if trsf is not None:
                try:
                    occ_shape = BRepBuilderAPI_Transform(occ_shape, trsf, True).Shape()
                except Exception:
                    continue

        builder.Add(compound, occ_shape)
        analytic_count += 1

    # --- Phase 2: faceted edge geometry + extras ---
    for _label, mesh in edge_mesh_items:
        if mesh is None:
            continue
        try:
            surface = mesh.extract_surface(algorithm="dataset_surface").triangulate().clean()
            fc = int(getattr(surface, "n_cells", 0))
            if fc > max_edge_facets > 0:
                reduction = 1.0 - float(max_edge_facets) / float(fc)
                try:
                    surface = surface.decimate_pro(
                        min(max(reduction, 0.0), 0.98),
                        preserve_topology=True,
                    ).triangulate().clean()
                except Exception:
                    pass
            points = np.asarray(surface.points, dtype=float)
            faces = np.asarray(surface.faces, dtype=int)
        except Exception:
            continue
        if points.ndim != 2 or points.shape[0] < 3 or points.shape[1] < 3 or faces.size == 0:
            continue
        added = 0
        cursor = 0
        while cursor < int(faces.size):
            vc = int(faces[cursor])
            ids = [int(v) for v in faces[cursor + 1: cursor + 1 + vc]]
            cursor += vc + 1
            if vc < 3:
                continue
            for ti in range(1, vc - 1):
                tri = (ids[0], ids[ti], ids[ti + 1])
                tp = points[list(tri), :3]
                if not np.all(np.isfinite(tp)):
                    continue
                if float(np.linalg.norm(np.cross(tp[1] - tp[0], tp[2] - tp[0]))) <= 1e-12:
                    continue
                polygon = BRepBuilderAPI_MakePolygon()
                for x, y, z in tp:
                    polygon.Add(gp_Pnt(float(x), float(y), float(z)))
                polygon.Close()
                if not polygon.IsDone():
                    continue
                face = BRepBuilderAPI_MakeFace(polygon.Wire())
                if not face.IsDone():
                    continue
                builder.Add(compound, face.Face())
                added += 1
        if added:
            faceted_mesh_count += 1
            tri_count += added

    if analytic_count + tri_count <= 0:
        raise RuntimeError("No valid geometry available for STEP export")

    writer = STEPControl_Writer()
    try:
        Interface_Static.SetCVal("write.step.unit", "MM")
    except Exception:
        pass
    try:
        stdout_fd = os.dup(1)
        stderr_fd = os.dup(2)
        with open(os.devnull, "w", encoding="utf-8") as devnull:
            os.dup2(devnull.fileno(), 1)
            os.dup2(devnull.fileno(), 2)
            writer.Transfer(compound, STEPControl_AsIs)
            status = writer.Write(str(target_path))
    except Exception:
        writer.Transfer(compound, STEPControl_AsIs)
        status = writer.Write(str(target_path))
    finally:
        for src_fd, dst_fd in ((locals().get("stdout_fd"), 1), (locals().get("stderr_fd"), 2)):
            if src_fd is None:
                continue
            try:
                os.dup2(int(src_fd), dst_fd)
                os.close(int(src_fd))
            except Exception:
                pass
    if status != IFSelect_RetDone or not target_path.exists() or target_path.stat().st_size <= 0:
        raise RuntimeError("STEP writer failed")
    return analytic_count, faceted_mesh_count, tri_count


def _write_step_with_cad_shapes_and_rays(
    system,
    rows: list,
    cad_shape_items: list[tuple[str, object]],
    ray_polylines: list[np.ndarray],
    target_path: Path,
    *,
    profile_points: int = 64,
    ray_tube_radius_mm: float | None = None,
    progress_callback=None,
) -> tuple[int, int, int]:
    """Write analytic optics, imported CAD shapes, and visible ray tubes.

    Imported CAD is preserved as native STEP BRep geometry and transformed into
    the same placement used by the UI. Rays are written as thin solid tubes
    rather than wire-only curves because FreeCAD and several mechanical viewers
    can import STEP wires without rendering them as visible objects.
    """
    try:
        from OCC.Core.BRep import BRep_Builder
        from OCC.Core.BRepBuilderAPI import (
            BRepBuilderAPI_Transform,
        )
        from OCC.Core.BRepPrimAPI import BRepPrimAPI_MakeCylinder
        from OCC.Core.IFSelect import IFSelect_RetDone
        from OCC.Core.Interface import Interface_Static
        from OCC.Core.STEPControl import STEPControl_AsIs, STEPControl_Writer
        from OCC.Core.TopoDS import TopoDS_Compound
        from OCC.Core.gp import gp_Ax2, gp_Dir, gp_Pnt
    except Exception as exc:
        raise RuntimeError(f"pythonocc-core is required for STEP export: {exc}") from exc

    target_path = Path(target_path).expanduser()
    target_path.parent.mkdir(parents=True, exist_ok=True)

    compound = TopoDS_Compound()
    builder = BRep_Builder()
    builder.MakeCompound(compound)

    sdt = getattr(system, 'SDT', [])
    trans_2a = getattr(system, 'TRANS_2A', [])
    analytic_count = 0
    cad_count = 0
    ray_count = 0

    valid_ray_points: list[np.ndarray] = []
    finite_ray_points: list[np.ndarray] = []
    for points in ray_polylines:
        pts = np.asarray(points, dtype=float)
        if pts.ndim != 2 or pts.shape[0] < 2 or pts.shape[1] < 3:
            continue
        finite_pts = pts[np.all(np.isfinite(pts[:, :3]), axis=1), :3]
        if finite_pts.shape[0] >= 2:
            valid_ray_points.append(pts[:, :3])
            finite_ray_points.append(finite_pts)
    if ray_tube_radius_mm is None:
        if finite_ray_points:
            all_pts = np.vstack(finite_ray_points)
            span = float(np.linalg.norm(np.ptp(all_pts, axis=0)))
            ray_tube_radius_mm = max(0.08, min(0.5, span * 0.00075))
        else:
            ray_tube_radius_mm = 0.1
    ray_tube_radius_mm = max(1e-4, float(ray_tube_radius_mm))

    n_surf = min(len(sdt), len(rows))
    if progress_callback is not None:
        progress_callback("Adding analytic optical surfaces", 1, 5)
    for j in range(n_surf):
        surf_label = getattr(rows[j], 'surface', '')
        if surf_label in {"Object", "Image"}:
            continue
        surf = sdt[j]
        if not getattr(surf, 'Drawing', 1):
            continue
        if float(getattr(surf, 'Diameter', 0)) <= 0:
            continue
        if not _is_surface_revolution_compatible(surf):
            continue
        occ_shape = _make_occ_revolution_face(surf, profile_points)
        if occ_shape is None:
            continue
        if j < len(trans_2a):
            trsf = _numpy_mat_to_occ_trsf(trans_2a[j])
            if trsf is not None:
                try:
                    occ_shape = BRepBuilderAPI_Transform(occ_shape, trsf, True).Shape()
                except Exception:
                    continue
        builder.Add(compound, occ_shape)
        analytic_count += 1

    if progress_callback is not None:
        progress_callback("Adding native STEP CAD", 2, 5)
    for _label, shape in cad_shape_items:
        if shape is None:
            continue
        try:
            if not shape.IsNull():
                builder.Add(compound, shape)
                cad_count += 1
        except Exception:
            continue

    if progress_callback is not None:
        progress_callback("Adding ray envelope tubes", 3, 5)
    for points in valid_ray_points:
        pts = np.asarray(points, dtype=float)
        added_segments = 0
        for start, end in zip(pts[:-1], pts[1:]):
            if not np.all(np.isfinite(start)) or not np.all(np.isfinite(end)):
                continue
            delta = end - start
            length = float(np.linalg.norm(delta))
            if length <= 1e-9:
                continue
            direction = delta / length
            cylinder = BRepPrimAPI_MakeCylinder(
                gp_Ax2(
                    gp_Pnt(float(start[0]), float(start[1]), float(start[2])),
                    gp_Dir(float(direction[0]), float(direction[1]), float(direction[2])),
                ),
                ray_tube_radius_mm,
                length,
            )
            try:
                ray_shape = cylinder.Shape()
            except Exception:
                continue
            try:
                if ray_shape.IsNull():
                    continue
            except Exception:
                pass
            builder.Add(compound, ray_shape)
            added_segments += 1
        if added_segments <= 0:
            continue
        ray_count += 1

    if analytic_count + cad_count + ray_count <= 0:
        raise RuntimeError("No valid geometry available for STEP export")

    writer = STEPControl_Writer()
    try:
        Interface_Static.SetCVal("write.step.unit", "MM")
    except Exception:
        pass
    if progress_callback is not None:
        progress_callback("Writing STEP file", 4, 5)
    try:
        stdout_fd = os.dup(1)
        stderr_fd = os.dup(2)
        with open(os.devnull, "w", encoding="utf-8") as devnull:
            os.dup2(devnull.fileno(), 1)
            os.dup2(devnull.fileno(), 2)
            writer.Transfer(compound, STEPControl_AsIs)
            status = writer.Write(str(target_path))
    except Exception:
        writer.Transfer(compound, STEPControl_AsIs)
        status = writer.Write(str(target_path))
    finally:
        for src_fd, dst_fd in ((locals().get("stdout_fd"), 1), (locals().get("stderr_fd"), 2)):
            if src_fd is None:
                continue
            try:
                os.dup2(int(src_fd), dst_fd)
                os.close(int(src_fd))
            except Exception:
                pass
    if status != IFSelect_RetDone or not target_path.exists() or target_path.stat().st_size <= 0:
        raise RuntimeError("STEP writer failed")
    if progress_callback is not None:
        progress_callback("STEP file complete", 5, 5)
    return analytic_count, cad_count, ray_count


def _finite_polyline_points(polyline: np.ndarray) -> np.ndarray:
    pts = np.asarray(polyline, dtype=float)
    if pts.ndim != 2 or pts.shape[0] < 2 or pts.shape[1] < 3:
        return np.empty((0, 3), dtype=float)
    pts = pts[:, :3]
    return pts[np.all(np.isfinite(pts), axis=1)]


def _convex_hull_indices_2d(points_2d: np.ndarray, *, tolerance: float = 1e-9) -> set[int]:
    pts = np.asarray(points_2d, dtype=float)
    if pts.ndim != 2 or pts.shape[0] == 0 or pts.shape[1] < 2:
        return set()
    finite_mask = np.all(np.isfinite(pts[:, :2]), axis=1)
    if not np.any(finite_mask):
        return set()
    original_indices = np.flatnonzero(finite_mask)
    pts = pts[finite_mask, :2]
    if pts.shape[0] <= 2:
        return {int(index) for index in original_indices}
    span = np.ptp(pts, axis=0)
    if float(np.linalg.norm(span)) <= tolerance:
        return {int(original_indices[0])}

    order = sorted(range(pts.shape[0]), key=lambda idx: (float(pts[idx, 0]), float(pts[idx, 1]), idx))

    def cross(o: int, a: int, b: int) -> float:
        return float(
            (pts[a, 0] - pts[o, 0]) * (pts[b, 1] - pts[o, 1])
            - (pts[a, 1] - pts[o, 1]) * (pts[b, 0] - pts[o, 0])
        )

    lower: list[int] = []
    for idx in order:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], idx) <= tolerance:
            lower.pop()
        lower.append(idx)
    upper: list[int] = []
    for idx in reversed(order):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], idx) <= tolerance:
            upper.pop()
        upper.append(idx)
    hull_local = lower[:-1] + upper[:-1]
    if not hull_local:
        return {int(original_indices[order[0]]), int(original_indices[order[-1]])}
    return {int(original_indices[idx]) for idx in hull_local}


def _ray_group_envelope_indices(polylines: list[np.ndarray]) -> set[int]:
    """Return boundary-ray indices for one launch group.

    STEP export is for mechanical envelope review, not optical debugging. The
    useful geometry is therefore the outside of the traced bundle. We select
    convex-hull rays in launch-position, launch-direction, and terminal-position
    spaces so meridional fans collapse to two edge rays, cross fans to four
    edge rays, and split/non-sequential paths still keep branch extremes.
    """
    starts: list[np.ndarray] = []
    ends: list[np.ndarray] = []
    directions: list[np.ndarray] = []
    point_counts: list[int] = []
    valid_indices: list[int] = []
    for index, polyline in enumerate(polylines):
        finite = _finite_polyline_points(polyline)
        if finite.shape[0] < 2:
            continue
        deltas = np.diff(finite, axis=0)
        lengths = np.linalg.norm(deltas, axis=1)
        direction = np.zeros(3, dtype=float)
        for delta, length in zip(deltas, lengths):
            if float(length) > 1e-9:
                direction = delta / float(length)
                break
        starts.append(finite[0])
        ends.append(finite[-1])
        directions.append(direction)
        point_counts.append(int(finite.shape[0]))
        valid_indices.append(index)

    if not valid_indices:
        return set()
    if len(valid_indices) <= 4:
        return set(valid_indices)

    candidate_local_indices = list(range(len(valid_indices)))
    counts = np.asarray(point_counts, dtype=int)
    if counts.size:
        max_count = int(np.max(counts))
        min_count = int(np.min(counts))
        longest = [idx for idx, count in enumerate(counts) if int(count) == max_count]
        if max_count > min_count and len(longest) >= max(2, int(np.ceil(0.5 * len(valid_indices)))):
            # In sequential layouts, clipped rays usually have fewer recorded
            # hit points than rays reaching the image/analysis plane. For
            # mechanical envelope export, prefer the through-going envelope
            # when it is the dominant ray population.
            candidate_local_indices = longest
    if len(candidate_local_indices) <= 4:
        return {int(valid_indices[idx]) for idx in candidate_local_indices}

    selected: set[int] = set()
    spaces = (
        np.asarray([starts[idx] for idx in candidate_local_indices], dtype=float)[:, :2],
        np.asarray([directions[idx] for idx in candidate_local_indices], dtype=float)[:, :2],
        np.asarray([ends[idx] for idx in candidate_local_indices], dtype=float)[:, :2],
    )
    for points in spaces:
        for local_idx in _convex_hull_indices_2d(points):
            if 0 <= local_idx < len(candidate_local_indices):
                selected.add(int(valid_indices[candidate_local_indices[local_idx]]))

    if not selected:
        start_arr = np.asarray([starts[idx] for idx in candidate_local_indices], dtype=float)
        end_arr = np.asarray([ends[idx] for idx in candidate_local_indices], dtype=float)
        radii = np.linalg.norm(start_arr[:, :2] - np.mean(start_arr[:, :2], axis=0), axis=1)
        if float(np.ptp(radii)) <= 1e-9:
            radii = np.linalg.norm(end_arr[:, :2] - np.mean(end_arr[:, :2], axis=0), axis=1)
        selected.add(int(valid_indices[candidate_local_indices[int(np.argmin(radii))]]))
        selected.add(int(valid_indices[candidate_local_indices[int(np.argmax(radii))]]))
    return selected


def _ray_bundle_envelope_polylines(polylines: list[np.ndarray], rays_per_group: int | None) -> list[np.ndarray]:
    clean_polylines: list[np.ndarray] = []
    for polyline in polylines:
        pts = np.asarray(polyline, dtype=float)
        if pts.ndim != 2 or pts.shape[0] < 2 or pts.shape[1] < 3:
            continue
        clean_polylines.append(pts[:, :3].copy())
    if len(clean_polylines) <= 4:
        return clean_polylines
    group_size = int(rays_per_group or 0)
    if group_size <= 0:
        group_size = len(clean_polylines)

    selected_global: set[int] = set()
    for start in range(0, len(clean_polylines), group_size):
        group = clean_polylines[start:start + group_size]
        for local_idx in _ray_group_envelope_indices(group):
            selected_global.add(start + int(local_idx))
    if not selected_global:
        return clean_polylines
    envelope: list[np.ndarray] = []
    seen: set[tuple[tuple[int, int], tuple[float, ...]]] = set()
    for index in sorted(selected_global):
        polyline = clean_polylines[index]
        finite = _finite_polyline_points(polyline)
        key_values = tuple(np.round(finite.ravel(), decimals=9).tolist())
        key = ((int(finite.shape[0]), int(finite.shape[1]) if finite.ndim == 2 else 0), key_values)
        if key in seen:
            continue
        seen.add(key)
        envelope.append(polyline)
    return envelope


class Kraken3DInspector(tk.Toplevel):
    def __init__(self, editor: "KrakenLayoutEditor") -> None:
        _load_3d_backends()
        super().__init__(editor)
        self.editor = editor
        self.available = False
        self.unavailable_reason = ""
        self.title("KrakenOS 3D Inspector")
        self.geometry("1100x780")
        self.minsize(720, 520)
        self.protocol("WM_DELETE_WINDOW", self._on_close)

        self._renderer = None
        self._vtk_widget = None
        self._vtk_interactor = None
        self._orientation_widget = None
        self._picker = None
        self._picked_row_index: int | None = None
        self._actor_row_map: dict[str, int] = {}
        self._row_actor_map: dict[int, list[str]] = {}
        self._actor_ray_map: dict[str, int] = {}
        self._ray_actor_map: dict[int, list[str]] = {}
        self._actor_step_map: dict[str, str] = {}
        self._step_actor_map: dict[str, list[str]] = {}
        self._picked_step_label: str | None = None
        self._picked_ray_index: int | None = None
        self._hover_step_actor = None
        self._hover_step_outline_actor = None
        self._hover_step_cell_key = None
        self._camera_preset = "iso"
        self._stl_placement_row_index: int | None = None
        self._stl_placement_dirty = False
        self._center_row_to_ray_mode = False
        self._center_row_to_ray_index: int | None = None
        self._source_target_pick_mode = False
        self.stl_axis_var = tk.StringVar(value="+Z")
        self.show_rays_var = tk.BooleanVar(value=True)
        self.status_var = tk.StringVar(value="3D inspector ready")

        self.columnconfigure(0, weight=1)
        self.rowconfigure(2, weight=1)

        host = ttk.Frame(self, padding=8)
        host.grid(row=2, column=0, sticky="nsew")
        host.columnconfigure(0, weight=1)
        host.rowconfigure(0, weight=1)

        if vtkTkRenderWindowInteractor is None or vtkRenderer is None:
            self.unavailable_reason = _VTK_TK_UNAVAILABLE_REASON or "Embedded VTK/Tk viewer unavailable."
            self.status_var.set(self.unavailable_reason)
            return

        try:
            toolbar = ttk.Frame(self, padding=(8, 8, 8, 0))
            toolbar.grid(row=0, column=0, sticky="ew")
            ttk.Button(toolbar, text="Refresh", command=self.refresh_from_editor).pack(side="left")
            ttk.Button(toolbar, text="Iso", command=lambda: self.set_camera_preset("iso")).pack(side="left", padx=(8, 0))
            ttk.Button(toolbar, text="ZY", command=lambda: self.set_camera_preset("zy")).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="XY", command=lambda: self.set_camera_preset("xy")).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="XZ", command=lambda: self.set_camera_preset("xz")).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Bottom", command=lambda: self.set_camera_preset("bottom")).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Z -90", command=lambda: self.editor.rotate_selected_step_z(-90.0)).pack(side="left", padx=(10, 0))
            ttk.Button(toolbar, text="Z +90", command=lambda: self.editor.rotate_selected_step_z(90.0)).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="X 180", command=lambda: self.editor.rotate_selected_step_x(180.0)).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Axis LED", command=lambda: self.editor.start_step_axis_pick("led")).pack(side="left", padx=(8, 0))
            ttk.Button(toolbar, text="Obj->LED", command=self.editor.start_led_object_edge_pick).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Axis Cam", command=lambda: self.editor.start_step_axis_pick("camera")).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Axis Lens", command=lambda: self.editor.start_step_axis_pick("lens")).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Export STEP", command=self.editor.export_3d_step).pack(side="left", padx=(8, 0))
            ttk.Button(toolbar, text="Center Row->Ray", command=self.start_center_row_to_ray).pack(side="left", padx=(8, 0))
            ttk.Button(toolbar, text="Faces...", command=self.open_selected_optical_faces).pack(side="left", padx=(4, 0))
            ttk.Button(toolbar, text="Source Target", command=self.start_source_target_pick).pack(side="left", padx=(4, 0))
            ttk.Checkbutton(
                toolbar,
                text="Show rays",
                variable=self.show_rays_var,
                command=self.refresh_from_editor,
            ).pack(side="left", padx=(12, 0))
            ttk.Label(
                toolbar,
                text="Click a surface or ray in 3D to inspect it",
                foreground="#4b5563",
            ).pack(side="right")

            stl_toolbar = ttk.Frame(self, padding=(8, 4, 8, 0))
            stl_toolbar.grid(row=1, column=0, sticky="ew")
            ttk.Label(stl_toolbar, text="CAD/STL placement").pack(side="left")
            ttk.Combobox(
                stl_toolbar,
                textvariable=self.stl_axis_var,
                state="readonly",
                values=tuple(STL_AXIS_TO_LAYOUT_Z_TILTS.keys()),
                width=5,
            ).pack(side="left", padx=(8, 0))
            ttk.Button(stl_toolbar, text="Fit Axis", command=self.fit_selected_stl_axis).pack(side="left", padx=(4, 0))
            for label, axis, delta in (
                ("X -90", "x", -90.0),
                ("X +90", "x", 90.0),
                ("Y -90", "y", -90.0),
                ("Y +90", "y", 90.0),
                ("Z -90", "z", -90.0),
                ("Z +90", "z", 90.0),
            ):
                ttk.Button(
                    stl_toolbar,
                    text=label,
                    command=lambda a=axis, d=delta: self.rotate_selected_stl_pose(a, d),
                ).pack(side="left", padx=(4, 0))
            ttk.Button(stl_toolbar, text="Center X/Y", command=self.center_selected_stl_xy).pack(side="left", padx=(8, 0))
            ttk.Button(stl_toolbar, text="Min Z On Row", command=self.place_selected_stl_front_on_row).pack(side="left", padx=(4, 0))
            ttk.Button(stl_toolbar, text="Done -> 2D", command=self.finish_stl_placement).pack(side="left", padx=(8, 0))
            ttk.Label(
                stl_toolbar,
                text="Select a CAD/STL solid row, then use these controls while watching the 3D view.",
                foreground="#4b5563",
            ).pack(side="right")

            _prepare_vtk_tk_widget(host)
            self._vtk_widget = vtkTkRenderWindowInteractor(host, width=1100, height=720)
            self._vtk_widget.grid(row=0, column=0, sticky="nsew")
            render_window = self._vtk_widget.GetRenderWindow()
            self._renderer = vtkRenderer()
            render_window.AddRenderer(self._renderer)
            self._renderer.SetBackground(1.0, 1.0, 1.0)

            self._vtk_interactor = render_window.GetInteractor()
            if self._vtk_interactor is not None:
                self._vtk_interactor.AddObserver("LeftButtonPressEvent", self._on_left_button_press)
                self._vtk_interactor.AddObserver("MouseMoveEvent", self._on_mouse_move)

            if vtkCellPicker is not None:
                self._picker = vtkCellPicker()
                self._picker.SetTolerance(0.0015)

            if vtkOrientationMarkerWidget is not None and vtkAxesActor is not None and self._vtk_interactor is not None:
                axes = vtkAxesActor()
                self._orientation_widget = vtkOrientationMarkerWidget()
                self._orientation_widget.SetOrientationMarker(axes)
                self._orientation_widget.SetInteractor(self._vtk_interactor)
                self._orientation_widget.SetViewport(0.0, 0.0, 0.18, 0.18)
                self._orientation_widget.SetEnabled(1)
                self._orientation_widget.InteractiveOff()

            self._vtk_widget.Initialize()
            ttk.Label(self, textvariable=self.status_var, padding=(8, 0, 8, 8)).grid(row=3, column=0, sticky="ew")
            self.available = True
        except Exception as exc:
            self.unavailable_reason = _short_error_message(exc)
            self.status_var.set(f"Embedded 3D unavailable: {self.unavailable_reason}")
            try:
                host.destroy()
            except Exception:
                pass

    @staticmethod
    def _actor_key(actor) -> str | None:
        if actor is None:
            return None
        try:
            return str(actor.GetAddressAsString(""))
        except Exception:
            return str(id(actor))

    @staticmethod
    def _surface_color(surface) -> tuple[float, float, float]:
        absorb_color = (10 / 256.0, 23 / 256.0, 24 / 256.0)
        mirror_color = (189 / 256.0, 189 / 256.0, 189 / 256.0)
        glass_color = (12 / 256.0, 238 / 256.0, 246 / 256.0)
        try:
            color = tuple(float(v) for v in surface.Color)
            if len(color) == 3 and any(abs(v) > 1e-9 for v in color):
                return color
        except Exception:
            pass
        glass = str(getattr(surface, "Glass", "") or "").upper()
        if glass == "MIRROR":
            return mirror_color
        if glass == "ABSORB":
            return absorb_color
        return glass_color

    @staticmethod
    def _mesh_with_transform(poly, transform) -> pv.DataSet | None:
        try:
            mesh = pv.wrap(poly)
        except Exception:
            return None
        try:
            mesh = mesh.extract_surface(algorithm="dataset_surface")
        except Exception:
            pass
        try:
            mesh = mesh.copy(deep=True)
        except Exception:
            return None
        try:
            pts = np.asarray(mesh.points, dtype=float)
        except Exception:
            return None
        if pts.size == 0:
            return None
        # Kraken's SYSTEM.AAA blocks are already in display/world coordinates.
        # TRANS_2A is for tracing into local surface coordinates; applying it
        # here doubles the axial positions and moves optical markers away from
        # imported STEP hardware.
        return mesh

    def _set_row_highlight(self, row_index: int | None) -> None:
        if row_index == self._picked_row_index:
            return
        if self._renderer is None:
            self._picked_row_index = row_index
            return
        collection = self._renderer.GetActors()
        collection.InitTraversal()
        for _ in range(collection.GetNumberOfItems()):
            actor = collection.GetNextActor()
            key = self._actor_key(actor)
            if key is not None and key in self._actor_step_map:
                continue
            prop = actor.GetProperty()
            if prop is None:
                continue
            actor_row_index = self._actor_row_map.get(key) if key is not None else None
            if row_index is not None and actor_row_index == row_index:
                prop.SetEdgeVisibility(1)
                prop.SetEdgeColor(1.0, 0.55, 0.05)
                prop.SetLineWidth(2.0)
            else:
                prop.SetEdgeVisibility(0)
                prop.SetLineWidth(1.0)
        self._picked_row_index = row_index

    def highlight_row(self, row_index: int | None) -> None:
        self._set_row_highlight(row_index)
        self.render()

    def _set_ray_highlight(self, ray_index: int | None) -> None:
        if ray_index == self._picked_ray_index:
            return
        if self._renderer is None:
            self._picked_ray_index = ray_index
            return
        collection = self._renderer.GetActors()
        collection.InitTraversal()
        for _ in range(collection.GetNumberOfItems()):
            actor = collection.GetNextActor()
            actor_key = self._actor_key(actor)
            actor_ray_index = self._actor_ray_map.get(actor_key) if actor_key is not None else None
            if actor_ray_index is None:
                continue
            self._set_ray_actor_selected(actor, bool(ray_index is not None and actor_ray_index == ray_index))
        self._picked_ray_index = ray_index

    def _add_mesh_actor(
        self,
        mesh,
        *,
        color: tuple[float, float, float],
        opacity: float = 1.0,
        pick_row_index: int | None = None,
        pick_step_label: str | None = None,
        line_width: float = 1.0,
        wireframe: bool = False,
        flat_shading: bool = False,
    ) -> None:
        if self._renderer is None or vtkActor is None or vtkDataSetMapper is None:
            return
        mapper = vtkDataSetMapper()
        mapper.SetInputData(mesh)
        actor = vtkActor()
        actor.SetMapper(mapper)
        prop = actor.GetProperty()
        prop.SetColor(*color)
        prop.SetOpacity(opacity)
        prop.SetLineWidth(line_width)
        if wireframe:
            prop.SetRepresentationToWireframe()
        else:
            if flat_shading:
                prop.SetInterpolationToFlat()
                prop.SetSpecular(0.0)
                prop.SetDiffuse(0.15)
                prop.SetAmbient(0.85)
            else:
                prop.SetInterpolationToPhong()
                prop.SetSpecular(0.18)
                prop.SetSpecularPower(12.0)
        try:
            prop.BackfaceCullingOn()
        except Exception:
            pass
        if pick_row_index is None and pick_step_label is None:
            actor.PickableOff()
        else:
            actor_key = self._actor_key(actor)
            if actor_key is not None and pick_row_index is not None:
                self._actor_row_map[actor_key] = pick_row_index
                self._row_actor_map.setdefault(pick_row_index, []).append(actor_key)
            if actor_key is not None and pick_step_label is not None:
                step_label = str(pick_step_label)
                self._actor_step_map[actor_key] = step_label
                self._step_actor_map.setdefault(step_label, []).append(actor_key)
        self._renderer.AddActor(actor)

    def _set_step_highlight(self, step_label: str | None) -> None:
        if step_label == self._picked_step_label:
            return
        if self._renderer is None:
            self._picked_step_label = step_label
            return
        collection = self._renderer.GetActors()
        collection.InitTraversal()
        for _ in range(collection.GetNumberOfItems()):
            actor = collection.GetNextActor()
            actor_key = self._actor_key(actor)
            actor_step = self._actor_step_map.get(actor_key) if actor_key is not None else None
            if actor_step is None:
                continue
            self._set_step_actor_selected(actor, bool(step_label is not None and actor_step == step_label))
        self._picked_step_label = step_label
        self.render()

    def _add_ray_actor(self, mesh, *, radius: float, color: tuple[float, float, float], ray_index: int | None = None) -> None:
        if self._renderer is None or vtkActor is None or vtkDataSetMapper is None:
            return
        actor = vtkActor()
        mapper = vtkDataSetMapper()
        mapper.SetInputData(mesh)
        actor.SetMapper(mapper)
        actor.GetProperty().SetLineWidth(1.2)
        actor.GetProperty().SetColor(*color)
        actor.GetProperty().SetOpacity(0.9)
        if ray_index is None:
            actor.PickableOff()
        else:
            actor_key = self._actor_key(actor)
            if actor_key is not None:
                self._actor_ray_map[actor_key] = int(ray_index)
                self._ray_actor_map.setdefault(int(ray_index), []).append(actor_key)
            actor.PickableOn()
        self._renderer.AddActor(actor)

    @staticmethod
    def _face_role_marker_scale(marker: OpticalSolidFaceMarker, scene_radius: float) -> float:
        face_span = np.sqrt(max(float(marker.area_mm2), 1.0))
        lower = max(float(scene_radius) * 0.025, 1.0)
        upper = max(float(scene_radius) * 0.12, lower)
        return float(np.clip(face_span * 0.28, lower, upper))

    def _add_face_role_marker_actor(self, marker: OpticalSolidFaceMarker, *, scene_radius: float) -> bool:
        if pv is None:
            return False
        try:
            start = np.asarray(marker.centroid, dtype=float)
            normal = np.asarray(marker.normal, dtype=float)
            if start.size < 3 or normal.size < 3:
                return False
            normal_norm = float(np.linalg.norm(normal[:3]))
            if normal_norm <= 1e-12 or not np.isfinite(normal_norm):
                return False
            normal = normal[:3] / normal_norm
            length = self._face_role_marker_scale(marker, scene_radius)
            self._add_mesh_actor(
                pv.Sphere(radius=max(length * 0.08, 0.18), center=tuple(start[:3])),
                color=marker.color,
                opacity=0.98,
                flat_shading=True,
            )
            self._add_mesh_actor(
                pv.Arrow(start=tuple(start[:3]), direction=tuple(normal), scale=length),
                color=marker.color,
                opacity=0.96,
                flat_shading=True,
            )
            return True
        except Exception as exc:
            self.editor.append_debug(f"3D optical face marker error: {exc}")
            return False

    def _add_optical_solid_face_role_overlays(self) -> int:
        if self._renderer is None:
            return 0
        z_positions = self.editor._row_z_positions()
        _center, scene_radius = self._scene_bounds()
        count = 0
        for row_index, row in enumerate(self.editor.rows):
            if self.editor._file_backed_stl_row_at(row_index) is None:
                continue
            z_station = float(z_positions[row_index]) if row_index < len(z_positions) else 0.0
            for marker in optical_solid_face_world_markers(row, z_station, assigned_only=True):
                if self._add_face_role_marker_actor(marker, scene_radius=scene_radius):
                    count += 1
        return count

    @staticmethod
    def _virtual_plane_marker_scale(marker: OpticalSolidVirtualPlaneMarker, scene_radius: float) -> float:
        lower = max(float(scene_radius) * 0.05, 1.5)
        upper = max(float(scene_radius) * 0.28, lower)
        aperture = max(float(marker.aperture_mm), 1.0)
        return float(np.clip(aperture, lower, upper))

    def _add_virtual_plane_marker_actor(self, marker: OpticalSolidVirtualPlaneMarker, *, scene_radius: float) -> bool:
        if pv is None:
            return False
        try:
            center = np.asarray(marker.centroid, dtype=float)
            normal = np.asarray(marker.normal, dtype=float)
            if center.size < 3 or normal.size < 3:
                return False
            norm = float(np.linalg.norm(normal[:3]))
            if norm <= 1e-12 or not np.isfinite(norm):
                return False
            normal = normal[:3] / norm
            size = self._virtual_plane_marker_scale(marker, scene_radius)
            plane = pv.Plane(center=tuple(center[:3]), direction=tuple(normal), i_size=size, j_size=size, i_resolution=1, j_resolution=1)
            self._add_mesh_actor(plane, color=marker.color, opacity=0.16, flat_shading=True)
            try:
                edges = plane.extract_feature_edges(boundary_edges=True, feature_edges=False, manifold_edges=False)
                if int(getattr(edges, "n_points", 0)) > 0:
                    self._add_mesh_actor(edges, color=marker.color, opacity=0.95, line_width=2.0)
            except Exception:
                pass
            self._add_mesh_actor(
                pv.Arrow(start=tuple(center[:3]), direction=tuple(normal), scale=max(size * 0.45, 1.0)),
                color=marker.color,
                opacity=0.94,
                flat_shading=True,
            )
            return True
        except Exception as exc:
            self.editor.append_debug(f"3D optical virtual-plane error: {exc}")
            return False

    def _add_optical_solid_virtual_plane_overlays(self) -> int:
        if self._renderer is None:
            return 0
        z_positions = self.editor._row_z_positions()
        _center, scene_radius = self._scene_bounds()
        count = 0
        for row_index, row in enumerate(self.editor.rows):
            if self.editor._file_backed_stl_row_at(row_index) is None:
                continue
            z_station = float(z_positions[row_index]) if row_index < len(z_positions) else 0.0
            for marker in optical_solid_virtual_plane_world_markers(row, z_station, assigned_only=True):
                if self._add_virtual_plane_marker_actor(marker, scene_radius=scene_radius):
                    count += 1
        return count

    def _scene_bounds(self) -> tuple[np.ndarray, float]:
        if self._renderer is None:
            return np.zeros(3, dtype=float), 1.0
        bounds = np.asarray(self._renderer.ComputeVisiblePropBounds(), dtype=float)
        if bounds.size != 6 or not np.all(np.isfinite(bounds)) or bounds[0] > bounds[1]:
            return np.zeros(3, dtype=float), 1.0
        center = np.array(
            [
                0.5 * (bounds[0] + bounds[1]),
                0.5 * (bounds[2] + bounds[3]),
                0.5 * (bounds[4] + bounds[5]),
            ],
            dtype=float,
        )
        radius = max(bounds[1] - bounds[0], bounds[3] - bounds[2], bounds[5] - bounds[4], 1.0)
        return center, radius

    def _render_aspect(self) -> float:
        if self._vtk_widget is None:
            return 1.4
        try:
            width, height = self._vtk_widget.GetRenderWindow().GetSize()
            return max(float(width) / max(float(height), 1.0), 0.1)
        except Exception:
            return 1.4

    @staticmethod
    def _parallel_scale_for_orthographic_fit(horizontal_span: float, vertical_span: float, aspect: float) -> float:
        aspect = max(float(aspect), 0.1)
        horizontal_scale = float(horizontal_span) / (2.0 * aspect)
        vertical_scale = float(vertical_span) * 0.5
        return max(horizontal_scale, vertical_scale, 1.0) * 1.08

    def set_camera_preset(self, preset: str) -> None:
        self._camera_preset = preset
        if self._renderer is None:
            return
        camera = self._renderer.GetActiveCamera()
        if camera is None:
            return
        center, radius = self._scene_bounds()
        bounds = np.asarray(self._renderer.ComputeVisiblePropBounds(), dtype=float)
        if bounds.size == 6 and np.all(np.isfinite(bounds)) and bounds[0] <= bounds[1]:
            span_x = float(bounds[1] - bounds[0])
            span_y = float(bounds[3] - bounds[2])
            span_z = float(bounds[5] - bounds[4])
        else:
            span_x = span_y = span_z = radius
        distance = max(radius * 2.2, 50.0)
        aspect = self._render_aspect()
        parallel_scale = None
        if preset == "zy":
            position = center + np.array([-distance, 0.0, 0.0], dtype=float)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = self._parallel_scale_for_orthographic_fit(span_z, span_y, aspect)
        elif preset == "xy":
            position = center + np.array([0.0, 0.0, distance], dtype=float)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = self._parallel_scale_for_orthographic_fit(span_x, span_y, aspect)
        elif preset == "xz":
            position = center + np.array([0.0, distance, 0.0], dtype=float)
            view_up = (1.0, 0.0, 0.0)
            parallel_scale = self._parallel_scale_for_orthographic_fit(span_z, span_x, aspect)
        elif preset == "bottom":
            position = center + np.array([0.0, 0.0, -distance], dtype=float)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = self._parallel_scale_for_orthographic_fit(span_x, span_y, aspect)
        else:
            position = center + np.array([-distance * 0.95, distance * 0.55, distance * 0.8], dtype=float)
            view_up = (0.0, 1.0, 0.0)
        camera.SetPosition(*position.tolist())
        camera.SetFocalPoint(*center.tolist())
        camera.SetViewUp(*view_up)
        try:
            camera.SetParallelProjection(1 if parallel_scale is not None else 0)
            if parallel_scale is not None:
                camera.SetParallelScale(float(parallel_scale))
        except Exception:
            pass
        self._renderer.ResetCameraClippingRange()
        self.render()

    def render(self) -> None:
        if self._vtk_widget is None:
            return
        try:
            self._vtk_widget.GetRenderWindow().Render()
        except Exception:
            pass

    def refresh_scene(
        self,
        system,
        rays,
        row_names: list[str],
        *,
        scene_bundle: SceneBundle | None = None,
        reset_camera: bool = False,
        ) -> None:
        if self._renderer is None:
            raise RuntimeError(_VTK_TK_UNAVAILABLE_REASON or "Embedded VTK/Tk viewer unavailable")

        self._renderer.RemoveAllViewProps()
        self._actor_row_map.clear()
        self._row_actor_map.clear()
        self._actor_ray_map.clear()
        self._ray_actor_map.clear()
        self._actor_step_map.clear()
        self._step_actor_map.clear()
        self._picked_step_label = None
        self._picked_ray_index = None
        self._hover_step_actor = None
        self._hover_step_outline_actor = None
        self._hover_step_cell_key = None
        self._picked_row_index = None

        drew_surfaces = 0
        for mesh_item in self.editor._scene_surface_meshes(system, scene_bundle, include_reference_surfaces=True):
            mesh = mesh_item.mesh
            self._add_mesh_actor(mesh, color=mesh_item.color, opacity=mesh_item.opacity, pick_row_index=mesh_item.row_index)
            if not mesh_item.is_body:
                try:
                    edges = mesh.extract_feature_edges(
                        feature_angle=10,
                        boundary_edges=True,
                        feature_edges=False,
                        manifold_edges=False,
                    )
                    if int(getattr(edges, "n_points", 0)) > 0:
                        self._add_mesh_actor(edges, color=(0.15, 0.15, 0.15), opacity=1.0, line_width=1.0)
                except Exception:
                    pass
            drew_surfaces += 1

        face_role_markers = self._add_optical_solid_face_role_overlays()
        virtual_plane_markers = self._add_optical_solid_virtual_plane_overlays()

        if self.show_rays_var.get():
            center, radius = self._scene_bounds()
            ray_radius = max(radius * 0.0015, 0.08)
            for ray_index, color, ray_pts in self.editor._iter_3d_scene_ray_items(rays, scene_bundle):
                try:
                    ray_mesh = pv.lines_from_points(ray_pts)
                except Exception:
                    continue
                if int(getattr(ray_mesh, "n_points", 0)) < 2:
                    continue
                self._add_ray_actor(ray_mesh, radius=ray_radius, color=color, ray_index=ray_index)

        for label, builder, color, opacity in (
            ("lens", self.editor._transformed_imported_lens_step_mesh, (0.25, 0.31, 0.39), 0.22),
            ("led", self.editor._transformed_imported_led_step_mesh, (0.95, 0.62, 0.16), 0.35),
            ("camera", self.editor._transformed_imported_camera_step_mesh, (0.36, 0.39, 0.44), 0.32),
        ):
            try:
                cad_mesh = builder()
            except Exception as exc:
                cad_mesh = None
                self.editor.append_debug(f"3D {label} STEP error: {exc}")
            if cad_mesh is not None and int(getattr(cad_mesh, "n_points", 0)) > 0:
                self._add_mesh_actor(
                    cad_mesh,
                    color=color,
                    opacity=opacity,
                    pick_row_index=None,
                    pick_step_label=label,
                    flat_shading=True,
                )

        try:
            external_mesh = self.editor._transformed_external_camera_mesh()
        except Exception as exc:
            external_mesh = None
            self.editor.append_debug(f"3D camera CAD error: {exc}")
        if external_mesh is not None and int(getattr(external_mesh, "n_points", 0)) > 0:
            spec = self.editor._current_external_camera_spec() or {}
            self._add_mesh_actor(
                external_mesh,
                color=tuple(spec.get("color", (0.62, 0.66, 0.72))),
                opacity=float(spec.get("opacity_3d", 1.0)),
                pick_row_index=None,
                flat_shading=True,
            )

        self._renderer.ResetCamera()
        self.set_camera_preset(self._camera_preset)
        self.highlight_row(self.editor._current_selected_row_index())
        ray_count = len(getattr(scene_bundle, "ray_paths", []) or []) if scene_bundle is not None else len(getattr(rays, "CC", []))
        self.status_var.set(
            f"3D scene ready | surfaces={drew_surfaces} | rays={ray_count} | face roles={face_role_markers} | virtual planes={virtual_plane_markers}"
        )
        self.render()

    def refresh_from_editor(self) -> None:
        try:
            system, rays, scene_bundle = self.editor._build_preview_system_rays_bundle(update_state=True)
            row_names = [row.name for row in self.editor.rows]
            self.refresh_scene(system, rays, row_names, scene_bundle=scene_bundle, reset_camera=False)
            self.editor.status_var.set("3D inspector updated")
        except Exception as exc:
            self.status_var.set(f"3D refresh failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"3D inspector refresh error: {exc}")

    def open_selected_optical_faces(self) -> None:
        row_index = self._picked_row_index
        if row_index is None:
            row_index = self.editor._current_selected_row_index()
        if row_index is None:
            self.status_var.set("Faces: select a CAD/STL solid row first.")
            return
        try:
            self.editor.open_optical_solid_face_role_editor(int(row_index))
        except Exception as exc:
            self.status_var.set(f"Faces unavailable: {_short_error_message(exc)}")
            self.editor.append_debug(f"3D Faces action failed: {exc}")

    def start_source_target_pick(self) -> None:
        self._source_target_pick_mode = True
        self._center_row_to_ray_mode = False
        self._center_row_to_ray_index = None
        self._set_axis_pick_cursor(True)
        self.status_var.set(
            "Source Target: click a surface/CAD solid. Assigned CAD/STL faces are used when the pick lands near one."
        )

    def _apply_source_target_pick(self, row_index: int) -> None:
        self._source_target_pick_mode = False
        self._set_axis_pick_cursor(False)
        row_index = int(row_index)
        face_id = ""
        target_text = f"S{row_index} row center"
        if self.editor._file_backed_stl_row_at(row_index) is not None and self._picker is not None:
            try:
                point = np.asarray(self._picker.GetPickPosition(), dtype=float).reshape(-1)[:3]
            except Exception:
                point = np.empty(0, dtype=float)
            if point.size >= 3 and np.all(np.isfinite(point[:3])):
                matched = self.editor.scene_source_face_anchor_at_world_point(row_index, point[:3])
                if matched is not None:
                    face_id = str(matched.get("face_id", "") or "").strip()
                    if face_id:
                        target_text = f"S{row_index} face {_optical_solid_face_marker_label(matched)} [{face_id}]"
        self.editor._select_table_row(row_index)
        self._set_row_highlight(row_index)
        self._set_ray_highlight(None)
        self.status_var.set(f"Opening Scene Source Manager with {target_text} selected.")
        self.editor.open_scene_source_manager(aim_row_index=row_index, aim_face_id=face_id)

    def start_center_row_to_ray(self) -> None:
        row_index = self._picked_row_index
        if row_index is None:
            row_index = self.editor._current_selected_row_index()
        self._center_row_to_ray_mode = True
        self._source_target_pick_mode = False
        if row_index is not None and 0 <= int(row_index) < len(self.editor.rows):
            row = self.editor.rows[int(row_index)]
            if row.surface not in {"Object", "Image"}:
                self._center_row_to_ray_index = int(row_index)
                stl_note = " assigned optical-face anchor or" if self.editor._file_backed_stl_row_at(int(row_index)) is not None else ""
                self.status_var.set(
                    f"Center Row->Ray: selected S{int(row_index)}. Now click the ray that should pass through its{stl_note} center."
                )
                return
        self._center_row_to_ray_index = None
        self.status_var.set("Center Row->Ray: click the surface/CAD row to move, then click the target ray.")

    def _apply_center_row_to_ray(self, ray_index: int) -> None:
        row_index = self._center_row_to_ray_index
        if row_index is None:
            self.status_var.set("Center Row->Ray: click a surface/CAD row first, then click the target ray.")
            return
        try:
            result = self.editor.center_surface_row_on_ray(int(row_index), int(ray_index))
        except Exception as exc:
            self.status_var.set(f"Center Row->Ray failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"Center Row->Ray failed: {exc}")
            return
        self._center_row_to_ray_mode = False
        self._center_row_to_ray_index = None
        if self.editor._file_backed_stl_row_at(int(row_index)) is not None:
            self._stl_placement_dirty = True
        try:
            self.refresh_from_editor()
            self.highlight_row(int(row_index))
            self._set_ray_highlight(int(ray_index))
        except Exception as exc:
            self.editor.append_debug(f"Center Row->Ray refresh failed: {exc}")
        target = result.get("target", (float("nan"), float("nan"), float("nan")))
        anchor_label = str(result.get("anchor_label", "") or result.get("anchor_face_id", "") or "").strip()
        anchor_text = f" using {anchor_label}" if anchor_label else ""
        self.status_var.set(
            "Centered S{row} on ray {ray}{anchor} at ({x:.6g}, {y:.6g}, {z:.6g}) mm. "
            "Click Done -> 2D or Update to refresh plots.".format(
                row=int(row_index),
                ray=int(ray_index),
                anchor=anchor_text,
                x=float(target[0]),
                y=float(target[1]),
                z=float(target[2]),
            )
        )

    def _on_left_button_press(self, obj, _event) -> None:
        if self._picker is None or self._renderer is None or self._vtk_interactor is None:
            return
        x, y = self._vtk_interactor.GetEventPosition()
        self._picker.Pick(x, y, 0.0, self._renderer)
        actor = self._picker.GetActor()
        actor_key = self._actor_key(actor)
        step_label = self._actor_step_map.get(actor_key) if actor_key is not None else None
        if self._source_target_pick_mode and step_label is not None:
            self.status_var.set("Source Target: pick a KrakenOS surface/CAD solid row, not external STEP hardware.")
            return
        if step_label is not None:
            if self.editor._cad_led_object_edge_pick:
                if step_label != "led":
                    self.status_var.set("Pick an edge on the LED STEP for Object-to-LED distance.")
                    return
                feature = self._picked_feature_info(actor, self._picker)
                if feature is None:
                    try:
                        center = np.asarray(self._picker.GetPickPosition(), dtype=float)
                    except Exception:
                        center = None
                else:
                    center = feature[0]
                if center is None or center.size < 3 or not np.all(np.isfinite(center[:3])):
                    self.status_var.set("Could not detect LED object-edge center.")
                    return
                self._set_step_hover_outline(None, None)
                self._set_axis_pick_cursor(False)
                self.editor.apply_led_object_edge_pick(center[:3])
                self.status_var.set("LED object-edge feature captured.")
                return
            requested_label = self.editor._cad_axis_pick_label
            if requested_label is None:
                self.editor.select_step_component(step_label)
                self._set_step_highlight(step_label)
                self.status_var.set(f"Selected {step_label.upper()} STEP.")
                return
            if requested_label != step_label:
                self.status_var.set(f"CAD STEP picked: {step_label}. Use Axis LED/Cam/Lens first.")
                return
            feature = self._picked_feature_info(actor, self._picker)
            if feature is None:
                try:
                    center = np.asarray(self._picker.GetPickPosition(), dtype=float)
                except Exception:
                    center = None
            else:
                center = feature[0]
            if center is None or center.size < 3 or not np.all(np.isfinite(center[:3])):
                self.status_var.set(f"Could not detect {step_label} feature center.")
                return
            self._set_step_hover_outline(None, None)
            self._set_axis_pick_cursor(False)
            self.editor.apply_step_axis_pick(step_label, center[:3])
            self.status_var.set(f"{step_label.upper()} optical-axis feature captured.")
            return
        row_index = self._actor_row_map.get(actor_key) if actor_key is not None else None
        ray_index = self._actor_ray_map.get(actor_key) if actor_key is not None else None
        if ray_index is not None:
            if self._source_target_pick_mode:
                self.status_var.set("Source Target: pick a surface/CAD solid, not a ray.")
                self.render()
                return
            if self._center_row_to_ray_mode:
                self._apply_center_row_to_ray(int(ray_index))
                self.render()
                return
            self._set_row_highlight(None)
            self._set_ray_highlight(int(ray_index))
            self.editor._select_ray_inspector_ray(int(ray_index))
            self.status_var.set(f"Selected ray {int(ray_index)} in Ray Inspector.")
            self.render()
            return
        if row_index is None:
            if self._source_target_pick_mode:
                self.status_var.set("Source Target: click a surface/CAD solid row.")
                self.render()
                return
            self._set_row_highlight(None)
            self._set_ray_highlight(None)
            self.status_var.set("3D scene ready")
            return
        if self._source_target_pick_mode:
            self._apply_source_target_pick(int(row_index))
            self.render()
            return
        self._set_row_highlight(row_index)
        self._set_ray_highlight(None)
        self.editor._select_table_row(row_index)
        row_name = self.editor.rows[row_index].name if 0 <= row_index < len(self.editor.rows) else "Surface"
        if self._center_row_to_ray_mode:
            self._center_row_to_ray_index = int(row_index)
            stl_note = " assigned optical-face anchor or" if self.editor._file_backed_stl_row_at(int(row_index)) is not None else ""
            self.status_var.set(f"Center Row->Ray: selected S{row_index}: {row_name}. Now click the target ray for its{stl_note} center.")
            self.render()
            return
        if self.editor._file_backed_stl_row_at(row_index) is not None:
            self._stl_placement_row_index = int(row_index)
            self.status_var.set(f"Selected CAD/STL row {row_index}: {row_name}. Use the placement toolbar.")
        else:
            self.status_var.set(f"Selected row {row_index}: {row_name}")
        self.render()

    def _on_mouse_move(self, obj, _event) -> None:
        if self._source_target_pick_mode:
            self._set_axis_pick_cursor(True)
            self.status_var.set("Source Target: click a surface/CAD solid row.")
            return
        requested_label = self.editor._cad_axis_pick_label
        led_edge_pick = bool(getattr(self.editor, "_cad_led_object_edge_pick", False))
        target_label = "led" if led_edge_pick else requested_label
        if target_label is None:
            self._set_step_hover_outline(None, None)
            self._set_axis_pick_cursor(False)
            return
        if self._picker is None or self._renderer is None or self._vtk_interactor is None:
            return
        try:
            x, y = self._vtk_interactor.GetEventPosition()
            self._picker.Pick(x, y, 0.0, self._renderer)
            actor = self._picker.GetActor()
        except Exception:
            actor = None
        actor_key = self._actor_key(actor)
        step_label = self._actor_step_map.get(actor_key) if actor_key is not None else None
        if step_label == target_label:
            try:
                cell_id = int(self._picker.GetCellId())
            except Exception:
                cell_id = -1
            hover_key = (actor_key, cell_id)
            outline = None
            if hover_key != self._hover_step_cell_key:
                feature = self._picked_feature_info(actor, self._picker)
                outline = self._hover_overlay_for_feature(feature[0], feature[1]) if feature is not None else None
            self._set_step_hover_outline(outline, hover_key)
            self._set_axis_pick_cursor(True)
            if led_edge_pick:
                self.status_var.set("Click orange LED edge used for Object-to-LED distance.")
            else:
                self.status_var.set(f"Click orange {step_label} edge/feature to align optical axis.")
            return
        self._set_step_hover_outline(None, None)
        self._set_axis_pick_cursor(False)

    def _set_axis_pick_cursor(self, hand: bool) -> None:
        try:
            if self._vtk_widget is not None:
                self._vtk_widget.configure(cursor="crosshair" if hand else "")
        except Exception:
            pass
        try:
            if self._vtk_interactor is not None:
                self._vtk_interactor.SetCurrentCursor(9 if hand else 0)
        except Exception:
            pass

    def _set_step_hover_outline(self, outline_mesh, hover_key) -> None:
        if hover_key is not None and hover_key == self._hover_step_cell_key:
            return
        if self._renderer is None:
            return
        if self._hover_step_outline_actor is not None:
            try:
                self._renderer.RemoveActor(self._hover_step_outline_actor)
            except Exception:
                pass
            self._hover_step_outline_actor = None
        self._hover_step_cell_key = hover_key
        if outline_mesh is not None and int(getattr(outline_mesh, "n_points", 0)) > 0 and vtkActor is not None and vtkDataSetMapper is not None:
            try:
                mapper = vtkDataSetMapper()
                mapper.SetInputData(outline_mesh)
                actor = vtkActor()
                actor.SetMapper(mapper)
                prop = actor.GetProperty()
                prop.SetColor(1.0, 0.18, 0.0)
                prop.SetOpacity(1.0)
                prop.SetLineWidth(8.0)
                try:
                    prop.SetAmbient(1.0)
                    prop.SetDiffuse(0.0)
                    prop.RenderLinesAsTubesOn()
                except Exception:
                    pass
                actor.PickableOff()
                self._renderer.AddActor(actor)
                self._hover_step_outline_actor = actor
            except Exception:
                self._hover_step_outline_actor = None
        self.render()

    @staticmethod
    def _picked_feature_info(actor, picker) -> tuple[np.ndarray, object | None] | None:
        if actor is None or picker is None:
            return None
        try:
            cell_id = int(picker.GetCellId())
        except Exception:
            cell_id = -1
        if cell_id < 0:
            return None
        try:
            data = actor.GetMapper().GetInput()
        except Exception:
            data = None
        if data is None:
            return None
        try:
            seed_cell = data.GetCell(cell_id)
            seed_ids = seed_cell.GetPointIds()
            seed_points = np.asarray(
                [data.GetPoint(seed_ids.GetId(index)) for index in range(seed_ids.GetNumberOfIds())],
                dtype=float,
            )
        except Exception:
            return None
        if seed_points.ndim != 2 or seed_points.shape[0] < 3:
            center = np.mean(seed_points, axis=0) if seed_points.size else None
            return (center, None) if center is not None else None
        normal = np.cross(seed_points[1] - seed_points[0], seed_points[2] - seed_points[0])
        normal_norm = float(np.linalg.norm(normal))
        if normal_norm <= 1e-12:
            return np.mean(seed_points, axis=0)
        normal /= normal_norm
        seed_center = np.mean(seed_points, axis=0)
        plane_d = float(np.dot(normal, seed_center))
        try:
            bounds = np.asarray(data.GetBounds(), dtype=float)
            span = max(float(bounds[1] - bounds[0]), float(bounds[3] - bounds[2]), float(bounds[5] - bounds[4]), 1.0)
            cell_count = int(data.GetNumberOfCells())
        except Exception:
            span = 1.0
            cell_count = 0
        plane_tol = max(span * 5e-5, 0.02)
        point_to_cells: dict[int, list[int]] = {}
        coplanar_cells: set[int] = set()
        for candidate_id in range(cell_count):
            try:
                cell = data.GetCell(candidate_id)
                ids = cell.GetPointIds()
                pts = np.asarray(
                    [data.GetPoint(ids.GetId(index)) for index in range(ids.GetNumberOfIds())],
                    dtype=float,
                )
            except Exception:
                continue
            if pts.ndim != 2 or pts.shape[0] < 3:
                continue
            cand_normal = np.cross(pts[1] - pts[0], pts[2] - pts[0])
            cand_norm = float(np.linalg.norm(cand_normal))
            if cand_norm <= 1e-12:
                continue
            cand_normal /= cand_norm
            if abs(float(np.dot(cand_normal, normal))) < 0.985:
                continue
            cand_center = np.mean(pts, axis=0)
            if abs(float(np.dot(normal, cand_center)) - plane_d) > plane_tol:
                continue
            coplanar_cells.add(candidate_id)
            for index in range(ids.GetNumberOfIds()):
                point_to_cells.setdefault(int(ids.GetId(index)), []).append(candidate_id)
        if cell_id not in coplanar_cells:
            return seed_center, Kraken3DInspector._outline_for_cells(data, {cell_id})
        component: set[int] = set()
        queue = [cell_id]
        while queue:
            candidate_id = queue.pop()
            if candidate_id in component:
                continue
            component.add(candidate_id)
            try:
                ids = data.GetCell(candidate_id).GetPointIds()
                for index in range(ids.GetNumberOfIds()):
                    for neighbor in point_to_cells.get(int(ids.GetId(index)), []):
                        if neighbor not in component:
                            queue.append(neighbor)
            except Exception:
                continue
        point_ids: set[int] = set()
        for candidate_id in component:
            try:
                ids = data.GetCell(candidate_id).GetPointIds()
                for index in range(ids.GetNumberOfIds()):
                    point_ids.add(int(ids.GetId(index)))
            except Exception:
                continue
        if not point_ids:
            return seed_center, Kraken3DInspector._outline_for_cells(data, component)
        points = np.asarray([data.GetPoint(point_id) for point_id in point_ids], dtype=float)
        center = 0.5 * (np.min(points, axis=0) + np.max(points, axis=0))
        return center, Kraken3DInspector._outline_for_cells(data, component)

    @staticmethod
    def _picked_feature_center(actor, picker) -> np.ndarray | None:
        feature = Kraken3DInspector._picked_feature_info(actor, picker)
        return feature[0] if feature is not None else None

    @staticmethod
    def _outline_for_cells(data, cell_ids: set[int]):
        if pv is None or data is None or not cell_ids:
            return None
        try:
            selected = pv.wrap(data).extract_cells(sorted(int(cell_id) for cell_id in cell_ids))
            surface = selected.extract_surface(algorithm="dataset_surface").copy(deep=True)
            outline = surface.extract_feature_edges(
                feature_angle=12,
                boundary_edges=True,
                feature_edges=True,
                manifold_edges=False,
            )
            if int(getattr(outline, "n_points", 0)) <= 0:
                outline = surface.extract_all_edges()
            if int(getattr(outline, "n_points", 0)) > 0:
                return outline.copy(deep=True)
        except Exception:
            return None
        return None

    @staticmethod
    def _hover_overlay_for_feature(center, outline_mesh):
        if pv is None:
            return outline_mesh
        parts = []
        span = 20.0
        try:
            if outline_mesh is not None and int(getattr(outline_mesh, "n_points", 0)) > 0:
                outline = pv.wrap(outline_mesh).copy(deep=True)
                parts.append(outline)
                bounds = outline.bounds
                span = max(
                    float(bounds[1] - bounds[0]),
                    float(bounds[3] - bounds[2]),
                    float(bounds[5] - bounds[4]),
                    1.0,
                )
        except Exception:
            pass
        try:
            center = np.asarray(center, dtype=float)
            if center.size >= 3 and np.all(np.isfinite(center[:3])):
                radius = max(min(span * 0.04, 6.0), 1.5)
                parts.append(
                    pv.Sphere(
                        radius=radius,
                        center=(float(center[0]), float(center[1]), float(center[2])),
                        theta_resolution=16,
                        phi_resolution=8,
                    )
                )
                arm = radius * 4.0
                for axis in np.eye(3):
                    start = center[:3] - axis * arm
                    end = center[:3] + axis * arm
                    parts.append(pv.Line(tuple(start), tuple(end)))
        except Exception:
            pass
        if not parts:
            return outline_mesh
        merged = parts[0]
        for part in parts[1:]:
            try:
                merged = merged.merge(part)
            except Exception:
                pass
        return merged

    @staticmethod
    def _set_step_actor_selected(actor, selected: bool) -> None:
        if actor is None:
            return
        try:
            prop = actor.GetProperty()
        except Exception:
            prop = None
        if prop is None:
            return
        base = getattr(actor, "_kraken_step_select_style", None)
        if not isinstance(base, dict):
            try:
                base = {
                    "edge_visibility": int(prop.GetEdgeVisibility()),
                    "edge_color": tuple(float(value) for value in prop.GetEdgeColor()),
                    "color": tuple(float(value) for value in prop.GetColor()),
                    "line_width": float(prop.GetLineWidth()),
                    "opacity": float(prop.GetOpacity()),
                    "ambient": float(prop.GetAmbient()),
                    "diffuse": float(prop.GetDiffuse()),
                }
                actor._kraken_step_select_style = base
            except Exception:
                base = {}
        if selected:
            try:
                prop.SetEdgeVisibility(1)
                prop.SetEdgeColor(1.0, 0.48, 0.0)
                prop.SetLineWidth(max(float(base.get("line_width", 1.0)), 3.0))
                prop.SetAmbient(max(float(base.get("ambient", 0.0)), 0.35))
                prop.SetOpacity(min(max(float(base.get("opacity", 1.0)), 0.25) + 0.10, 1.0))
            except Exception:
                pass
            return
        try:
            prop.SetEdgeVisibility(int(base.get("edge_visibility", 0)))
            edge_color = tuple(base.get("edge_color", (0.0, 0.0, 0.0)))
            if len(edge_color) == 3:
                prop.SetEdgeColor(*edge_color)
            color = tuple(base.get("color", (1.0, 1.0, 1.0)))
            if len(color) == 3:
                prop.SetColor(*color)
            prop.SetLineWidth(float(base.get("line_width", 1.0)))
            prop.SetOpacity(float(base.get("opacity", 1.0)))
            prop.SetAmbient(float(base.get("ambient", 0.0)))
            prop.SetDiffuse(float(base.get("diffuse", 1.0)))
        except Exception:
            pass

    @staticmethod
    def _set_ray_actor_selected(actor, selected: bool) -> None:
        if actor is None:
            return
        try:
            prop = actor.GetProperty()
        except Exception:
            prop = None
        if prop is None:
            return
        base = getattr(actor, "_kraken_ray_select_style", None)
        if not isinstance(base, dict):
            try:
                base = {
                    "color": tuple(float(value) for value in prop.GetColor()),
                    "line_width": float(prop.GetLineWidth()),
                    "opacity": float(prop.GetOpacity()),
                    "ambient": float(prop.GetAmbient()),
                    "diffuse": float(prop.GetDiffuse()),
                }
                actor._kraken_ray_select_style = base
            except Exception:
                base = {}
        if selected:
            try:
                prop.SetColor(1.0, 0.35, 0.0)
                prop.SetLineWidth(max(float(base.get("line_width", 1.2)), 4.0))
                prop.SetOpacity(1.0)
                prop.SetAmbient(max(float(base.get("ambient", 0.0)), 0.35))
            except Exception:
                pass
            return
        try:
            color = tuple(base.get("color", (0.2, 1.0, 0.2)))
            if len(color) == 3:
                prop.SetColor(*color)
            prop.SetLineWidth(float(base.get("line_width", 1.2)))
            prop.SetOpacity(float(base.get("opacity", 0.9)))
            prop.SetAmbient(float(base.get("ambient", 0.0)))
            prop.SetDiffuse(float(base.get("diffuse", 1.0)))
        except Exception:
            pass

    def start_stl_placement(self, row_index: int, *, refresh: bool = False) -> None:
        try:
            row_index = int(row_index)
        except Exception:
            self.status_var.set("Select a CAD/STL solid row before using placement controls.")
            return
        if self.editor._file_backed_stl_row_at(row_index) is None:
            self.status_var.set("Selected row is not a file-backed optical CAD/STL solid.")
            return
        self._stl_placement_row_index = row_index
        self.editor._select_table_row(row_index)
        self.highlight_row(row_index)
        if refresh:
            self.refresh_from_editor()
        self.status_var.set(f"CAD/STL placement mode: row {row_index}. Use the placement toolbar, then Done -> 2D or close this view.")

    def _active_stl_placement_row_index(self) -> int | None:
        if self._stl_placement_row_index is not None:
            if self.editor._file_backed_stl_row_at(self._stl_placement_row_index) is not None:
                return int(self._stl_placement_row_index)
        row_index = self.editor._current_selected_row_index()
        if row_index is not None and self.editor._file_backed_stl_row_at(int(row_index)) is not None:
            self._stl_placement_row_index = int(row_index)
            return int(row_index)
        self.status_var.set("Select an optical CAD/STL row first.")
        return None

    def _refresh_after_stl_pose_change(self, row_index: int, action: str) -> None:
        self._stl_placement_row_index = int(row_index)
        self._stl_placement_dirty = True
        try:
            self.refresh_from_editor()
        except Exception as exc:
            self.status_var.set(f"STL pose updated; 3D refresh failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"3D CAD/STL placement refresh failed: {exc}")
            return
        self.highlight_row(row_index)
        self.status_var.set(f"{action} applied to CAD/STL row {row_index}. Close or Done -> 2D to update the 2D layout.")

    def fit_selected_stl_axis(self) -> None:
        row_index = self._active_stl_placement_row_index()
        if row_index is None:
            return
        axis = self.stl_axis_var.get().strip() or "+Z"
        try:
            self.editor.apply_stl_axis_fit(row_index, axis)
        except Exception as exc:
            self.status_var.set(f"STL axis fit failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"STL axis fit failed: {exc}")
            return
        self._refresh_after_stl_pose_change(row_index, f"Fit {axis} -> +Z")

    def rotate_selected_stl_pose(self, axis: str, delta_deg: float) -> None:
        row_index = self._active_stl_placement_row_index()
        if row_index is None:
            return
        try:
            self.editor.rotate_stl_row_pose(row_index, axis, delta_deg)
        except Exception as exc:
            self.status_var.set(f"STL rotation failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"STL rotation failed: {exc}")
            return
        self._refresh_after_stl_pose_change(row_index, f"Rotate {axis.upper()} {float(delta_deg):+.0f} deg")

    def center_selected_stl_xy(self) -> None:
        row_index = self._active_stl_placement_row_index()
        if row_index is None:
            return
        try:
            self.editor.center_stl_row_xy(row_index)
        except Exception as exc:
            self.status_var.set(f"STL centring failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"STL centring failed: {exc}")
            return
        self._refresh_after_stl_pose_change(row_index, "Center X/Y")

    def place_selected_stl_front_on_row(self) -> None:
        row_index = self._active_stl_placement_row_index()
        if row_index is None:
            return
        try:
            self.editor.place_stl_row_front_on_station(row_index)
        except Exception as exc:
            self.status_var.set(f"STL front placement failed: {_short_error_message(exc)}")
            self.editor.append_debug(f"STL front placement failed: {exc}")
            return
        self._refresh_after_stl_pose_change(row_index, "Min Z On Row")

    def finish_stl_placement(self) -> None:
        if self._stl_placement_dirty:
            try:
                self.editor.refresh_plot(suppress_analysis=True)
                self._stl_placement_dirty = False
                self.editor.status_var.set("Applied CAD/STL placement to the 2D layout.")
            except Exception as exc:
                self.editor.status_var.set(f"CAD/STL placement saved; 2D refresh failed: {_short_error_message(exc)}")
                self.editor.append_debug(f"CAD/STL placement 2D refresh failed: {exc}")
        self._on_close()

    def _on_close(self) -> None:
        dirty = bool(getattr(self, "_stl_placement_dirty", False))
        self._stl_placement_dirty = False
        self.editor._three_d_inspector = None
        try:
            self.destroy()
        except Exception:
            pass
        if dirty:
            def refresh_2d_after_close() -> None:
                try:
                    self.editor.refresh_plot(suppress_analysis=True)
                except Exception as exc:
                    self.editor.status_var.set(f"CAD/STL placement saved; 2D refresh failed: {_short_error_message(exc)}")
                    self.editor.append_debug(f"CAD/STL placement close refresh failed: {exc}")

            try:
                self.editor.after(50, refresh_2d_after_close)
                self.editor.status_var.set("3D CAD/STL placement closed; refreshing 2D layout.")
            except Exception as exc:
                self.editor.append_debug(f"CAD/STL placement close refresh failed: {exc}")


class OpticalStlPlacementDialog(tk.Toplevel):
    """Visual pose editor for a file-backed optical CAD/STL row."""

    def __init__(
        self,
        editor: "KrakenLayoutEditor",
        row_index: int,
        row: SurfaceRow,
        path: Path,
        diagnostics: StlMeshDiagnostics,
    ) -> None:
        _load_3d_backends()
        if pv is None or vtkTkRenderWindowInteractor is None or vtkRenderer is None:
            raise RuntimeError(_VTK_TK_UNAVAILABLE_REASON or "Embedded VTK/Tk CAD/STL placement preview unavailable")
        super().__init__(editor)
        self.editor = editor
        self.row_index = int(row_index)
        self.path = Path(path).expanduser()
        self.diagnostics = diagnostics
        z_positions = editor._row_z_positions()
        self.z_station = float(z_positions[self.row_index]) if 0 <= self.row_index < len(z_positions) else 0.0
        self._renderer = None
        self._vtk_widget = None
        self._vtk_interactor = None
        self._orientation_widget = None
        self._render_after_id: str | None = None
        self._suspend_trace = False
        self._camera_preset = "iso"
        self.status_var = tk.StringVar(value="CAD/STL placement preview ready")
        self.tilt_x_var = tk.StringVar(value=self._format_pose(row.tilt_x))
        self.tilt_y_var = tk.StringVar(value=self._format_pose(row.tilt_y))
        self.tilt_z_var = tk.StringVar(value=self._format_pose(row.tilt_z))
        self.desp_x_var = tk.StringVar(value=self._format_pose(row.desp_x))
        self.desp_y_var = tk.StringVar(value=self._format_pose(row.desp_y))
        self.desp_z_var = tk.StringVar(value=self._format_pose(row.desp_z))
        self.axis_var = tk.StringVar(value="+Z")
        self._face_metadata = normalize_optical_solid_face_metadata(
            (row.advanced or {}).get(OPTICAL_SOLID_FACES_ADVANCED_ATTR, {}),
            source_stl=str(self.path),
        )
        self._face_anchor_choices = self._build_face_anchor_choices(self._face_metadata)
        self.face_anchor_var = tk.StringVar(value=self._default_face_anchor_choice())
        self.roll_constraint_var = tk.StringVar(value=OPTICAL_SOLID_FACE_FIT_ROLL_DEFAULT)
        self.title(f"Visual CAD/STL Placement - S{self.row_index}")
        self.geometry("1180x780")
        self.minsize(860, 560)
        self.transient(editor)
        self.protocol("WM_DELETE_WINDOW", self.destroy)
        self.columnconfigure(0, weight=0)
        self.columnconfigure(1, weight=1)
        self.rowconfigure(1, weight=1)

        summary = (
            f"S{self.row_index}: {row.name or row.surface} | {self.path.name} | "
            f"{short_stl_mesh_diagnostics(diagnostics)} | row Z={self.z_station:.6g} mm"
        )
        ttk.Label(self, text=summary, padding=(10, 8, 10, 0), wraplength=1120).grid(
            row=0,
            column=0,
            columnspan=2,
            sticky="ew",
        )

        controls = ttk.Frame(self, padding=10)
        controls.grid(row=1, column=0, sticky="nsw")
        viewer_host = ttk.Frame(self, padding=(0, 10, 10, 10))
        viewer_host.grid(row=1, column=1, sticky="nsew")
        viewer_host.columnconfigure(0, weight=1)
        viewer_host.rowconfigure(0, weight=1)

        self._build_controls(controls)
        _prepare_vtk_tk_widget(viewer_host)
        self._vtk_widget = vtkTkRenderWindowInteractor(viewer_host, width=760, height=660)
        self._vtk_widget.grid(row=0, column=0, sticky="nsew")
        render_window = self._vtk_widget.GetRenderWindow()
        self._renderer = vtkRenderer()
        render_window.AddRenderer(self._renderer)
        self._renderer.SetBackground(1.0, 1.0, 1.0)
        self._vtk_interactor = render_window.GetInteractor()
        if vtkOrientationMarkerWidget is not None and vtkAxesActor is not None and self._vtk_interactor is not None:
            axes = vtkAxesActor()
            self._orientation_widget = vtkOrientationMarkerWidget()
            self._orientation_widget.SetOrientationMarker(axes)
            self._orientation_widget.SetInteractor(self._vtk_interactor)
            self._orientation_widget.SetViewport(0.0, 0.0, 0.16, 0.16)
            self._orientation_widget.SetEnabled(1)
            self._orientation_widget.InteractiveOff()
        self._vtk_widget.Initialize()
        ttk.Label(self, textvariable=self.status_var, padding=(10, 0, 10, 8)).grid(
            row=2,
            column=0,
            columnspan=2,
            sticky="ew",
        )
        for var in (
            self.tilt_x_var,
            self.tilt_y_var,
            self.tilt_z_var,
            self.desp_x_var,
            self.desp_y_var,
            self.desp_z_var,
        ):
            var.trace_add("write", self._schedule_render)
        self.after(60, lambda: self._render_preview(reset_camera=True))

    @staticmethod
    def _format_pose(value: float) -> str:
        return f"{float(value):.12g}"

    @staticmethod
    def _face_choice_text(face: dict[str, object]) -> str:
        face_id = str(face.get("face_id", "") or "").strip() or "Face"
        label = _optical_solid_face_marker_label(face)
        return f"{face_id}: {label}" if label else face_id

    def _build_face_anchor_choices(self, metadata: dict[str, object]) -> dict[str, str]:
        choices = {"Auto": ""}
        for face in list(metadata.get("faces", []) or []):
            if not isinstance(face, dict):
                continue
            normalized = normalize_optical_solid_face_record(face)
            choices[self._face_choice_text(normalized)] = str(normalized.get("face_id", "") or "").strip()
        return choices

    def _default_face_anchor_choice(self) -> str:
        face = select_optical_solid_anchor_face(self._face_metadata)
        if face is None:
            return "Auto"
        face_id = str(face.get("face_id", "") or "").strip()
        for label, candidate_id in self._face_anchor_choices.items():
            if candidate_id == face_id:
                return label
        return "Auto"

    def _selected_face_anchor_id(self) -> str:
        return str(self._face_anchor_choices.get(self.face_anchor_var.get().strip(), "") or "").strip()

    def _selected_face_record(self) -> dict[str, object] | None:
        return select_optical_solid_anchor_face(self._face_metadata, face_id=self._selected_face_anchor_id())

    def _selected_face_world_record(
        self,
        tilts: tuple[float, float, float] | None = None,
        desp: tuple[float, float, float] | None = None,
    ) -> dict[str, object] | None:
        if tilts is None or desp is None:
            tilts, desp = self._pose_values()
        preview_row = self._preview_face_role_row(tilts, desp)
        face_id = self._selected_face_anchor_id()
        for face in optical_solid_face_world_records(preview_row, self.z_station, assigned_only=False):
            if face_id and str(face.get("face_id", "") or "").strip() == face_id:
                return face
        if face_id:
            return None
        selected = self._selected_face_record()
        if selected is None:
            return None
        selected_id = str(selected.get("face_id", "") or "").strip()
        for face in optical_solid_face_world_records(preview_row, self.z_station, assigned_only=False):
            if str(face.get("face_id", "") or "").strip() == selected_id:
                return face
        return None

    def _reference_anchor_point(
        self,
        tilts: tuple[float, float, float] | None = None,
        desp: tuple[float, float, float] | None = None,
    ) -> np.ndarray:
        if tilts is None or desp is None:
            tilts, desp = self._pose_values()
        face = self._selected_face_world_record(tilts, desp)
        if face is not None:
            centroid = np.asarray(face.get("centroid_world", (np.nan, np.nan, np.nan)), dtype=float)
            if centroid.size >= 3 and np.all(np.isfinite(centroid[:3])):
                return centroid[:3]
        return np.asarray((float(desp[0]), float(desp[1]), self.z_station + float(desp[2])), dtype=float)

