    def open_optical_solid_face_role_editor(self, row_index: int | None = None) -> None:
        title = "Assign CAD/STL Optical Faces"
        if row_index is None:
            selected = self._selected_file_backed_stl_row(title)
            if selected is None:
                return
            row_index, row, path = selected
        else:
            self._commit_pending_table_edit()
            try:
                self._read_rows_from_table()
            except Exception as exc:
                messagebox.showerror(title, f"Could not read the surface table:\n\n{exc}", parent=self)
                return
            item = self._file_backed_stl_row_at(row_index)
            if item is None:
                messagebox.showinfo(title, "The selected row does not contain a file-backed Solid_3d_stl value.", parent=self)
                return
            row, path = item
        self._open_optical_solid_faces_for_row(int(row_index), row, path)

    def _selected_file_backed_stl_row(self, title: str) -> tuple[int, SurfaceRow, Path] | None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror(title, f"Could not read the surface table:\n\n{exc}", parent=self)
            return None
        row_index = self._selected_surface_row_index()
        if row_index is None or row_index < 0 or row_index >= len(self.rows):
            messagebox.showinfo(title, "Select an STL solid row first.", parent=self)
            return None
        row = self.rows[row_index]
        path = self._stl_path_from_row(row)
        if path is None:
            messagebox.showinfo(title, "The selected row does not contain a file-backed Solid_3d_stl value.", parent=self)
            return None
        if not path.exists():
            messagebox.showerror(title, f"STL file does not exist:\n\n{path}", parent=self)
            return None
        return row_index, row, path

    def _file_backed_stl_row_at(self, row_index: int) -> tuple[SurfaceRow, Path] | None:
        try:
            row_index = int(row_index)
        except Exception:
            return None
        if not (0 <= row_index < len(self.rows)):
            return None
        row = self.rows[row_index]
        path = self._stl_path_from_row(row)
        if path is None or not path.exists():
            return None
        return row, path

    def _stl_row_z_station(self, row_index: int) -> float:
        z_positions = self._row_z_positions()
        if 0 <= int(row_index) < len(z_positions):
            return float(z_positions[int(row_index)])
        return 0.0

    def _apply_stl_row_pose(
        self,
        row_index: int,
        *,
        tilts: tuple[float, float, float] | None = None,
        desp: tuple[float, float, float] | None = None,
        action: str,
    ) -> None:
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        row, _path = selected
        self._begin_history_capture()
        if tilts is not None:
            row.tilt_x, row.tilt_y, row.tilt_z = (float(value) for value in tilts)
        if desp is not None:
            row.desp_x, row.desp_y, row.desp_z = (float(value) for value in desp)
        self._sync_table()
        self._select_table_row(int(row_index))
        self._commit_history_capture()
        self._mark_plot_update_pending()
        self.append_debug(
            "STL 3D placement {action} S{idx}: Tilt=({tx:.6g},{ty:.6g},{tz:.6g}) "
            "Desp=({dx:.6g},{dy:.6g},{dz:.6g})".format(
                action=action,
                idx=int(row_index),
                tx=float(row.tilt_x),
                ty=float(row.tilt_y),
                tz=float(row.tilt_z),
                dx=float(row.desp_x),
                dy=float(row.desp_y),
                dz=float(row.desp_z),
            )
        )

    def apply_stl_axis_fit(self, row_index: int, axis: str) -> None:
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        _row, path = selected
        axis = str(axis or "+Z").strip()
        tilts = STL_AXIS_TO_LAYOUT_Z_TILTS.get(axis, STL_AXIS_TO_LAYOUT_Z_TILTS["+Z"])
        bounds_min, _bounds_max, center = rotated_stl_bounds(path, tilts)
        desp = (-float(center[0]), -float(center[1]), -float(bounds_min[2]))
        self._apply_stl_row_pose(row_index, tilts=tilts, desp=desp, action=f"fit {axis}->+Z")

    def rotate_stl_row_pose(self, row_index: int, axis: str, delta_deg: float) -> None:
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        row, _path = selected
        tilts = [float(row.tilt_x), float(row.tilt_y), float(row.tilt_z)]
        axis_index = {"x": 0, "y": 1, "z": 2}.get(str(axis).strip().lower())
        if axis_index is None:
            raise RuntimeError(f"Unknown STL rotation axis: {axis}")
        tilts[axis_index] += float(delta_deg)
        self._apply_stl_row_pose(row_index, tilts=tuple(tilts), action=f"rotate {axis.upper()} {float(delta_deg):+.0f} deg")

    def center_stl_row_xy(self, row_index: int) -> None:
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        row, path = selected
        tilts = (float(row.tilt_x), float(row.tilt_y), float(row.tilt_z))
        _bounds_min, _bounds_max, center = rotated_stl_bounds(path, tilts)
        desp = (-float(center[0]), -float(center[1]), float(row.desp_z))
        self._apply_stl_row_pose(row_index, desp=desp, action="center X/Y")

    def place_stl_row_front_on_station(self, row_index: int) -> None:
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        row, path = selected
        tilts = (float(row.tilt_x), float(row.tilt_y), float(row.tilt_z))
        bounds_min, _bounds_max, _center = rotated_stl_bounds(path, tilts)
        desp = (float(row.desp_x), float(row.desp_y), -float(bounds_min[2]))
        self._apply_stl_row_pose(row_index, desp=desp, action="front on row")

    def _surface_origin_for_rows(self, rows: list[SurfaceRow], row_index: int) -> np.ndarray:
        transform = self._surface_transform_for_rows(rows, int(row_index))
        return np.asarray(transform[:3, 3], dtype=float)

    def _surface_normal_for_rows(self, rows: list[SurfaceRow], row_index: int) -> np.ndarray:
        transform = self._surface_transform_for_rows(rows, int(row_index))
        normal = np.asarray(transform[:3, 2], dtype=float)
        norm = float(np.linalg.norm(normal))
        if norm <= 1e-12:
            return np.asarray((0.0, 0.0, 1.0), dtype=float)
        return normal / norm

    def _scene_source_aim_target_choices(self) -> list[str]:
        choices: list[str] = []
        for index, row in enumerate(self.rows):
            surface = str(row.surface or f"Row {index}").strip() or f"Row {index}"
            name = str(row.name or "").strip()
            label = surface if not name or name == surface else f"{name} ({surface})"
            if self._file_backed_stl_row_at(index) is not None:
                label = f"{label} CAD/STL center"
            choices.append(f"{index}: {label}")
            for face in self._scene_source_face_anchor_records(index):
                face_id = str(face.get("face_id", "") or "").strip()
                if not face_id:
                    continue
                face_label = _optical_solid_face_marker_label(face)
                choices.append(f"{index}/{face_id}: {label} face {face_label} [{face_id}]")
        return choices

    def _scene_source_target_choice_for(self, row_index: int, face_id: str = "") -> str:
        face = str(face_id or "").strip()
        prefix = f"{int(row_index)}/{face}:" if face else f"{int(row_index)}:"
        return next((choice for choice in self._scene_source_aim_target_choices() if choice.startswith(prefix)), "")

    def _scene_source_face_anchor_records(self, row_index: int) -> list[dict[str, object]]:
        row_index = int(row_index)
        if not (0 <= row_index < len(self.rows)):
            return []
        row = self.rows[row_index]
        try:
            faces = optical_solid_face_world_records(
                row,
                self._stl_row_z_station(row_index),
                assigned_only=True,
            )
        except Exception:
            return []
        output: list[dict[str, object]] = []
        seen: set[str] = set()
        for face in faces:
            face_id = str(face.get("face_id", "") or "").strip()
            centroid = np.asarray(face.get("centroid_world", (np.nan, np.nan, np.nan)), dtype=float).reshape(-1)
            if not face_id or face_id in seen or centroid.size < 3 or not np.all(np.isfinite(centroid[:3])):
                continue
            seen.add(face_id)
            output.append(dict(face))
        return output

    def _scene_source_face_anchor_record(self, row_index: int, face_id: str) -> dict[str, object] | None:
        target = str(face_id or "").strip()
        if not target:
            return None
        for face in self._scene_source_face_anchor_records(int(row_index)):
            if str(face.get("face_id", "") or "").strip() == target:
                return dict(face)
        return None

    def scene_source_face_anchor_at_world_point(self, row_index: int, point_world, normal_world=None) -> dict[str, object] | None:
        faces = self._scene_source_face_anchor_records(int(row_index))
        if not faces:
            return None
        return match_optical_solid_world_face(faces, point_world, normal_world)

    def _surface_reference_world_point(self, row_index: int, *, face_id: str = "", system=None) -> np.ndarray:
        row_index = int(row_index)
        if not (0 <= row_index < len(self.rows)):
            raise RuntimeError("Target row is out of range.")

        anchor_face = self._scene_source_face_anchor_record(row_index, face_id)
        if anchor_face is not None:
            centroid = np.asarray(anchor_face.get("centroid_world", (0.0, 0.0, 0.0)), dtype=float).reshape(-1)[:3]
            if centroid.size >= 3 and np.all(np.isfinite(centroid)):
                return centroid.astype(float)
            raise RuntimeError("Selected CAD/STL face anchor has no finite world centroid.")
        if str(face_id or "").strip():
            raise RuntimeError("Selected CAD/STL face anchor is not available for this row.")

        selected_stl = self._file_backed_stl_row_at(row_index)
        if selected_stl is not None:
            row, path = selected_stl
            tilts = (float(row.tilt_x), float(row.tilt_y), float(row.tilt_z))
            desp = (float(row.desp_x), float(row.desp_y), float(row.desp_z))
            _bounds_min, _bounds_max, center = transformed_stl_bounds(
                path,
                tilts,
                desp,
                self._stl_row_z_station(row_index),
            )
            center = np.asarray(center, dtype=float).reshape(-1)[:3]
            if center.size >= 3 and np.all(np.isfinite(center)):
                return center.astype(float)

        try:
            trace_state = self._resolved_trace_mode(system=system)
        except Exception:
            trace_state = {}
        if bool(trace_state.get("use_folded")):
            try:
                _point, _direction, _max_half, _extent, elements = self._compute_world_folded_layout_geometry_for_rows(
                    self.rows,
                    system=system,
                )
                for surface_index, (_surface_type, center, _row, *_rest) in enumerate(elements, start=1):
                    if surface_index == row_index:
                        center_2d = np.asarray(center, dtype=float).reshape(-1)
                        if center_2d.size >= 2 and np.all(np.isfinite(center_2d[:2])):
                            return np.asarray((0.0, float(center_2d[1]), float(center_2d[0])), dtype=float)
            except Exception:
                pass

        try:
            return self._surface_origin_for_rows(self.rows, row_index)
        except Exception:
            z_positions = self._row_z_positions()
            row = self.rows[row_index]
            z_station = float(z_positions[row_index]) if row_index < len(z_positions) else 0.0
            return np.asarray(
                (
                    float(row.desp_x),
                    float(row.desp_y),
                    z_station + float(row.desp_z),
                ),
                dtype=float,
            )

    def scene_source_direction_to_row(
        self,
        source_spec: dict[str, object],
        row_index: int,
        *,
        face_id: str = "",
        system=None,
    ) -> dict[str, object]:
        target = self._surface_reference_world_point(int(row_index), face_id=face_id, system=system)
        origin = self._source_spec_vector(
            dict(source_spec or {}),
            ("origin", "source_xyz", "xyz"),
            ("source_x", "source_y", "source_z"),
            (0.0, 0.0, 0.0),
        )[:3].astype(float)
        delta = np.asarray(target, dtype=float).reshape(3) - origin
        distance = float(np.linalg.norm(delta))
        if not np.isfinite(distance) or distance <= 1e-12:
            raise RuntimeError("Source origin is already at the target row center.")
        direction = delta / distance
        row = self.rows[int(row_index)]
        row_name = str(row.name or row.surface or f"Row {int(row_index)}").strip()
        anchor_face = self._scene_source_face_anchor_record(int(row_index), face_id)
        target_label = row_name
        normalized_face_id = str(face_id or "").strip()
        if anchor_face is not None:
            target_label = f"{row_name} face {_optical_solid_face_marker_label(anchor_face)}"
            normalized_face_id = str(anchor_face.get("face_id", "") or normalized_face_id).strip()
        return {
            "source_l": float(direction[0]),
            "source_m": float(direction[1]),
            "source_n": float(direction[2]),
            "target_point": tuple(float(value) for value in np.asarray(target, dtype=float).reshape(3)),
            "distance_mm": distance,
            "row_index": int(row_index),
            "row_name": row_name,
            "face_id": normalized_face_id,
            "target_label": target_label,
        }

    def scene_source_place_at_row_standoff(
        self,
        source_spec: dict[str, object],
        row_index: int,
        distance_mm: float,
        *,
        face_id: str = "",
        system=None,
    ) -> dict[str, object]:
        distance = float(distance_mm)
        if not np.isfinite(distance) or distance <= 0.0:
            raise RuntimeError("Placement standoff must be a positive distance.")
        target = self._surface_reference_world_point(int(row_index), face_id=face_id, system=system)
        direction = self._source_spec_vector(
            dict(source_spec or {}),
            ("direction", "source_lmn", "lmn"),
            ("source_l", "source_m", "source_n"),
            (0.0, 0.0, 1.0),
        )[:3].astype(float)
        norm = float(np.linalg.norm(direction))
        if not np.isfinite(norm) or norm <= 1e-12:
            raise RuntimeError("Set a non-zero source direction before placing at standoff.")
        direction = direction / norm
        origin = np.asarray(target, dtype=float).reshape(3) - direction * distance
        row = self.rows[int(row_index)]
        row_name = str(row.name or row.surface or f"Row {int(row_index)}").strip()
        anchor_face = self._scene_source_face_anchor_record(int(row_index), face_id)
        target_label = row_name
        normalized_face_id = str(face_id or "").strip()
        if anchor_face is not None:
            target_label = f"{row_name} face {_optical_solid_face_marker_label(anchor_face)}"
            normalized_face_id = str(anchor_face.get("face_id", "") or normalized_face_id).strip()
        return {
            "source_x": float(origin[0]),
            "source_y": float(origin[1]),
            "source_z": float(origin[2]),
            "source_l": float(direction[0]),
            "source_m": float(direction[1]),
            "source_n": float(direction[2]),
            "target_point": tuple(float(value) for value in np.asarray(target, dtype=float).reshape(3)),
            "distance_mm": distance,
            "row_index": int(row_index),
            "row_name": row_name,
            "face_id": normalized_face_id,
            "target_label": target_label,
        }

    @staticmethod
    def _closest_polyline_point(points: np.ndarray, target: np.ndarray) -> np.ndarray:
        best_point = np.asarray(points[0], dtype=float)
        best_distance = float("inf")
        for start, end in zip(points[:-1], points[1:]):
            start = np.asarray(start, dtype=float)
            end = np.asarray(end, dtype=float)
            segment = end - start
            denom = float(np.dot(segment, segment))
            if denom <= 1e-18:
                candidate = start
            else:
                t = float(np.dot(target - start, segment) / denom)
                t = min(max(t, 0.0), 1.0)
                candidate = start + segment * t
            distance = float(np.linalg.norm(candidate - target))
            if distance < best_distance:
                best_distance = distance
                best_point = candidate
        return best_point

    @staticmethod
    def _closest_polyline_point_and_direction(points: np.ndarray, target: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        best_point = np.asarray(points[0], dtype=float)
        best_direction = np.asarray(points[-1] - points[0], dtype=float)
        best_distance = float("inf")
        for start, end in zip(points[:-1], points[1:]):
            start = np.asarray(start, dtype=float)
            end = np.asarray(end, dtype=float)
            segment = end - start
            denom = float(np.dot(segment, segment))
            if denom <= 1e-18:
                candidate = start
                direction = best_direction
            else:
                t = float(np.dot(target - start, segment) / denom)
                t = min(max(t, 0.0), 1.0)
                candidate = start + segment * t
                direction = segment
            distance = float(np.linalg.norm(candidate - target))
            if distance < best_distance:
                best_distance = distance
                best_point = candidate
                best_direction = np.asarray(direction, dtype=float)
        norm = float(np.linalg.norm(best_direction))
        if norm <= 1e-12:
            best_direction = np.asarray((0.0, 0.0, 1.0), dtype=float)
        else:
            best_direction = best_direction / norm
        return best_point, best_direction

    @classmethod
    def _ray_point_on_surface_plane(cls, points: np.ndarray, origin: np.ndarray, normal: np.ndarray) -> np.ndarray:
        point, _direction = cls._ray_point_and_direction_on_surface_plane(points, origin, normal)
        return point

    @classmethod
    def _ray_point_and_direction_on_surface_plane(
        cls,
        points: np.ndarray,
        origin: np.ndarray,
        normal: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray]:
        best_point: np.ndarray | None = None
        best_direction: np.ndarray | None = None
        best_distance = float("inf")
        for start, end in zip(points[:-1], points[1:]):
            start = np.asarray(start, dtype=float)
            end = np.asarray(end, dtype=float)
            segment = end - start
            denom = float(np.dot(segment, normal))
            if abs(denom) <= 1e-12:
                continue
            t = -float(np.dot(start - origin, normal)) / denom
            if -1e-9 <= t <= 1.0 + 1e-9:
                t = min(max(t, 0.0), 1.0)
                candidate = start + segment * t
                distance = float(np.linalg.norm(candidate - origin))
                if distance < best_distance:
                    best_distance = distance
                    best_point = candidate
                    best_direction = np.asarray(segment, dtype=float)
        if best_point is not None:
            direction = np.asarray(best_direction, dtype=float)
            norm = float(np.linalg.norm(direction))
            if norm <= 1e-12:
                direction = np.asarray((0.0, 0.0, 1.0), dtype=float)
            else:
                direction = direction / norm
            return best_point, direction
        closest, direction = cls._closest_polyline_point_and_direction(points, origin)
        return closest - normal * float(np.dot(closest - origin, normal)), direction

    @classmethod
    def _optical_solid_face_snap_anchor(
        cls,
        row: SurfaceRow,
        z_station: float,
        ray_points: np.ndarray,
    ) -> dict[str, object] | None:
        face_records = optical_solid_face_world_records(row, z_station, assigned_only=True)
        if not face_records:
            return None
        priority_map = {
            OPTICAL_SOLID_FACE_FUNCTION_TRANSMIT: 5,
            "Beam Splitter": 4,
            "Mirror": 3,
            "TIR": 2,
            OPTICAL_SOLID_FACE_FUNCTION_DEFAULT: 1,
        }
        best: tuple[tuple[float, float, float, float, float], dict[str, object]] | None = None
        for face in face_records:
            function = _normalize_optical_solid_face_function(face.get("function"), legacy_role=face.get("role"))
            if function == "Absorber/Mechanical":
                continue
            centroid = np.asarray(face.get("centroid_world", (0.0, 0.0, 0.0)), dtype=float)
            normal = np.asarray(face.get("normal_world", (0.0, 0.0, 1.0)), dtype=float)
            if centroid.size < 3 or normal.size < 3 or not (np.all(np.isfinite(centroid[:3])) and np.all(np.isfinite(normal[:3]))):
                continue
            target, ray_direction = cls._ray_point_and_direction_on_surface_plane(ray_points, centroid[:3], normal[:3])
            distance = float(np.linalg.norm(target - centroid[:3]))
            facing = float(-np.dot(normal[:3], ray_direction[:3]))
            score = (
                float(priority_map.get(function, 0)),
                float(1.0 if _normalize_optical_solid_face_side(face.get("side_2d")) != OPTICAL_SOLID_FACE_SIDE_DEFAULT else 0.0),
                facing,
                -distance,
                float(face.get("area_mm2", 0.0) or 0.0),
            )
            payload = dict(face)
            payload["target_world"] = tuple(float(value) for value in target[:3])
            payload["ray_direction_world"] = tuple(float(value) for value in ray_direction[:3])
            payload["facing_score"] = facing
            payload["distance_to_ray_mm"] = distance
            payload["label"] = _optical_solid_face_marker_label(face)
            if best is None or score > best[0]:
                best = (score, payload)
        return None if best is None else best[1]

    def _row_decenter_delta_for_world_delta(self, row_index: int, world_delta: np.ndarray) -> np.ndarray:
        base_rows = [SurfaceRow(**asdict(row)) for row in self.rows]
        base_origin = self._surface_origin_for_rows(base_rows, row_index)
        columns: list[np.ndarray] = []
        eps = 1.0
        for attr in ("desp_x", "desp_y", "desp_z"):
            trial_rows = [SurfaceRow(**asdict(row)) for row in self.rows]
            setattr(trial_rows[row_index], attr, float(getattr(trial_rows[row_index], attr)) + eps)
            try:
                shifted_origin = self._surface_origin_for_rows(trial_rows, row_index)
                columns.append((shifted_origin - base_origin) / eps)
            except Exception:
                columns.append(np.eye(3)[len(columns)])
        jacobian = np.column_stack(columns)
        try:
            solution, _residuals, rank, _singular_values = np.linalg.lstsq(jacobian, np.asarray(world_delta, dtype=float), rcond=None)
            if rank > 0 and np.all(np.isfinite(solution)):
                return np.asarray(solution, dtype=float)
        except Exception:
            pass
        return np.asarray(world_delta, dtype=float)

    def center_surface_row_on_ray(self, row_index: int, ray_index: int) -> dict[str, object]:
        row_index = int(row_index)
        ray_index = int(ray_index)
        if not (0 <= row_index < len(self.rows)):
            raise RuntimeError(f"Surface row index is out of range: {row_index}")
        if self.rows[row_index].surface in {"Object", "Image"}:
            raise RuntimeError("Object/Image rows are references; choose a physical surface or CAD/STL row.")
        bundle = getattr(self, "_last_scene_bundle", None)
        ray_paths = list(getattr(bundle, "ray_paths", []) or []) if bundle is not None else []
        if not ray_paths:
            _system, _rays, bundle = self._build_preview_system_rays_bundle(update_state=True)
            ray_paths = list(getattr(bundle, "ray_paths", []) or [])
        ray_path = next((path for path in ray_paths if int(getattr(path, "ray_index", -1)) == ray_index), None)
        if ray_path is None and 0 <= ray_index < len(ray_paths):
            ray_path = ray_paths[ray_index]
        if ray_path is None:
            raise RuntimeError(f"Ray index is not available in the current 3D preview: {ray_index}")
        points = np.asarray(getattr(ray_path, "points_world", []), dtype=float)
        if points.ndim != 2 or points.shape[0] < 2 or points.shape[1] < 3:
            raise RuntimeError("Selected ray does not contain a valid 3D polyline.")
        anchor_label = ""
        anchor_face_id = ""
        anchor = None
        if self._file_backed_stl_row_at(row_index) is not None:
            anchor = self._optical_solid_face_snap_anchor(self.rows[row_index], self._stl_row_z_station(row_index), points[:, :3])
        if anchor is not None:
            origin = np.asarray(anchor.get("centroid_world", (0.0, 0.0, 0.0)), dtype=float)
            normal = np.asarray(anchor.get("normal_world", (0.0, 0.0, 1.0)), dtype=float)
            target, ray_direction = self._ray_point_and_direction_on_surface_plane(points[:, :3], origin, normal)
            anchor_label = str(anchor.get("label", "") or "").strip()
            anchor_face_id = str(anchor.get("face_id", "") or "").strip()
        else:
            origin = self._surface_origin_for_rows(self.rows, row_index)
            normal = self._surface_normal_for_rows(self.rows, row_index)
            target, ray_direction = self._ray_point_and_direction_on_surface_plane(points[:, :3], origin, normal)
        world_delta = np.asarray(target - origin, dtype=float)
        decenter_delta = self._row_decenter_delta_for_world_delta(row_index, world_delta)
        row = self.rows[row_index]
        self._begin_history_capture()
        row.desp_x = float(row.desp_x) + float(decenter_delta[0])
        row.desp_y = float(row.desp_y) + float(decenter_delta[1])
        row.desp_z = float(row.desp_z) + float(decenter_delta[2])
        self._sync_table()
        self._select_table_row(row_index)
        self._commit_history_capture()
        self._mark_plot_update_pending()
        anchor_text = f" anchor={anchor_label or anchor_face_id}" if anchor_label or anchor_face_id else ""
        self.append_debug(
            "Centered S{row} on ray {ray}: target=({tx:.6g},{ty:.6g},{tz:.6g}) "
            "world_delta=({wx:.6g},{wy:.6g},{wz:.6g}) decenter_delta=({dx:.6g},{dy:.6g},{dz:.6g}){anchor}".format(
                row=row_index,
                ray=ray_index,
                tx=float(target[0]),
                ty=float(target[1]),
                tz=float(target[2]),
                wx=float(world_delta[0]),
                wy=float(world_delta[1]),
                wz=float(world_delta[2]),
                dx=float(decenter_delta[0]),
                dy=float(decenter_delta[1]),
                dz=float(decenter_delta[2]),
                anchor=anchor_text,
            )
        )
        return {
            "row_index": row_index,
            "ray_index": ray_index,
            "target": tuple(float(value) for value in target[:3]),
            "world_delta": tuple(float(value) for value in world_delta[:3]),
            "decenter_delta": tuple(float(value) for value in decenter_delta[:3]),
            "ray_direction": tuple(float(value) for value in ray_direction[:3]),
            "anchor_label": anchor_label,
            "anchor_face_id": anchor_face_id,
        }

    def open_optical_stl_placement_assistant(self) -> None:
        selected = self._selected_file_backed_stl_row("Place/Orient Selected CAD/STL Solid")
        if selected is None:
            return
        row_index, row, path = selected
        diagnostics = inspect_stl_mesh(path)
        if diagnostics.triangle_count <= 0:
            messagebox.showerror(
                "Place/Orient Selected CAD/STL Solid",
                "STL geometry could not be read:\n\n" + "\n".join(diagnostics.errors or ("No triangles found.",)),
                parent=self,
            )
            return

        self.open_3d_view()
        inspector = self._three_d_inspector
        if inspector is not None and inspector.available:
            inspector.start_stl_placement(row_index, refresh=False)
            self.status_var.set(f"Opened 3D CAD/STL placement mode for S{row_index}.")
            return
        plotter = self._legacy_3d_plotter
        if plotter is not None:
            self._legacy_3d_start_stl_placement(plotter, row_index)
            self.status_var.set(f"Opened legacy 3D CAD/STL placement mode for S{row_index}.")
            return
        self.status_var.set("3D CAD/STL placement unavailable; use row Tilt/Decenter fields.")
        self.append_debug("3D CAD/STL placement unavailable; neither embedded nor legacy 3D view is active.")

    def _open_optical_stl_numeric_placement_assistant(
        self,
        row_index: int,
        row: SurfaceRow,
        path: Path,
        diagnostics: StlMeshDiagnostics,
    ) -> None:
        window = tk.Toplevel(self)
        window.title(f"Place/Orient CAD/STL Solid - S{row_index}")
        window.geometry("760x520")
        window.minsize(680, 440)
        window.transient(self)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(0, weight=1)

        frame = ttk.Frame(window, padding=12)
        frame.grid(row=0, column=0, sticky="nsew")
        frame.columnconfigure(1, weight=1)
        frame.rowconfigure(9, weight=1)

        summary = (
            f"S{row_index}: {row.name or row.surface}\n"
            f"{Path(diagnostics.path).name} | {short_stl_mesh_diagnostics(diagnostics)}\n"
            "Placement rule: choose the STL local axis that should point along layout +Z. "
            "The helper writes TiltX/Y/Z and optional DespX/Y/Z; the previous row Thickness controls the row Z station."
        )
        ttk.Label(frame, text=summary, justify="left", wraplength=700).grid(row=0, column=0, columnspan=3, sticky="ew", pady=(0, 10))

        ttk.Label(frame, text="STL axis -> layout +Z").grid(row=1, column=0, sticky="w", pady=4)
        axis_var = tk.StringVar(value="+Z")
        axis_menu = ttk.Combobox(
            frame,
            textvariable=axis_var,
            state="readonly",
            values=tuple(STL_AXIS_TO_LAYOUT_Z_TILTS.keys()),
            width=12,
        )
        axis_menu.grid(row=1, column=1, sticky="w", pady=4)

        center_xy_var = tk.BooleanVar(value=True)
        front_z_var = tk.BooleanVar(value=False)
        ttk.Checkbutton(frame, text="Center rotated STL X/Y on layout axis", variable=center_xy_var).grid(
            row=2, column=0, columnspan=3, sticky="w", pady=(8, 2)
        )
        ttk.Checkbutton(frame, text="Place rotated STL minimum Z on this row plane", variable=front_z_var).grid(
            row=3, column=0, columnspan=3, sticky="w", pady=2
        )

        ttk.Label(frame, text="Extra X [mm]").grid(row=4, column=0, sticky="w", pady=(10, 2))
        extra_x_var = tk.StringVar(value="0.0")
        extra_x_entry = ttk.Entry(frame, textvariable=extra_x_var, width=12)
        extra_x_entry.grid(row=4, column=1, sticky="w", pady=(10, 2))

        ttk.Label(frame, text="Extra Y [mm]").grid(row=5, column=0, sticky="w", pady=2)
        extra_y_var = tk.StringVar(value="0.0")
        extra_y_entry = ttk.Entry(frame, textvariable=extra_y_var, width=12)
        extra_y_entry.grid(row=5, column=1, sticky="w", pady=2)

        ttk.Label(frame, text="Extra Z [mm]").grid(row=6, column=0, sticky="w", pady=2)
        extra_z_var = tk.StringVar(value="0.0")
        extra_z_entry = ttk.Entry(frame, textvariable=extra_z_var, width=12)
        extra_z_entry.grid(row=6, column=1, sticky="w", pady=2)

        result_var = tk.StringVar(value="")
        ttk.Label(frame, textvariable=result_var, justify="left", wraplength=700).grid(
            row=7, column=0, columnspan=3, sticky="ew", pady=(10, 6)
        )

        text = tk.Text(frame, wrap="word", height=8, width=86)
        text.grid(row=9, column=0, columnspan=3, sticky="nsew", pady=(8, 0))

        def computed_pose() -> tuple[tuple[float, float, float], tuple[float, float, float], str]:
            axis = axis_var.get().strip()
            tilts = STL_AXIS_TO_LAYOUT_Z_TILTS.get(axis, STL_AXIS_TO_LAYOUT_Z_TILTS["+Z"])
            bounds_min, bounds_max, center = rotated_stl_bounds(path, tilts)
            try:
                extra_x = float(extra_x_var.get().strip() or "0.0")
                extra_y = float(extra_y_var.get().strip() or "0.0")
                extra_z = float(extra_z_var.get().strip() or "0.0")
            except Exception as exc:
                raise ValueError(f"Extra offsets must be numeric: {exc}") from exc
            desp_x = (-float(center[0]) if center_xy_var.get() else float(row.desp_x)) + extra_x
            desp_y = (-float(center[1]) if center_xy_var.get() else float(row.desp_y)) + extra_y
            desp_z = (-float(bounds_min[2]) if front_z_var.get() else float(row.desp_z)) + extra_z
            summary_text = (
                "Rotated bounds [mm]\n"
                "  min=({:.6g}, {:.6g}, {:.6g})\n"
                "  max=({:.6g}, {:.6g}, {:.6g})\n"
                "New row pose\n"
                "  TiltX={:.6g}, TiltY={:.6g}, TiltZ={:.6g}\n"
                "  DespX={:.6g}, DespY={:.6g}, DespZ={:.6g}".format(
                    *bounds_min,
                    *bounds_max,
                    tilts[0],
                    tilts[1],
                    tilts[2],
                    desp_x,
                    desp_y,
                    desp_z,
                )
            )
            return tilts, (desp_x, desp_y, desp_z), summary_text

        def refresh_preview(*_args) -> None:
            try:
                _tilts, _desp, summary_text = computed_pose()
                result_var.set("Computed pose is ready. Apply writes table values; click Update to trace.")
                text.configure(state="normal")
                text.delete("1.0", "end")
                text.insert("1.0", summary_text + "\n")
                text.configure(state="disabled")
            except Exception as exc:
                result_var.set(f"Placement preview failed: {_short_error_message(exc)}")

        def apply_pose() -> None:
            try:
                tilts, desp, summary_text = computed_pose()
            except Exception as exc:
                messagebox.showerror("Place/Orient Selected CAD/STL Solid", str(exc), parent=window)
                return
            self._begin_history_capture()
            target = self.rows[row_index]
            target.tilt_x, target.tilt_y, target.tilt_z = (float(value) for value in tilts)
            target.desp_x, target.desp_y, target.desp_z = (float(value) for value in desp)
            self._sync_table()
            self._select_table_row(row_index)
            self._commit_history_capture()
            self._mark_plot_update_pending()
            self.status_var.set(f"Placed/oriented STL solid S{row_index}. Click Update to trace.")
            self.append_debug(f"CAD/STL placement S{row_index}:\n{summary_text}")
            window.destroy()

        for var in (axis_var, center_xy_var, front_z_var, extra_x_var, extra_y_var, extra_z_var):
            try:
                var.trace_add("write", refresh_preview)
            except Exception:
                pass

        footer = ttk.Frame(frame)
        footer.grid(row=10, column=0, columnspan=3, sticky="ew", pady=(10, 0))
        ttk.Button(footer, text="Apply Pose", command=apply_pose).pack(side="right")
        ttk.Button(footer, text="Cancel", command=window.destroy).pack(side="right", padx=(0, 8))
        refresh_preview()

    def import_lens_step(self) -> None:
        path = self._ask_step_file("Import lens STEP", DEFAULT_LENS_STEP_PATH.parent)
        if path is None:
            return
        self._begin_history_capture()
        self.imported_lens_step_path = path
        self.lens_step_rotation_x_deg = 0.0
        self.lens_step_rotation_z_deg = 0.0
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self._selected_step_label = "lens"
        self._commit_history_capture()
        self.status_var.set(f"Lens STEP imported: {path.name}. Open or refresh 3D view.")
        self._refresh_open_3d_views()

    def import_camera_step(self) -> None:
        path = self._ask_step_file("Import camera STEP", DEFAULT_CAMERA_STEP_PATH.parent)
        if path is None:
            return
        self._begin_history_capture()
        self.imported_camera_step_path = path
        self.camera_step_rotation_x_deg = 0.0
        self.camera_step_rotation_z_deg = 0.0
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self._selected_step_label = "camera"
        self._commit_history_capture()
        self.status_var.set(f"Camera STEP imported: {path.name}. Open or refresh 3D view.")
        self._refresh_open_3d_views(camera_only=True)

    def rotate_camera_step_z(self, delta_deg: float) -> None:
        self.rotate_step_z("camera", delta_deg)

    def import_led_step(self) -> None:
        initial_dir = DEFAULT_LED_STEP_PATH if DEFAULT_LED_STEP_PATH.is_dir() else DEFAULT_LED_STEP_PATH.parent
        path = self._ask_step_file("Import LED STEP", initial_dir)
        if path is None:
            return
        initial_distance = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
        if initial_distance <= 0.0:
            initial_distance = self._default_led_object_edge_distance()
        edge_distance = self._ask_led_edge_distance(initial_distance)
        if edge_distance is None:
            self.status_var.set("LED STEP import cancelled.")
            return
        self._begin_history_capture()
        self.imported_led_step_path = path
        self.led_step_rotation_x_deg = 0.0
        self.led_step_rotation_z_deg = 0.0
        self.led_step_object_edge_local_z = None
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self._selected_step_label = "led"
        self._cad_led_object_edge_pick = False
        self.led_object_edge_distance_mm = float(edge_distance)
        self._commit_history_capture()
        self.status_var.set(
            f"LED STEP imported: {path.name}; edge distance={self.led_object_edge_distance_mm:.3g} mm."
        )
        self._refresh_open_3d_views(step_label="led")

    def _default_led_object_edge_distance(self) -> float:
        lens_front_z = max(float(self._lens_front_datum_z()), 0.0)
        if lens_front_z <= 1e-9:
            return 0.0
        return max(0.0, min(lens_front_z * 0.25, lens_front_z - 1.0))

    def set_led_edge_distance(self) -> None:
        current = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
        if current <= 0.0:
            current = self._default_led_object_edge_distance()
        value = self._ask_led_edge_distance(current)
        if value is None:
            return
        self._begin_history_capture()
        self.led_object_edge_distance_mm = float(value)
        self._commit_history_capture()
        self.status_var.set(f"LED edge distance: {self.led_object_edge_distance_mm:.3g} mm")
        self._refresh_open_3d_views(step_label="led")

    def _ask_led_edge_distance(self, initial_value: float) -> float | None:
        value_var = tk.StringVar(value=f"{max(float(initial_value), 0.0):g}")
        value_holder: dict[str, float] = {}

        dialog = tk.Toplevel(self)
        dialog.withdraw()
        dialog.title("LED Edge Distance")
        dialog.transient(self)
        dialog.grab_set()
        dialog.resizable(False, False)

        ttk.Label(
            dialog,
            text="Distance from object plane to the object-side LED box edge [mm]",
        ).grid(row=0, column=0, columnspan=2, padx=12, pady=(12, 6), sticky="w")
        entry = ttk.Entry(dialog, textvariable=value_var, width=18)
        entry.grid(row=1, column=0, columnspan=2, padx=12, pady=(0, 12), sticky="ew")

        def accept() -> None:
            try:
                value_holder["value"] = max(float(value_var.get()), 0.0)
            except ValueError:
                self.status_var.set("Invalid LED edge distance.")
                return
            dialog.destroy()

        ttk.Button(dialog, text="Save", command=accept).grid(row=2, column=0, padx=(12, 4), pady=(0, 12), sticky="e")
        ttk.Button(dialog, text="Cancel", command=dialog.destroy).grid(row=2, column=1, padx=(4, 12), pady=(0, 12), sticky="w")
        dialog.bind("<Return>", lambda _event: accept())
        dialog.bind("<Escape>", lambda _event: dialog.destroy())
        self._show_centered_dialog(dialog)
        entry.focus_set()
        self.wait_window(dialog)

        value = value_holder.get("value")
        return float(value) if value is not None else None

    def rotate_led_step_z(self, delta_deg: float) -> None:
        self.rotate_step_z("led", delta_deg)

    def start_led_object_edge_pick(self) -> None:
        if self.imported_led_step_path is None:
            self.status_var.set("No LED STEP is imported.")
            return
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = True
        self._selected_step_label = "led"
        message = "Pick the LED body edge used for Object-to-LED distance."
        self.status_var.set(message)
        if self._three_d_inspector is not None:
            try:
                self._three_d_inspector.status_var.set(message)
            except Exception:
                pass

    def _led_step_z_translation(self) -> float:
        target_edge_z = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
        reference_z = getattr(self, "led_step_object_edge_local_z", None)
        if reference_z is None:
            return target_edge_z
        try:
            return target_edge_z - float(reference_z)
        except Exception:
            return target_edge_z

    def apply_led_object_edge_pick(self, feature_center_xyz: np.ndarray) -> None:
        feature_center = np.asarray(feature_center_xyz, dtype=float)
        if feature_center.size < 3 or not np.all(np.isfinite(feature_center[:3])):
            self.status_var.set("Invalid LED object-edge pick.")
            return
        # Store the picked edge in the LED's transformed local Z frame. Future
        # placement shifts the whole STEP so this edge, not a cable extremum,
        # lands at the Object-to-LED distance.
        local_z = float(feature_center[2]) - self._led_step_z_translation()
        self._begin_history_capture()
        self.led_step_object_edge_local_z = local_z
        self._cad_led_object_edge_pick = False
        self._cad_axis_pick_label = None
        self._selected_step_label = "led"
        self._commit_history_capture()
        self.status_var.set(
            f"LED object edge locked. Local Z={local_z:.3g} mm; "
            f"edge distance={self.led_object_edge_distance_mm:.3g} mm."
        )
        self._refresh_open_3d_views(step_label="led")

    def rotate_step_z(self, label: str, delta_deg: float) -> None:
        label = str(label).strip().lower()
        if label not in {"lens", "led", "camera"}:
            return
        path = {
            "lens": self.imported_lens_step_path,
            "led": self.imported_led_step_path,
            "camera": self.imported_camera_step_path,
        }.get(label)
        if path is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return
        attr = f"{label}_step_rotation_z_deg"
        self._begin_history_capture()
        current = float(getattr(self, attr, 0.0))
        next_angle = float((current + float(delta_deg)) % 360.0)
        setattr(self, attr, next_angle)
        self._selected_step_label = label
        self._commit_history_capture()
        self.status_var.set(f"{label.upper()} STEP Z rotation: {next_angle:.0f} deg")
        self._refresh_open_3d_views(step_label=label)

    def rotate_selected_step_z(self, delta_deg: float) -> None:
        label = self._selected_step_label
        if label not in {"lens", "led", "camera"}:
            self.status_var.set("Select a STEP component in the 3D view first.")
            return
        self.rotate_step_z(label, delta_deg)

    def rotate_step_x(self, label: str, delta_deg: float) -> None:
        label = str(label).strip().lower()
        if label not in {"lens", "led", "camera"}:
            return
        path = {
            "lens": self.imported_lens_step_path,
            "led": self.imported_led_step_path,
            "camera": self.imported_camera_step_path,
        }.get(label)
        if path is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return
        attr = f"{label}_step_rotation_x_deg"
        self._begin_history_capture()
        current = float(getattr(self, attr, 0.0))
        next_angle = float((current + float(delta_deg)) % 360.0)
        setattr(self, attr, next_angle)
        self._selected_step_label = label
        self._commit_history_capture()
        self.status_var.set(f"{label.upper()} STEP X rotation: {next_angle:.0f} deg")
        self._refresh_open_3d_views(step_label=label)

    def rotate_selected_step_x(self, delta_deg: float) -> None:
        label = self._selected_step_label
        if label not in {"lens", "led", "camera"}:
            self.status_var.set("Select a STEP component in the 3D view first.")
            return
        self.rotate_step_x(label, delta_deg)

    def select_step_component(self, label: str) -> None:
        label = str(label).strip().lower()
        if label not in {"lens", "led", "camera"}:
            return
        self._selected_step_label = label
        self.status_var.set(f"Selected {label.upper()} STEP. Use Z +/-90, X 180, or Axis {label.title()}.")

    def start_step_axis_pick(self, label: str) -> None:
        label = str(label).strip().lower()
        if label not in {"lens", "led", "camera"}:
            return
        path = {
            "lens": self.imported_lens_step_path,
            "led": self.imported_led_step_path,
            "camera": self.imported_camera_step_path,
        }.get(label)
        if path is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return
        self._cad_axis_pick_label = label
        self._cad_led_object_edge_pick = False
        self._selected_step_label = label
        message = f"Pick a planar/circular feature on the {label} STEP to define its optical axis."
        self.status_var.set(message)
        if self._three_d_inspector is not None:
            try:
                self._three_d_inspector.status_var.set(message)
            except Exception:
                pass

    def _step_axis_offset_xy(self, label: str) -> tuple[float, float]:
        value = getattr(self, f"{label}_step_axis_offset_xy", (0.0, 0.0))
        try:
            return (float(value[0]), float(value[1]))
        except Exception:
            return (0.0, 0.0)

    def _set_step_axis_offset_xy(self, label: str, offset_xy: tuple[float, float]) -> None:
        if label not in {"lens", "led", "camera"}:
            return
        setattr(self, f"{label}_step_axis_offset_xy", (float(offset_xy[0]), float(offset_xy[1])))

    def _step_roll_deg(self, label: str) -> float:
        if label == "lens":
            return float(getattr(self, "lens_step_rotation_z_deg", 0.0))
        if label == "camera":
            return float(getattr(self, "camera_step_rotation_z_deg", 0.0))
        if label == "led":
            return float(getattr(self, "led_step_rotation_z_deg", 0.0))
        return 0.0

    def _step_x_rotation_deg(self, label: str) -> float:
        if label == "lens":
            return float(getattr(self, "lens_step_rotation_x_deg", 0.0))
        if label == "camera":
            return float(getattr(self, "camera_step_rotation_x_deg", 0.0))
        if label == "led":
            return float(getattr(self, "led_step_rotation_x_deg", 0.0))
        return 0.0

    def _step_target_front_z(self, label: str) -> float:
        if label == "lens":
            return float(self._lens_front_datum_z())
        if label == "camera":
            return float(self._current_image_plane_z() - self._current_camera_front_to_sensor_mm())
        if label == "led":
            return float(self._led_step_z_translation())
        return 0.0

    def apply_step_axis_pick(self, label: str, feature_center_xyz: np.ndarray) -> None:
        label = str(label).strip().lower()
        if label not in {"lens", "led", "camera"}:
            return
        feature_center = np.asarray(feature_center_xyz, dtype=float)
        if feature_center.size < 2 or not np.all(np.isfinite(feature_center[:2])):
            self.status_var.set(f"Invalid {label} CAD feature center.")
            return
        current = np.asarray(self._step_axis_offset_xy(label), dtype=float)
        # Stored offsets are in the STEP's pre-roll aligned frame. Convert the
        # picked display-space residual back so later rotations happen about
        # the picked optical axis instead of the STEP bounding-box center.
        z_angle = np.deg2rad(-self._step_roll_deg(label))
        cos_z = float(np.cos(z_angle))
        sin_z = float(np.sin(z_angle))
        rolled_x = (cos_z * float(feature_center[0])) - (sin_z * float(feature_center[1]))
        rolled_y = (sin_z * float(feature_center[0])) + (cos_z * float(feature_center[1]))
        rolled_z = 0.0
        if feature_center.size >= 3 and np.isfinite(feature_center[2]):
            rolled_z = float(feature_center[2]) - self._step_target_front_z(label)
        x_angle = np.deg2rad(self._step_x_rotation_deg(label))
        pre_x = rolled_x
        pre_y = (float(np.cos(x_angle)) * rolled_y) + (float(np.sin(x_angle)) * rolled_z)
        delta = np.array([pre_x, pre_y], dtype=float)
        new_offset = current + delta
        self._begin_history_capture()
        self._set_step_axis_offset_xy(label, (float(new_offset[0]), float(new_offset[1])))
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = False
        self._commit_history_capture()
        self.status_var.set(
            f"{label.upper()} STEP optical axis aligned from picked feature "
            f"(offset={new_offset[0]:.3g}, {new_offset[1]:.3g} mm)."
        )
        self._refresh_open_3d_views(step_label=label)

    def clear_step_axis_offsets(self) -> None:
        self._begin_history_capture()
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = False
        self._commit_history_capture()
        self.status_var.set("CAD STEP optical-axis offsets cleared.")
        self._refresh_open_3d_views()

    def clear_step_imports(self) -> None:
        self._begin_history_capture()
        self.imported_camera_step_path = None
        self.imported_lens_step_path = None
        self.imported_led_step_path = None
        self.camera_step_rotation_x_deg = 0.0
        self.lens_step_rotation_x_deg = 0.0
        self.led_step_rotation_x_deg = 0.0
        self.camera_step_rotation_z_deg = 0.0
        self.lens_step_rotation_z_deg = 0.0
        self.led_step_rotation_z_deg = 0.0
        self.led_object_edge_distance_mm = 0.0
        self.led_step_object_edge_local_z = None
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = False
        self._selected_step_label = None
        self._commit_history_capture()
        self.status_var.set("Camera/lens/LED STEP imports cleared.")
        self._refresh_open_3d_views()

    def _has_imported_step_cad(self) -> bool:
        return any(
            path is not None
            for path in (
                self.imported_lens_step_path,
                self.imported_led_step_path,
                self.imported_camera_step_path,
            )
        )

    def _step_export_alignment_params(self, label: str) -> dict[str, object] | None:
        label = str(label).strip().lower()
        if label == "lens":
            if self.imported_lens_step_path is None:
                return None
            cylinder_axis = self._step_primary_cylinder_axis(self.imported_lens_step_path)
            return {
                "path": self.imported_lens_step_path,
                "largest_component": True,
                "source_axis": cylinder_axis if cylinder_axis is not None else "pca0",
                "front_face": "max",
                "target_front_z": self._lens_front_datum_z(),
                "label": "Lens STEP",
                "roll_deg": float(getattr(self, "lens_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "lens_step_rotation_x_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("lens"),
            }
        if label == "camera":
            if self.imported_camera_step_path is None:
                return None
            camera_front_z = self._current_image_plane_z() - self._current_camera_front_to_sensor_mm()
            return {
                "path": self.imported_camera_step_path,
                "largest_component": True,
                "source_axis": "z",
                "front_face": "max",
                "target_front_z": camera_front_z,
                "label": "Camera STEP",
                "roll_deg": float(getattr(self, "camera_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "camera_step_rotation_x_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("camera"),
            }
        if label == "led":
            if self.imported_led_step_path is None:
                return None
            return {
                "path": self.imported_led_step_path,
                "largest_component": False,
                "source_axis": "z",
                "front_face": "min",
                "target_front_z": self._led_step_z_translation(),
                "label": "LED STEP",
                "roll_deg": float(getattr(self, "led_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "led_step_rotation_x_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("led"),
            }
        return None

    def _step_alignment_affine(self, params: dict[str, object]) -> np.ndarray | None:
        path = Path(params["path"])
        source_mesh = self._load_step_mesh(
            path,
            largest_component=bool(params.get("largest_component", False)),
        )
        aligned_mesh = self._cad_mesh_aligned_to_optical_axis(
            source_mesh,
            source_axis=params.get("source_axis", "z"),
            front_face=str(params.get("front_face", "min")),
            target_front_z=float(params.get("target_front_z", 0.0)),
            label=str(params.get("label", "STEP")),
            roll_deg=float(params.get("roll_deg", 0.0)),
            x_rotation_deg=float(params.get("x_rotation_deg", 0.0)),
            axis_offset_xy=params.get("axis_offset_xy"),
        )
        if aligned_mesh is None:
            return None
        matrix = _affine_from_point_sets(
            np.asarray(source_mesh.points, dtype=float),
            np.asarray(aligned_mesh.points, dtype=float),
        )
        return matrix

    def _collect_native_step_export_shapes(self, progress_callback=None) -> list[tuple[str, object]]:
        shape_items: list[tuple[str, object]] = []
        labels = ("lens", "led", "camera")
        for index, label in enumerate(labels, start=1):
            params = self._step_export_alignment_params(label)
            if params is None:
                continue
            if progress_callback is not None:
                progress_callback(
                    f"Preparing {params.get('label', label)} native STEP",
                    index,
                    len(labels),
                )
            try:
                matrix = self._step_alignment_affine(params)
                if matrix is None:
                    raise RuntimeError("could not compute CAD placement affine")
                shape = _read_step_shape(Path(params["path"]))
                shape_items.append((str(params.get("label", label)), _shape_with_affine(shape, matrix)))
            except Exception as exc:
                self.append_debug(f"3D STEP native {label} export skipped: {exc}")
        return shape_items

    def _step_export_ray_polylines(self, system) -> list[np.ndarray]:
        previous_ray_count = getattr(self, "_preview_field_ray_count", None)
        previous_bundle_count = getattr(self, "_preview_field_bundle_count", None)
        rays_per_group = previous_ray_count
        try:
            wavelength = self._current_wavelength()
            max_radius = max((max(float(row.diameter) / 2.0, 0.5) for row in self.rows), default=1.0)
            rays = Kos.raykeeper(system)
            self._trace_preview_rays(
                system,
                rays,
                wavelength,
                max_radius,
                allow_full_pupil=True,
                sampling_mode="world_envelope",
            )
            rays_per_group = getattr(self, "_preview_field_ray_count", previous_ray_count)
        except Exception as exc:
            self.append_debug(f"3D STEP ray export skipped: {exc}")
            rays = self.last_rays
        finally:
            if previous_ray_count is not None:
                self._preview_field_ray_count = previous_ray_count
            if previous_bundle_count is not None:
                self._preview_field_bundle_count = previous_bundle_count
        polylines: list[np.ndarray] = []
        for ray in getattr(rays, "CC", ()) if rays is not None else ():
            pts = np.asarray(ray, dtype=float)
            if pts.ndim != 2 or pts.shape[0] < 2 or pts.shape[1] < 3:
                continue
            if not np.any(np.all(np.isfinite(pts[:, :3]), axis=1)):
                continue
            polylines.append(pts[:, :3].copy())
        envelope = _ray_bundle_envelope_polylines(
            polylines,
            rays_per_group,
        )
        if len(envelope) < len(polylines):
            self.append_progress(
                f"STEP ray export reduced to envelope: {len(envelope)}/{len(polylines)} traced rays"
            )
        return envelope

    def _collect_3d_step_export_meshes(self, system) -> list[tuple[str, object]]:
        _load_3d_backends()
        if pv is None:
            raise RuntimeError("PyVista is required to collect 3D export geometry")

        mesh_items: list[tuple[str, object]] = []

        def add_mesh(label: str, mesh) -> None:
            if mesh is None:
                return
            try:
                surface = mesh.extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                try:
                    surface = mesh.copy(deep=True)
                except Exception:
                    return
            try:
                if int(getattr(surface, "n_points", 0)) > 0:
                    mesh_items.append((label, surface))
            except Exception:
                pass

        transforms = getattr(system, "TRANS_2A", None)
        surfaces = getattr(system, "AAA", None)
        if transforms is not None and surfaces is not None:
            block_count = min(len(self.rows), getattr(surfaces, "n_blocks", 0), len(transforms))
            for index in range(block_count):
                row = self.rows[index]
                if row.surface in {"Object", "Image"}:
                    continue
                add_mesh(
                    f"surface_{index}_{row.name or row.surface}",
                    Kraken3DInspector._mesh_with_transform(surfaces[index], transforms[index]),
                )

        side_index = 0
        for row_index in getattr(system, "side_number", []):
            try:
                body = pv.wrap(system.BBB[side_index]).extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                side_index += 1
                continue
            side_index += 1
            if 0 <= int(row_index) < len(self.rows):
                row = self.rows[int(row_index)]
                add_mesh(f"edge_{int(row_index)}_{row.name or row.surface}", body)
            else:
                add_mesh(f"edge_{int(row_index)}", body)

        try:
            add_mesh("external_camera", self._transformed_external_camera_mesh())
        except Exception as exc:
            self.append_debug(f"3D STEP export external camera skipped: {exc}")

        for label, builder in (
            ("lens_step", self._transformed_imported_lens_step_mesh),
            ("led_step", self._transformed_imported_led_step_mesh),
            ("camera_step", self._transformed_imported_camera_step_mesh),
        ):
            try:
                add_mesh(label, builder())
            except Exception as exc:
                self.append_debug(f"3D STEP export {label} skipped: {exc}")

        return mesh_items

    def _collect_step_edge_and_extra_meshes(self, system) -> list[tuple[str, object]]:
        """Collect edge geometry and imported meshes, excluding optical surface
        faces (which are handled analytically)."""
        _load_3d_backends()
        if pv is None:
            return []

        mesh_items: list[tuple[str, object]] = []

        def add_mesh(label: str, mesh) -> None:
            if mesh is None:
                return
            try:
                surface = mesh.extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                try:
                    surface = mesh.copy(deep=True)
                except Exception:
                    return
            try:
                if int(getattr(surface, "n_points", 0)) > 0:
                    mesh_items.append((label, surface))
            except Exception:
                pass

        side_index = 0
        for row_index in getattr(system, "side_number", []):
            try:
                body = pv.wrap(system.BBB[side_index]).extract_surface(
                    algorithm="dataset_surface"
                ).copy(deep=True)
            except Exception:
                side_index += 1
                continue
            side_index += 1
            if 0 <= int(row_index) < len(self.rows):
                row = self.rows[int(row_index)]
                add_mesh(f"edge_{int(row_index)}_{row.name or row.surface}", body)
            else:
                add_mesh(f"edge_{int(row_index)}", body)

        try:
            add_mesh("external_camera", self._transformed_external_camera_mesh())
        except Exception:
            pass

        for label, builder in (
            ("lens_step", self._transformed_imported_lens_step_mesh),
            ("led_step", self._transformed_imported_led_step_mesh),
            ("camera_step", self._transformed_imported_camera_step_mesh),
        ):
            try:
                add_mesh(label, builder())
            except Exception:
                pass

        return mesh_items

    def _ask_step_file(self, title: str, initial_dir: Path) -> Path | None:
        path = filedialog.askopenfilename(
            title=title,
            initialdir=str(initial_dir if initial_dir.exists() else Path.home()),
            filetypes=[
                ("STEP files", "*.step *.stp *.STEP *.STP *.SETP"),
                ("All files", "*"),
            ],
        )
        if not path:
            return None
        selected = Path(path).expanduser()
        if not selected.exists():
            messagebox.showerror("STEP file not found", f"File does not exist:\n\n{selected}", parent=self)
            return None
        return selected

    def _refresh_open_3d_views(self, *, camera_only: bool = False, step_label: str | None = None) -> None:
        if camera_only:
            step_label = "camera"
        if self._three_d_inspector is not None:
            try:
                if self._three_d_inspector.winfo_exists():
                    self._three_d_inspector.refresh_from_editor()
            except Exception:
                pass
        if self._legacy_3d_plotter is not None:
            labels = [step_label] if step_label else ["lens", "led", "camera"]
            refreshed = False
            for label in labels:
                if label and self._refresh_legacy_step_actor(self._legacy_3d_plotter, label):
                    refreshed = True
            if refreshed:
                return
            self.status_var.set("STEP change saved. Close and reopen legacy 3D view to redraw.")

    def _refresh_legacy_camera_step_actor(self, plotter) -> bool:
        return self._refresh_legacy_step_actor(plotter, "camera")

    def _refresh_legacy_step_actor(self, plotter, label: str) -> bool:
        if plotter is None:
            return False
        scene = dict(getattr(plotter, "_kraken_scene", {}) or {})
        cad_step_actors = dict(scene.get("cad_step_actors", {}) or {})
        cad_step_actor_map = dict(scene.get("cad_step_actor_map", {}) or {})
        step_actors = list(cad_step_actors.get(label, []) or [])
        visibility = dict(getattr(plotter, "_kraken_visibility", {}) or {})
        visible = bool(visibility.get(f"step_{label}", True))
        try:
            builders = {
                "camera": self._transformed_imported_camera_step_mesh,
                "led": self._transformed_imported_led_step_mesh,
                "lens": self._transformed_imported_lens_step_mesh,
            }
            builder = builders.get(label)
            if builder is None:
                return False
            cad_mesh = builder()
        except Exception as exc:
            self.append_debug(f"Legacy 3D {label} STEP refresh failed: {exc}")
            return False
        if cad_mesh is None or int(getattr(cad_mesh, "n_points", 0)) <= 0:
            if not step_actors:
                return False
            hidden = False
            for _kind, actor in step_actors:
                try:
                    actor.SetVisibility(False)
                    hidden = True
                except Exception:
                    pass
            if hidden:
                try:
                    plotter.render()
                except Exception:
                    pass
            return hidden
        try:
            edges = cad_mesh.extract_feature_edges(
                feature_angle=20,
                boundary_edges=True,
                feature_edges=True,
                manifold_edges=False,
            )
        except Exception:
            edges = None
        if not step_actors:
            try:
                color, opacity = {
                    "lens": ("#4b5563", 0.22),
                    "led": ("#f59e0b", 0.35),
                    "camera": ("#6b7280", 0.32),
                }.get(label, ("#6b7280", 0.32))
                helper_actors = list(scene.get("helper_actors", []) or [])
                cad_step_actors.setdefault(label, [])
                actor = plotter.add_mesh(
                    cad_mesh,
                    color=color,
                    opacity=opacity,
                    smooth_shading=False,
                    show_edges=False,
                    pickable=True,
                )
                try:
                    actor.SetPickable(True)
                except Exception:
                    pass
                actor_key = Kraken3DInspector._actor_key(actor)
                if actor_key is not None:
                    cad_step_actor_map[actor_key] = label
                try:
                    actor.SetVisibility(visible)
                except Exception:
                    pass
                cad_step_actors[label].append(("mesh", actor))
                if edges is not None and int(getattr(edges, "n_points", 0)) > 0:
                    edge_actor = plotter.add_mesh(edges, color="#111827", line_width=0.8, pickable=False)
                    try:
                        edge_actor.SetVisibility(visible)
                    except Exception:
                        pass
                    cad_step_actors[label].append(("edges", edge_actor))
                scene["helper_actors"] = helper_actors
                scene["cad_step_actors"] = cad_step_actors
                scene["cad_step_actor_map"] = cad_step_actor_map
                setattr(plotter, "_kraken_scene", scene)
                try:
                    plotter.render()
                except Exception:
                    pass
                return True
            except Exception as exc:
                self.append_debug(f"Legacy 3D {label} STEP add failed: {exc}")
                return False
        refreshed = False
        for kind, actor in step_actors:
            try:
                mapper = actor.GetMapper()
                if mapper is None:
                    continue
                if kind == "edges":
                    if edges is None or int(getattr(edges, "n_points", 0)) <= 0:
                        actor.SetVisibility(False)
                        continue
                    mapper.SetInputData(edges)
                    actor.SetVisibility(visible)
                else:
                    mapper.SetInputData(cad_mesh)
                    actor.SetVisibility(visible)
                mapper.Modified()
                refreshed = True
            except Exception as exc:
                self.append_debug(f"Legacy 3D {label} actor update failed: {exc}")
        if refreshed:
            try:
                plotter.render()
            except Exception:
                pass
            if label == "camera":
                self.status_var.set(
                    f"Camera STEP rotation: X={self.camera_step_rotation_x_deg:.0f}, "
                    f"Z={self.camera_step_rotation_z_deg:.0f} deg"
                )
            elif label == "lens":
                self.status_var.set(
                    f"Lens STEP rotation: X={self.lens_step_rotation_x_deg:.0f}, "
                    f"Z={self.lens_step_rotation_z_deg:.0f} deg"
                )
            elif label == "led":
                reference_text = (
                    "unset"
                    if getattr(self, "led_step_object_edge_local_z", None) is None
                    else f"{float(self.led_step_object_edge_local_z):.3g} mm"
                )
                self.status_var.set(
                    f"LED STEP: x rotation={self.led_step_rotation_x_deg:.0f} deg, "
                    f"z rotation={self.led_step_rotation_z_deg:.0f} deg, "
                    f"edge distance={self.led_object_edge_distance_mm:.3g} mm, "
                    f"edge ref={reference_text}"
                )
        return refreshed

