    def _register_left_mode_control(
        self,
        var_name: str,
        widget,
        relevant,
        *,
        normal_state: str = "normal",
        extra_widgets=(),
        include_label: bool = True,
    ) -> None:
        if not hasattr(self, "_left_mode_controls"):
            self._left_mode_controls = []
        managed_widgets = self._left_mode_control_grid_widgets(
            widget,
            extra_widgets=extra_widgets,
            include_label=include_label,
        )
        var = getattr(self, var_name, None)
        try:
            fallback = str(var.get()) if var is not None else ""
        except Exception:
            fallback = ""
        grid_records = []
        for managed_widget in managed_widgets:
            try:
                grid_records.append((managed_widget, dict(managed_widget.grid_info())))
            except Exception:
                pass
        self._left_mode_controls.append(
            {
                "var_name": var_name,
                "widget": widget,
                "managed_widgets": managed_widgets,
                "grid_records": grid_records,
                "relevant": relevant,
                "normal_state": normal_state,
                "fallback": fallback,
            }
        )

    @staticmethod
    def _left_mode_control_grid_widgets(widget, *, extra_widgets=(), include_label: bool = True) -> list:
        managed = []

        def add(candidate) -> None:
            if candidate is not None and candidate not in managed:
                managed.append(candidate)

        add(widget)
        try:
            grid_info = widget.grid_info()
            parent = widget.master
            row = int(grid_info.get("row", 0))
            column = int(grid_info.get("column", 0))
            columnspan = int(grid_info.get("columnspan", 1))
            label_row = row - 1
        except Exception:
            row = column = label_row = -1
            columnspan = 1
            parent = None
        if include_label and parent is not None and label_row >= 0:
            wanted = set(range(column, column + max(columnspan, 1)))
            try:
                for candidate in parent.grid_slaves(row=label_row):
                    if candidate is widget:
                        continue
                    info = candidate.grid_info()
                    candidate_column = int(info.get("column", 0))
                    candidate_span = int(info.get("columnspan", 1))
                    candidate_columns = set(range(candidate_column, candidate_column + max(candidate_span, 1)))
                    if wanted & candidate_columns:
                        add(candidate)
            except Exception:
                pass
        for candidate in extra_widgets or ():
            add(candidate)
        return managed

    def _register_source_mode_controls(self, **widgets) -> None:
        if hasattr(self, "field_type_menu"):
            self._register_left_mode_control(
                "field_type_var",
                self.field_type_menu,
                lambda: self._current_source_model() == SOURCE_MODEL_DEFAULT,
                normal_state="readonly",
            )
        if hasattr(self, "field_value_entry"):
            self._register_left_mode_control(
                "field_value_var",
                self.field_value_entry,
                lambda: self._current_source_model() == SOURCE_MODEL_DEFAULT,
            )
        if hasattr(self, "field_count_entry"):
            self._register_left_mode_control(
                "field_count_var",
                self.field_count_entry,
                lambda: self._current_source_model() == SOURCE_MODEL_DEFAULT,
            )
        self._register_left_mode_control(
            "pupil_pattern_var",
            self.pupil_pattern_menu,
            lambda: self._current_source_model() == SOURCE_MODEL_DEFAULT,
            normal_state="readonly",
        )
        self._register_left_mode_control(
            "source_radius_var",
            widgets["source_radius_entry"],
            lambda: self._current_source_model() in {
                "Collimated disk source",
                "Random circle source",
                "Random square source",
                "Random line source",
            },
        )
        self._register_left_mode_control(
            "source_cone_angle_var",
            widgets["source_cone_entry"],
            lambda: self._current_source_model() in {"Random circle source", "Random square source", "Random line source", "Random point cone"},
        )
        self._register_left_mode_control(
            "gaussian_input_mode_var",
            widgets["gaussian_input_mode_menu"],
            lambda: self._current_source_model() == "Gaussian beam",
            normal_state="readonly",
        )
        self._register_left_mode_control(
            "gaussian_waist_radius_var",
            widgets["gaussian_waist_entry"],
            lambda: self._current_source_model() == "Gaussian beam" and self._current_gaussian_input_mode() == GAUSSIAN_INPUT_MODE_DEFAULT,
        )
        self._register_left_mode_control(
            "gaussian_waist_offset_var",
            widgets["gaussian_offset_entry"],
            lambda: self._current_source_model() == "Gaussian beam" and self._current_gaussian_input_mode() == GAUSSIAN_INPUT_MODE_DEFAULT,
        )
        self._register_left_mode_control(
            "gaussian_beam_diameter_var",
            widgets["gaussian_diameter_entry"],
            lambda: self._current_source_model() == "Gaussian beam" and self._current_gaussian_input_mode() == "Diameter + divergence",
        )
        self._register_left_mode_control(
            "gaussian_full_divergence_var",
            widgets["gaussian_divergence_entry"],
            lambda: self._current_source_model() == "Gaussian beam" and self._current_gaussian_input_mode() == "Diameter + divergence",
        )
        self._register_left_mode_control(
            "gaussian_m2_var",
            widgets["gaussian_m2_entry"],
            lambda: self._current_source_model() == "Gaussian beam",
        )
        self._register_left_mode_control(
            "gaussian_waist_side_var",
            widgets["gaussian_waist_side_menu"],
            lambda: self._current_source_model() == "Gaussian beam" and self._current_gaussian_input_mode() == "Diameter + divergence",
            normal_state="readonly",
        )
        self._register_left_mode_control(
            "pupil_rad_var",
            widgets["pupil_rad_entry"],
            lambda: self._current_source_model() == SOURCE_MODEL_DEFAULT and self._current_pupil_pattern_label() == "R-theta",
        )
        self._register_left_mode_control(
            "pupil_theta_var",
            widgets["pupil_theta_entry"],
            lambda: self._current_source_model() == SOURCE_MODEL_DEFAULT and self._current_pupil_pattern_label() == "R-theta",
        )
        self._register_left_mode_control(
            "source_power_var",
            widgets["source_power_entry"],
            lambda: self._current_source_model() != SOURCE_MODEL_DEFAULT,
        )
        self._register_left_mode_control(
            "source_seed_var",
            widgets["source_seed_entry"],
            lambda: self._current_source_model() in {
                "Random circle source",
                "Random square source",
                "Random line source",
                "Random point cone",
            } or (self._current_source_model() == SOURCE_MODEL_DEFAULT and self._current_pupil_pattern_label() == "Random disk"),
        )
        for var_name, widget_name in (
            ("source_x_var", "source_x_entry"),
            ("source_y_var", "source_y_entry"),
            ("source_z_var", "source_z_entry"),
            ("source_l_var", "source_l_entry"),
            ("source_m_var", "source_m_entry"),
            ("source_n_var", "source_n_entry"),
        ):
            self._register_left_mode_control(
                var_name,
                widgets[widget_name],
                lambda: self._current_source_model() != SOURCE_MODEL_DEFAULT,
            )
        self._register_left_mode_control(
            "source_direction_preset_var",
            widgets["source_direction_preset_menu"],
            lambda: self._current_source_model() != SOURCE_MODEL_DEFAULT,
            normal_state="readonly",
        )
        self._register_left_mode_control(
            "source_angular_weight_var",
            widgets["source_angular_weight_menu"],
            lambda: self._current_source_model() in {"Random circle source", "Random square source"},
            normal_state="readonly",
        )
        self._register_left_mode_control(
            "",
            widgets["source_physical_note"],
            lambda: self._current_source_model() != SOURCE_MODEL_DEFAULT,
            include_label=False,
        )
        self._register_left_mode_control(
            "",
            widgets["source_summary_label"],
            lambda: True,
            include_label=False,
        )
        self._register_left_mode_control(
            "",
            widgets["source_manager_button"],
            lambda: True,
            include_label=False,
        )

    def _sync_left_mode_controls(self) -> None:
        controls = list(getattr(self, "_left_mode_controls", []) or [])
        if not controls:
            return
        saved = getattr(self, "_left_mode_saved_values", None)
        if saved is None:
            saved = {}
            self._left_mode_saved_values = saved
        for control in controls:
            var_name = str(control.get("var_name", ""))
            var = getattr(self, var_name, None)
            widget = control.get("widget")
            relevant = control.get("relevant")
            normal_state = str(control.get("normal_state", "normal"))
            if widget is None or not callable(relevant):
                continue
            try:
                is_relevant = bool(relevant())
            except Exception:
                is_relevant = True
            try:
                current = str(var.get())
            except Exception:
                current = ""
            if is_relevant:
                if current == "NA":
                    restored = saved.pop(var_name, str(control.get("fallback", "")))
                    if restored:
                        try:
                            var.set(restored)
                        except Exception:
                            pass
                try:
                    widget.configure(state=normal_state)
                except Exception:
                    pass
            else:
                if var is not None and current not in {"", "NA"}:
                    saved.setdefault(var_name, current)
                try:
                    widget.configure(state="disabled")
                except Exception:
                    pass
            control["visible"] = is_relevant
        self._sync_left_source_panel_layout()
        self._sync_left_field_panel_visibility()
        self._reflow_left_mode_controls()

    def _sync_left_source_panel_layout(self) -> None:
        is_default_source = self._current_source_model() == SOURCE_MODEL_DEFAULT
        span = 1 if is_default_source else 2
        for widget in (getattr(self, "source_model_label", None), getattr(self, "source_model_menu", None)):
            if widget is None:
                continue
            try:
                widget.grid_configure(columnspan=span)
            except Exception:
                pass

    def _sync_left_field_panel_visibility(self) -> None:
        field_panel = getattr(self, "field_panel", None)
        if field_panel is None:
            return
        try:
            if self._current_source_model() == SOURCE_MODEL_DEFAULT:
                field_panel.grid()
            else:
                field_panel.grid_remove()
        except Exception:
            pass

    def _reflow_left_mode_controls(self) -> None:
        controls = list(getattr(self, "_left_mode_controls", []) or [])
        if not controls:
            return
        managed_widgets = {
            widget
            for control in controls
            for widget in (control.get("managed_widgets") or ())
            if widget is not None
        }
        parent_controls: dict[tk.Widget, list[dict[str, object]]] = {}
        for index, control in enumerate(controls):
            visible = bool(control.get("visible", True))
            records = []
            parent = None
            for widget, original_info in control.get("grid_records", []) or []:
                if widget is None or not isinstance(original_info, dict) or not original_info:
                    continue
                widget_parent = getattr(widget, "master", None)
                if widget_parent is None:
                    continue
                if parent is None:
                    parent = widget_parent
                if widget_parent is not parent:
                    continue
                records.append((widget, dict(original_info)))
            if parent is not None and records:
                parent_controls.setdefault(parent, []).append(
                    {
                        "index": index,
                        "records": records,
                        "visible": visible,
                    }
                )

        for parent, panel_controls in parent_controls.items():
            fixed_cells: set[tuple[int, int]] = set()
            try:
                children = list(parent.grid_slaves())
            except Exception:
                children = []
            for child in children:
                if child in managed_widgets:
                    continue
                try:
                    info = child.grid_info()
                    row = int(info.get("row", 0))
                    column = int(info.get("column", 0))
                    rowspan = max(int(info.get("rowspan", 1)), 1)
                    columnspan = max(int(info.get("columnspan", 1)), 1)
                except Exception:
                    continue
                for rr in range(row, row + rowspan):
                    for cc in range(column, column + columnspan):
                        fixed_cells.add((rr, cc))

            items = []
            for control in panel_controls:
                records = list(control.get("records") or [])
                if not bool(control.get("visible", True)):
                    for widget, _info in records:
                        try:
                            widget.grid_remove()
                        except Exception:
                            pass
                    continue

                parsed = []
                for widget, info in records:
                    try:
                        row = int(info.get("row", 0))
                        column = int(info.get("column", 0))
                        rowspan = max(int(info.get("rowspan", 1)), 1)
                        columnspan = max(int(info.get("columnspan", 1)), 1)
                    except Exception:
                        row = column = 0
                        rowspan = columnspan = 1
                    parsed.append(
                        {
                            "widget": widget,
                            "info": info,
                            "row": row,
                            "column": column,
                            "rowspan": rowspan,
                            "columnspan": columnspan,
                        }
                    )
                if not parsed:
                    continue

                base_row = min(int(record["row"]) for record in parsed)
                base_column = min(int(record["column"]) for record in parsed)
                max_column = max(int(record["column"]) + int(record["columnspan"]) for record in parsed)
                if any(int(record["columnspan"]) > 1 for record in parsed):
                    kind = "wide"
                elif max_column - base_column > 1:
                    kind = "multi"
                else:
                    kind = "single"
                height = max(
                    int(record["row"]) - base_row + int(record["rowspan"])
                    for record in parsed
                )
                items.append(
                    {
                        "index": int(control.get("index", 0)),
                        "records": parsed,
                        "base_row": base_row,
                        "base_column": base_column,
                        "kind": kind,
                        "height": max(height, 1),
                    }
                )

            if not items:
                continue

            items.sort(key=lambda item: (int(item["base_row"]), int(item["base_column"]), int(item["index"])))
            occupied = set(fixed_cells)
            first_row = min(int(item["base_row"]) for item in items)
            cursor_row = first_row

            def cells_for_item(item: dict[str, object], target_row: int, target_column: int) -> list[tuple[int, int]]:
                kind = str(item["kind"])
                cells: list[tuple[int, int]] = []
                for record in item["records"]:
                    row_delta = int(record["row"]) - int(item["base_row"])
                    rowspan = int(record["rowspan"])
                    if kind == "wide":
                        column = 0
                        columnspan = 2
                    elif kind == "multi":
                        column = int(record["column"]) - int(item["base_column"])
                        columnspan = int(record["columnspan"])
                    else:
                        column = target_column
                        columnspan = 1
                    for rr in range(target_row + row_delta, target_row + row_delta + rowspan):
                        for cc in range(column, column + columnspan):
                            cells.append((rr, cc))
                return cells

            def first_available_slot(item: dict[str, object], start_row: int) -> tuple[int, int]:
                columns = (0, 1) if str(item["kind"]) == "single" else (0,)
                target_row = max(start_row, first_row)
                while target_row < first_row + 200:
                    for target_column in columns:
                        cells = cells_for_item(item, target_row, target_column)
                        if not any(cell in occupied for cell in cells):
                            return target_row, target_column
                    target_row += 1
                return target_row, 0

            for item in items:
                target_row, target_column = first_available_slot(item, cursor_row)
                occupied.update(cells_for_item(item, target_row, target_column))
                for record in item["records"]:
                    info = dict(record["info"])
                    row_delta = int(record["row"]) - int(item["base_row"])
                    info["row"] = target_row + row_delta
                    kind = str(item["kind"])
                    if kind == "wide":
                        info["column"] = 0
                        info["columnspan"] = 2
                    elif kind == "multi":
                        info["column"] = int(record["column"]) - int(item["base_column"])
                    else:
                        info["column"] = target_column
                        info["columnspan"] = 1
                        info["padx"] = (8, 0) if target_column else (0, 0)
                    try:
                        record["widget"].grid(**info)
                    except Exception:
                        pass
                if str(item["kind"]) != "single":
                    cursor_row = max(cursor_row, target_row + int(item["height"]))

    def _left_mode_text(self, var_name: str, fallback: str = "") -> str:
        var = getattr(self, var_name, None)
        try:
            text = str(var.get()).strip() if var is not None else str(fallback)
        except Exception:
            text = str(fallback)
        if text == "NA":
            saved = getattr(self, "_left_mode_saved_values", {}) or {}
            text = str(saved.get(var_name, fallback)).strip()
        return text

    def _build_atmosphere_panel(self, parent) -> None:
        for column in range(2):
            parent.columnconfigure(column, weight=1)

        ttk.Label(parent, text="Observatory preset").grid(row=0, column=0, sticky="w", pady=(0, 2))
        self.atmos_observatory_var = tk.StringVar(value="Manual")
        self.atmos_observatory_menu = ttk.Combobox(
            parent,
            textvariable=self.atmos_observatory_var,
            state="readonly",
            width=16,
            values=self._atmos_observatory_names(),
        )
        self.atmos_observatory_menu.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        self.atmos_observatory_menu.bind("<FocusIn>", self._begin_history_capture, add="+")
        self.atmos_observatory_menu.bind("<<ComboboxSelected>>", self._on_atmos_observatory_changed)

        ttk.Label(parent, text="Atmos plot").grid(row=2, column=0, sticky="w", pady=(0, 2))
        self.atmos_plot_mode_var = tk.StringVar(value=ATMOS_PLOT_MODE_DEFAULT)
        self.atmos_plot_mode_menu = ttk.Combobox(
            parent,
            textvariable=self.atmos_plot_mode_var,
            state="readonly",
            width=16,
            values=ATMOS_PLOT_MODE_VALUES,
        )
        self.atmos_plot_mode_menu.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        self.atmos_plot_mode_menu.bind("<FocusIn>", self._begin_history_capture, add="+")
        self.atmos_plot_mode_menu.bind("<<ComboboxSelected>>", self._mark_plot_update_pending)

        controls = (
            ("Min wavelength [um]", "atmos_wavelength_min_var", "0.45"),
            ("Max wavelength [um]", "atmos_wavelength_max_var", "0.75"),
            ("Samples", "atmos_wavelength_count_var", "11"),
            ("Zenith angle [deg]", "atmos_zenith_deg_var", "45.0"),
            ("Temperature [K]", "atmos_temperature_k_var", "283.15"),
            ("Pressure [Pa]", "atmos_pressure_pa_var", "101300"),
            ("Humidity [0-1]", "atmos_humidity_var", "0.5"),
            ("CO2 [ppm]", "atmos_co2_ppm_var", "400"),
            ("Latitude [deg]", "atmos_latitude_deg_var", "31.0"),
            ("Altitude [m]", "atmos_altitude_m_var", "2800"),
        )
        entries: list[ttk.Entry] = []
        for index, (label, attr_name, default) in enumerate(controls):
            row = 4 + (index // 2) * 2
            column = index % 2
            ttk.Label(parent, text=label).grid(
                row=row,
                column=column,
                sticky="w",
                pady=(0 if row == 0 else 6, 2),
                padx=(8 if column else 0, 0),
            )
            var = tk.StringVar(value=default)
            setattr(self, attr_name, var)
            entry = ttk.Entry(parent, textvariable=var, width=12)
            entry.grid(row=row + 1, column=column, sticky="ew", padx=(8 if column else 0, 0))
            entries.append(entry)

        self.atmosphere_summary_var = tk.StringVar(value="")
        ttk.Label(
            parent,
            textvariable=self.atmosphere_summary_var,
            foreground="#3f4a5a",
            wraplength=460,
            justify="left",
        ).grid(row=14, column=0, columnspan=2, sticky="ew", pady=(8, 0))

        for entry in entries:
            self._bind_deferred_manual_update(entry)
        for _label, attr_name, _default in controls:
            var = getattr(self, attr_name)
            var.trace_add("write", lambda *_args: self._update_atmosphere_summary())
        self.atmos_plot_mode_var.trace_add("write", lambda *_args: self._update_atmosphere_summary())
        self._update_atmosphere_summary()

    def open_atmosphere_settings_dialog(self) -> None:
        window = self.__dict__.get("_atmosphere_settings_window")
        if window is not None:
            try:
                if window.winfo_exists():
                    window.deiconify()
                    window.lift()
                    window.focus_force()
                    return
            except Exception:
                pass

        window = tk.Toplevel(self)
        self._atmosphere_settings_window = window
        window.title("Atmospheric Settings")
        window.transient(self)
        window.protocol("WM_DELETE_WINDOW", self._close_atmosphere_settings_dialog)
        window.columnconfigure(0, weight=1)

        root = ttk.Frame(window, padding=12)
        root.grid(row=0, column=0, sticky="nsew")
        for column in range(2):
            root.columnconfigure(column, weight=1)

        ttk.Label(
            root,
            text=(
                "Atmospheric refraction/dispersion settings are advanced analysis inputs. "
                "Use the Atmos analysis button after changing these values."
            ),
            foreground="#475569",
            wraplength=520,
            justify="left",
        ).grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 10))

        ttk.Label(root, text="Observatory preset").grid(row=1, column=0, sticky="w", pady=(0, 2))
        observatory_menu = ttk.Combobox(
            root,
            textvariable=self.atmos_observatory_var,
            state="readonly",
            values=self._atmos_observatory_names(),
            width=20,
        )
        observatory_menu.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        observatory_menu.bind("<FocusIn>", self._begin_history_capture, add="+")
        observatory_menu.bind("<<ComboboxSelected>>", self._on_atmos_observatory_changed)

        ttk.Label(root, text="Atmos plot").grid(row=3, column=0, sticky="w", pady=(0, 2))
        plot_menu = ttk.Combobox(
            root,
            textvariable=self.atmos_plot_mode_var,
            state="readonly",
            values=ATMOS_PLOT_MODE_VALUES,
            width=20,
        )
        plot_menu.grid(row=4, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        plot_menu.bind("<FocusIn>", self._begin_history_capture, add="+")
        plot_menu.bind("<<ComboboxSelected>>", self._mark_plot_update_pending)

        controls = (
            ("Min wavelength [um]", "atmos_wavelength_min_var"),
            ("Max wavelength [um]", "atmos_wavelength_max_var"),
            ("Samples", "atmos_wavelength_count_var"),
            ("Zenith angle [deg]", "atmos_zenith_deg_var"),
            ("Temperature [K]", "atmos_temperature_k_var"),
            ("Pressure [Pa]", "atmos_pressure_pa_var"),
            ("Humidity [0-1]", "atmos_humidity_var"),
            ("CO2 [ppm]", "atmos_co2_ppm_var"),
            ("Latitude [deg]", "atmos_latitude_deg_var"),
            ("Altitude [m]", "atmos_altitude_m_var"),
        )
        entries: list[ttk.Entry] = []
        for index, (label, attr_name) in enumerate(controls):
            row = 5 + (index // 2) * 2
            column = index % 2
            ttk.Label(root, text=label).grid(
                row=row,
                column=column,
                sticky="w",
                pady=(6, 2),
                padx=(8 if column else 0, 0),
            )
            entry = ttk.Entry(root, textvariable=getattr(self, attr_name), width=14)
            entry.grid(row=row + 1, column=column, sticky="ew", padx=(8 if column else 0, 0))
            self._bind_deferred_manual_update(entry)
            entries.append(entry)

        ttk.Label(
            root,
            textvariable=self.atmosphere_summary_var,
            foreground="#3f4a5a",
            wraplength=520,
            justify="left",
        ).grid(row=16, column=0, columnspan=2, sticky="ew", pady=(10, 0))

        buttons = ttk.Frame(root)
        buttons.grid(row=17, column=0, columnspan=2, sticky="e", pady=(12, 0))
        ttk.Button(
            buttons,
            text="Apply",
            command=lambda: (self._update_atmosphere_summary(), self._mark_plot_update_pending()),
        ).pack(side="left")
        ttk.Button(
            buttons,
            text="Apply + Atmos",
            command=lambda: (
                self._update_atmosphere_summary(),
                None if "atmosphere" in self.selected_analysis_modes else self.toggle_analysis_mode("atmosphere"),
                self._mark_plot_update_pending(),
            ),
        ).pack(side="left", padx=(8, 0))
        ttk.Button(buttons, text="Close", command=self._close_atmosphere_settings_dialog).pack(side="left", padx=(8, 0))

        self._show_centered_dialog(window)

    def _close_atmosphere_settings_dialog(self) -> None:
        window = self.__dict__.get("_atmosphere_settings_window")
        self._atmosphere_settings_window = None
        if window is not None:
            try:
                window.destroy()
            except Exception:
                pass

    def _on_control_stack_configure(self, _event=None) -> None:
        if not hasattr(self, "control_canvas"):
            return
        self.control_canvas.configure(scrollregion=self.control_canvas.bbox("all"))

    def _on_control_canvas_configure(self, event=None) -> None:
        if not hasattr(self, "control_canvas") or not hasattr(self, "control_stack_window"):
            return
        width = self.control_canvas.winfo_width() if event is None else int(event.width)
        self.control_canvas.itemconfigure(self.control_stack_window, width=max(width, 1))

    def _on_left_panel_mousewheel(self, event=None):
        canvas = getattr(self, "control_canvas", None)
        if canvas is None or event is None:
            return None
        try:
            pointer_x = canvas.winfo_pointerx()
            pointer_y = canvas.winfo_pointery()
            canvas_x = canvas.winfo_rootx()
            canvas_y = canvas.winfo_rooty()
            inside_canvas = (
                canvas_x <= pointer_x < canvas_x + canvas.winfo_width()
                and canvas_y <= pointer_y < canvas_y + canvas.winfo_height()
            )
        except Exception:
            return None
        if not inside_canvas:
            return None
        try:
            bbox = canvas.bbox("all")
            if not bbox or int(bbox[3] - bbox[1]) <= canvas.winfo_height():
                return "break"
        except Exception:
            pass

        delta = 0
        if getattr(event, "num", None) == 4:
            delta = -1
        elif getattr(event, "num", None) == 5:
            delta = 1
        else:
            wheel_delta = int(getattr(event, "delta", 0) or 0)
            if wheel_delta:
                delta = -max(1, abs(wheel_delta) // 120) if wheel_delta > 0 else max(1, abs(wheel_delta) // 120)
        if delta:
            try:
                canvas.yview_scroll(delta, "units")
            except Exception:
                return None
            return "break"
        return None

    def _update_field_status_hint(self) -> None:
        if not hasattr(self, "status_hint_var"):
            return
        note = self.field_mode_note_var.get().strip() if hasattr(self, "field_mode_note_var") else ""
        warning = self.field_warning_var.get().strip() if hasattr(self, "field_warning_var") else ""
        summary = self.field_summary_var.get().strip() if hasattr(self, "field_summary_var") else ""
        summary = summary.replace("\n", " | ")
        parts = [part for part in (note, warning, summary) if part]
        self.status_hint_var.set("  ||  ".join(parts))

    def _build_optimization_panel(self, parent) -> None:
        operand_list_width = max((len(spec.label) for spec in OPERAND_REGISTRY.values()), default=14) + 2
        operand_list_minsize = max(150, operand_list_width * 8)
        parent.columnconfigure(0, weight=0, minsize=operand_list_minsize)
        parent.columnconfigure(1, weight=1, minsize=220)

        button_row = ttk.Frame(parent)
        button_row.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        ttk.Button(button_row, text="Start Optimization", command=self.start_optimization).pack(side="left")
        ttk.Button(button_row, text="Stop", command=self.stop_optimization).pack(side="left", padx=(8, 0))
        ttk.Button(button_row, text="Check Backend", command=self.check_optimization_backend).pack(
            side="left",
            padx=(8, 0),
        )
        cpu_total = max(1, int(os.cpu_count() or 1))
        worker_choices = ["Auto", "1"]
        for candidate in (2, 4, 6, 8, 12, 16, cpu_total):
            candidate = max(1, min(cpu_total, int(candidate)))
            text = str(candidate)
            if text not in worker_choices:
                worker_choices.append(text)
        ttk.Label(button_row, text="Workers").pack(side="left", padx=(14, 0))
        self.optimization_workers_var = tk.StringVar(value="Auto")
        ttk.Combobox(
            button_row,
            textvariable=self.optimization_workers_var,
            state="readonly",
            width=6,
            values=worker_choices,
        ).pack(side="left", padx=(6, 0))

        ttk.Label(parent, text="Merit operands").grid(row=1, column=0, sticky="w", pady=(0, 2))
        self.merit_mode_list = tk.Listbox(
            parent,
            exportselection=False,
            selectmode="extended",
            height=min(4, max(2, len(OPERAND_REGISTRY))),
            width=operand_list_width,
        )
        for spec in OPERAND_REGISTRY.values():
            self.merit_mode_list.insert("end", spec.label)
        if OPERAND_REGISTRY:
            self.merit_mode_list.selection_set(0)
        self.merit_mode_list.grid(row=2, column=0, sticky="nsw", pady=(0, 8), padx=(0, 8))
        self.merit_mode_list.bind("<ButtonPress-1>", self._begin_history_capture, add="+")
        self.merit_mode_list.bind("<<ListboxSelect>>", lambda _e: self._update_operand_setup_visibility())

        setup_holder = ttk.Frame(parent, height=320)
        setup_holder.grid(row=2, column=1, sticky="nsew", pady=(0, 8), padx=(4, 0))
        setup_holder.grid_propagate(False)
        setup_holder.columnconfigure(0, weight=1)
        setup_holder.rowconfigure(0, weight=1)

        setup_frame = ttk.Frame(setup_holder)
        setup_frame.grid(row=0, column=0, sticky="nsew")
        setup_frame.columnconfigure(0, weight=1, minsize=220)
        ttk.Label(setup_frame, text="Operand setup").grid(row=0, column=0, sticky="w", pady=(0, 2))

        for idx, spec in enumerate(OPERAND_REGISTRY.values(), start=1):
            card = ttk.LabelFrame(setup_frame, text=spec.label, padding=6)
            card.grid(row=idx, column=0, sticky="ew", pady=(0, 8))
            card.columnconfigure(1, weight=1, minsize=120)
