    @staticmethod
    def _safe_float(value, default: float = 0.0) -> float:
        try:
            result = float(value)
        except Exception:
            return default
        if not np.isfinite(result):
            return default
        return result

    @staticmethod
    def _safe_positive_float(value, default: float = 0.0) -> float:
        try:
            result = float(value)
        except Exception:
            return default
        if not np.isfinite(result):
            return default
        return max(result, 0.0)

    @staticmethod
    def _safe_complex(value, default: complex = complex(1.0, 0.0)) -> complex:
        try:
            result = complex(value)
        except Exception:
            return default
        if not np.isfinite(result.real) or not np.isfinite(result.imag):
            return default
        return result

    @classmethod
    def _normalize_jones_pair(cls, p_value, s_value) -> tuple[complex, complex]:
        p_component = cls._safe_complex(p_value, complex(1.0, 0.0))
        s_component = cls._safe_complex(s_value, complex(0.0, 0.0))
        norm = float(np.sqrt((abs(p_component) ** 2.0) + (abs(s_component) ** 2.0)))
        if not np.isfinite(norm) or norm <= 1e-15:
            return complex(1.0, 0.0), complex(0.0, 0.0)
        return p_component / norm, s_component / norm

    @staticmethod
    def _normalize_complex_vector(value) -> np.ndarray:
        try:
            vector = np.asarray(value, dtype=np.complex128).reshape(-1)[:3]
        except Exception:
            vector = np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        if vector.size < 3:
            vector = np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        if not np.all(np.isfinite(vector.real) & np.isfinite(vector.imag)):
            vector = np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        norm = float(np.sqrt(np.sum(np.abs(vector) ** 2.0)))
        if not np.isfinite(norm) or norm <= 1e-15:
            return np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        return vector / norm

    @staticmethod
    def _format_jones_value(value) -> str:
        try:
            component = complex(value)
        except Exception:
            return ""
        sign = "+" if component.imag >= 0.0 else "-"
        return f"{component.real:.4g}{sign}{abs(component.imag):.4g}j"

    def _branch_output_label(self, branch_path: str) -> str:
        selectors = self._branch_path_selector_sequence(branch_path)
        if not selectors:
            return "Primary path"
        code = "".join(selectors)
        tail = "".join(selectors[-2:])
        if tail in {"TR", "RT"}:
            return "Detector output port"
        if tail in {"TT", "RR"}:
            return "Source return port"
        if len(selectors) == 1:
            return "Transmit path" if selectors[0] == "T" else "Reflect path" if selectors[0] == "R" else f"{selectors[0]} path"
        return f"Path {code}"

    def _terminal_surface_label(self, surface_index, fallback_name: str = "") -> str:
        try:
            index = int(surface_index)
        except Exception:
            return str(fallback_name or "No terminal surface").strip()
        if not (0 <= index < len(self.rows)):
            return str(fallback_name or f"S{index}").strip()
        row = self.rows[index]
        metadata = self._element_metadata(row)
        element = self._element_key(row) or str(metadata.get("element_name", "") or "").strip()
        name = str(getattr(row, "name", "") or fallback_name or "").strip()
        role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT)
        prefix = "Detector" if role == "Detector" or self._row_has_detector_output_metadata(row) else str(row.surface or "Surface")
        label = element or name or f"S{index}"
        return f"S{index} {prefix}: {label}"

    def _surface_index_is_detector(self, surface_index) -> bool:
        try:
            index = int(surface_index)
        except Exception:
            return False
        if not (0 <= index < len(self.rows)):
            return False
        row = self.rows[index]
        metadata = self._element_metadata(row)
        role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT)
        return role == "Detector" or row.surface == "Image" or self._row_has_detector_output_metadata(row)

    def _source_illumination_target_priority(self, surface_index: int) -> int:
        if not (0 <= int(surface_index) < len(self.rows)):
            return 99
        row = self.rows[int(surface_index)]
        if self._surface_index_is_detector(surface_index):
            return 0
        if row.surface in {OBJECT_TARGET_SURFACE, DIFFUSE_OBJECT_SURFACE, "Object"}:
            return 1
        if row.surface == "Aperture":
            return 2
        return 3

    def _source_illumination_auto_target_index(self) -> int | None:
        hit_surfaces: set[int] = set()
        for record in self._collect_ray_inspector_records():
            for hit in list(record.get("hits", []) or []):
                try:
                    surface_index = int(hit.get("surface"))
                except Exception:
                    continue
                if 0 <= surface_index < len(self.rows):
                    hit_surfaces.add(surface_index)

        if hit_surfaces:
            return min(
                hit_surfaces,
                key=lambda index: (
                    self._source_illumination_target_priority(index),
                    -index,
                ),
            )

        detector_candidates = [
            index
            for index, _row in enumerate(self.rows)
            if self._surface_index_is_detector(index)
        ]
        if detector_candidates:
            return max(detector_candidates)
        return len(self.rows) - 1 if self.rows else None

    def _detector_settings_for_surface(self, surface_index) -> dict[str, object]:
        try:
            index = int(surface_index)
        except Exception:
            return _normalize_detector_settings({})
        if not (0 <= index < len(self.rows)):
            return _normalize_detector_settings({})
        return self._detector_settings(self.rows[index])

    @staticmethod
    def _single_terminal_surface_from_samples(samples: dict[str, object]) -> int | None:
        surfaces: set[int] = set()
        for surface in list(samples.get("terminal_surfaces", []) or []):
            try:
                surfaces.add(int(surface))
            except Exception:
                pass
        if len(surfaces) != 1:
            return None
        return next(iter(surfaces))

    def _detector_model_for_samples(self, samples: dict[str, object]) -> dict[str, object]:
        surface_index = self._single_terminal_surface_from_samples(samples)
        settings = self._detector_settings_for_surface(surface_index) if surface_index is not None else _normalize_detector_settings({})
        active_width = float(settings.get("active_width_mm", 0.0))
        active_height = float(settings.get("active_height_mm", 0.0))
        if surface_index is not None and 0 <= surface_index < len(self.rows):
            diameter = self._safe_positive_float(getattr(self.rows[surface_index], "diameter", 0.0), 0.0)
            if active_width <= 0.0 and diameter > 0.0:
                active_width = diameter
            if active_height <= 0.0 and diameter > 0.0:
                active_height = diameter
        return {
            "surface_index": surface_index,
            "settings": settings,
            "active_width_mm": active_width,
            "active_height_mm": active_height,
            "bins": str(settings.get("bins", "") or ""),
            "pixel_pitch_um": float(settings.get("pixel_pitch_um", 0.0)),
        }

    def _collect_branch_throughput_records(self) -> list[dict[str, object]]:
        ray_records = self._collect_ray_inspector_records()
        if not ray_records:
            return []

        source_input: dict[tuple[int, int], float] = {}
        groups: dict[tuple[str, str, str, int | None], dict[str, object]] = {}
        for record in ray_records:
            field_index = int(record.get("field_index", 0) or 0)
            source_ray_index = int(record.get("source_ray_index", record.get("ray_index", 0)) or 0)
            source_weight = self._safe_positive_float(record.get("source_weight"), 1.0)
            source_power = self._safe_positive_float(record.get("source_power"), 1.0)
            source_key = (field_index, source_ray_index)
            source_input[source_key] = max(source_input.get(source_key, 0.0), source_weight * source_power)

            branch_path = str(record.get("branch_path", "") or "").strip()
            branch_code = "".join(self._branch_path_selector_sequence(branch_path)) or "primary"
            output_label = self._branch_output_label(branch_path)
            last_surface = record.get("last_surface")
            terminal = self._terminal_surface_label(last_surface, str(record.get("last_name", "") or ""))
            key = (output_label, branch_code, branch_path, int(last_surface) if last_surface is not None else None)
            entry = groups.get(key)
            if entry is None:
                entry = {
                    "output": output_label,
                    "branch_code": branch_code,
                    "branch_path": branch_path or "primary",
                    "terminal": terminal,
                    "terminal_surface": "" if last_surface is None else int(last_surface),
                    "ray_count": 0,
                    "source_ray_count": 0,
                    "_sources": set(),
                    "detector_hits": 0,
                    "power_sum": 0.0,
                    "distance_weighted_sum": 0.0,
                    "op_weighted_sum": 0.0,
                }
                groups[key] = entry

            branch_power = self._safe_positive_float(record.get("branch_power"), np.nan)
            if not np.isfinite(branch_power):
                branch_power = self._safe_positive_float(record.get("transmission"), 1.0)
            effective_power = branch_power * source_weight * source_power
            entry["ray_count"] = int(entry["ray_count"]) + 1
            entry["_sources"].add(source_key)  # type: ignore[union-attr]
            if self._surface_index_is_detector(last_surface):
                entry["detector_hits"] = int(entry["detector_hits"]) + 1
            entry["power_sum"] = float(entry["power_sum"]) + effective_power
            distance = self._safe_positive_float(record.get("distance"), 0.0)
            op = self._safe_positive_float(record.get("op"), 0.0)
            entry["distance_weighted_sum"] = float(entry["distance_weighted_sum"]) + effective_power * distance
            entry["op_weighted_sum"] = float(entry["op_weighted_sum"]) + effective_power * op

        total_input = float(sum(source_input.values()))
        records: list[dict[str, object]] = []
        for entry in groups.values():
            power_sum = float(entry["power_sum"])
            source_set = set(entry.pop("_sources", set()) or set())
            entry["source_ray_count"] = len(source_set)
            entry["throughput"] = power_sum / total_input if total_input > 0.0 else np.nan
            entry["mean_distance"] = float(entry["distance_weighted_sum"]) / power_sum if power_sum > 0.0 else np.nan
            entry["mean_op"] = float(entry["op_weighted_sum"]) / power_sum if power_sum > 0.0 else np.nan
            entry["total_input_power"] = total_input
            records.append(entry)

        records.sort(
            key=lambda item: (
                str(item.get("output", "")),
                str(item.get("branch_code", "")),
                str(item.get("terminal", "")),
                str(item.get("branch_path", "")),
            )
        )
        return records

    def _source_illumination_target_choices(self) -> list[str]:
        choices = ["Auto"]
        for index, row in enumerate(self.rows):
            choices.append(f"{index}: {row.name or row.surface}")
        return choices

    def _source_illumination_target_index(self) -> int | None:
        target_var = self.__dict__.get("_source_illumination_target_var")
        value = (
            str(target_var.get()).strip()
            if target_var is not None
            else "Auto"
        )
        if value and value != "Auto":
            try:
                index = int(value.split(":", 1)[0].strip())
                if 0 <= index < len(self.rows):
                    return index
            except Exception:
                pass
        analysis_var = self.__dict__.get("analysis_surface_var")
        analysis_text = str(analysis_var.get()).strip() if analysis_var is not None else "Auto"
        if analysis_text and analysis_text != "Auto":
            try:
                analysis_index = int(analysis_text.split(":", 1)[0].strip())
                if 0 <= analysis_index < len(self.rows):
                    return analysis_index
            except Exception:
                pass
        nonseq_target_index = self._current_nonseq_target_surface_index()
        if nonseq_target_index is not None:
            return nonseq_target_index
        return self._source_illumination_auto_target_index()

    @staticmethod
    def _finite_centroid_and_rms(points: list[tuple[float, float, float]]) -> tuple[float, float, float, float, float, float, float]:
        arr = np.asarray(points, dtype=float).reshape(-1, 3) if points else np.empty((0, 3), dtype=float)
        if arr.size == 0:
            return (np.nan, np.nan, np.nan, np.nan, np.nan, np.nan, np.nan)
        mask = np.all(np.isfinite(arr), axis=1)
        arr = arr[mask]
        if arr.size == 0:
            return (np.nan, np.nan, np.nan, np.nan, np.nan, np.nan, np.nan)
        centroid = np.mean(arr, axis=0)
        radial = np.linalg.norm(arr[:, :2] - centroid[:2], axis=1)
        rms = float(np.sqrt(np.mean(radial * radial))) if radial.size else np.nan
        span_x = float(np.max(arr[:, 0]) - np.min(arr[:, 0])) if arr.shape[0] else np.nan
        span_y = float(np.max(arr[:, 1]) - np.min(arr[:, 1])) if arr.shape[0] else np.nan
        span_z = float(np.max(arr[:, 2]) - np.min(arr[:, 2])) if arr.shape[0] else np.nan
        return (float(centroid[0]), float(centroid[1]), float(centroid[2]), rms, span_x, span_y, span_z)

    def _source_illumination_terminal_label_for_record(self, record: dict[str, object]) -> str:
        last_surface = record.get("last_surface")
        last_name = str(record.get("last_name", "") or "")
        terminal = self._terminal_surface_label(last_surface, last_name)
        termination = str(record.get("termination", "") or "").strip()
        if terminal:
            return terminal
        return termination or "No recorded hit"

    @staticmethod
    def _source_illumination_format_terminal_counts(counts: dict[str, int], *, limit: int = 3) -> str:
        items = [
            (str(label), int(count))
            for label, count in (counts or {}).items()
            if str(label).strip() and int(count) > 0
        ]
        if not items:
            return "None"
        items.sort(key=lambda item: (-item[1], item[0]))
        shown = [f"{label} ({count})" for label, count in items[: max(1, int(limit))]]
        remainder = sum(count for _label, count in items[max(1, int(limit)):])
        if remainder > 0:
            shown.append(f"+{remainder} more")
        return "; ".join(shown)

    def _collect_source_illumination_records(self, target_surface_index: int | None = None) -> list[dict[str, object]]:
        ray_records = self._collect_ray_inspector_records()
        if not ray_records:
            return []
        if target_surface_index is None:
            target_surface_index = self._source_illumination_target_index()
        if target_surface_index is None or not (0 <= int(target_surface_index) < len(self.rows)):
            return []
        target_surface_index = int(target_surface_index)

        source_input: dict[tuple[str, int], float] = {}
        groups: dict[str, dict[str, object]] = {}

        def group_for(record: dict[str, object]) -> dict[str, object]:
            source_id = str(record.get("source_id", "") or "source:0")
            entry = groups.get(source_id)
            if entry is None:
                entry = {
                    "source_id": source_id,
                    "source_name": str(record.get("source_name", "") or source_id),
                    "source_model": str(record.get("source_model", "") or ""),
                    "target_surface": target_surface_index,
                    "target_name": self.rows[target_surface_index].name if 0 <= target_surface_index < len(self.rows) else "",
                    "launched_rays": 0,
                    "hit_rays": 0,
                    "hit_events": 0,
                    "input_power": 0.0,
                    "hit_power": 0.0,
                    "_launched_keys": set(),
                    "_hit_keys": set(),
                    "_points": [],
                    "_miss_candidates": {},
                }
                groups[source_id] = entry
            return entry

        for record in ray_records:
            source_id = str(record.get("source_id", "") or "source:0")
            source_ray_index = int(record.get("source_ray_index", record.get("ray_index", 0)) or 0)
            source_key = (source_id, source_ray_index)
            source_weight = self._safe_positive_float(record.get("source_weight"), 1.0)
            source_power = self._safe_positive_float(record.get("source_power"), 1.0)
            input_power = source_weight * source_power
            source_input[source_key] = max(float(source_input.get(source_key, 0.0)), input_power)
            entry = group_for(record)
            entry["_launched_keys"].add(source_key)  # type: ignore[union-attr]
            branch_power = self._safe_positive_float(record.get("branch_power"), np.nan)
            if not np.isfinite(branch_power):
                branch_power = self._safe_positive_float(record.get("transmission"), 1.0)
            effective_power = max(float(input_power * branch_power), 0.0)

            hits = [
                hit
                for hit in list(record.get("hits", []) or [])
                if str(hit.get("surface", "")).strip() not in {"", "-"}
                and int(hit.get("surface")) == target_surface_index
            ]
            if not hits:
                miss_candidates = entry["_miss_candidates"]  # type: ignore[assignment]
                candidates = miss_candidates.setdefault(source_key, [])
                candidates.append(
                    (
                        effective_power,
                        self._source_illumination_terminal_label_for_record(record),
                    )
                )
                continue
            entry["_hit_keys"].add(source_key)  # type: ignore[union-attr]
            entry["hit_events"] = int(entry["hit_events"]) + len(hits)
            entry["hit_power"] = float(entry["hit_power"]) + effective_power
            points = entry["_points"]  # type: ignore[assignment]
            for hit in hits:
                points.append(
                    (
                        float(hit.get("x", np.nan)),
                        float(hit.get("y", np.nan)),
                        float(hit.get("z", np.nan)),
                    )
                )

        for entry in groups.values():
            launched_keys = set(entry.pop("_launched_keys", set()) or set())
            hit_keys = set(entry.pop("_hit_keys", set()) or set())
            points = list(entry.pop("_points", []) or [])
            miss_candidates = dict(entry.pop("_miss_candidates", {}) or {})
            missed_keys = launched_keys - hit_keys
            terminal_counts: dict[str, int] = {}
            missed_power = 0.0
            for source_key in missed_keys:
                candidates = list(miss_candidates.get(source_key, []) or [])
                terminal = "No recorded hit"
                if candidates:
                    candidates.sort(key=lambda item: float(item[0] if np.isfinite(float(item[0])) else 0.0), reverse=True)
                    terminal = str(candidates[0][1] or terminal)
                terminal_counts[terminal] = int(terminal_counts.get(terminal, 0)) + 1
                missed_power += float(source_input.get(source_key, 0.0))
            input_power = float(sum(source_input.get(key, 0.0) for key in launched_keys))
            hit_power = float(entry.get("hit_power", 0.0))
            cx, cy, cz, rms, span_x, span_y, span_z = self._finite_centroid_and_rms(points)
            entry["launched_rays"] = len(launched_keys)
            entry["hit_rays"] = len(hit_keys)
            entry["missed_rays"] = max(len(launched_keys) - len(hit_keys), 0)
            entry["missed_power"] = missed_power
            entry["input_power"] = input_power
            entry["hit_power"] = hit_power
            entry["throughput"] = hit_power / input_power if input_power > 0.0 else np.nan
            entry["hit_fraction"] = len(hit_keys) / len(launched_keys) if launched_keys else np.nan
            entry["vignetted_fraction"] = 1.0 - float(entry["hit_fraction"]) if np.isfinite(float(entry["hit_fraction"])) else np.nan
            entry["missed_terminal_counts"] = dict(sorted(terminal_counts.items(), key=lambda item: (-item[1], item[0])))
            entry["missed_terminal_breakdown"] = self._source_illumination_format_terminal_counts(terminal_counts)
            entry["dominant_loss"] = self._source_illumination_format_terminal_counts(terminal_counts, limit=1)
            entry["centroid_x"] = cx
            entry["centroid_y"] = cy
            entry["centroid_z"] = cz
            entry["rms_radius"] = rms
            entry["span_x"] = span_x
            entry["span_y"] = span_y
            entry["span_z"] = span_z

        records = list(groups.values())
        records.sort(key=lambda item: str(item.get("source_id", "")))
        return records

    def open_source_illumination_report(self) -> None:
        window = self._source_illumination_window
        if window is not None and window.winfo_exists():
            self._refresh_source_illumination_report()
            window.deiconify()
            window.lift()
            window.focus_force()
            return

        window = tk.Toplevel(self)
        window.title("Source Illumination Report")
        window.geometry("1160x600")
        window.protocol("WM_DELETE_WINDOW", self._close_source_illumination_report)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(2, weight=1)

        toolbar = ttk.Frame(window, padding=(8, 8, 8, 4))
        toolbar.grid(row=0, column=0, sticky="ew")
        ttk.Label(toolbar, text="Target").pack(side="left")
        default_target = "Auto"
        self._source_illumination_target_var = tk.StringVar(master=window, value=default_target)
        self._source_illumination_target_menu = ttk.Combobox(
            toolbar,
            textvariable=self._source_illumination_target_var,
            values=self._source_illumination_target_choices(),
            state="readonly",
            width=28,
        )
        self._source_illumination_target_menu.pack(side="left", padx=(6, 10))
        self._source_illumination_target_menu.bind("<<ComboboxSelected>>", lambda _event: self._refresh_source_illumination_report(), add="+")
        ttk.Button(toolbar, text="Refresh", command=self._refresh_source_illumination_report).pack(side="left")
        ttk.Button(toolbar, text="Copy", command=self.copy_source_illumination_report_to_clipboard).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Export CSV", command=self.export_source_illumination_csv).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Close", command=self._close_source_illumination_report).pack(side="left", padx=(6, 0))

        self._source_illumination_summary_var = tk.StringVar(master=window, value="No trace data. Click Update.")
        ttk.Label(window, textvariable=self._source_illumination_summary_var, padding=(8, 0, 8, 4)).grid(row=1, column=0, sticky="ew")

        columns = (
            "source",
            "model",
            "launched",
            "hit",
            "missed",
            "loss",
            "events",
            "hit_fraction",
            "throughput",
            "power",
            "centroid",
            "rms",
            "span",
        )
        table = ttk.Treeview(window, columns=columns, show="headings", selectmode="browse")
        headings = {
            "source": "Source",
            "model": "Model",
            "launched": "Launched",
            "hit": "Hit Rays",
            "missed": "Missed",
            "loss": "Dominant Loss",
            "events": "Hit Events",
            "hit_fraction": "Hit %",
            "throughput": "Power %",
            "power": "Hit Power",
            "centroid": "Centroid XYZ",
            "rms": "RMS r",
            "span": "Span XYZ",
        }
        widths = {
            "source": 180,
            "model": 150,
            "launched": 75,
            "hit": 75,
            "missed": 75,
            "loss": 165,
            "events": 80,
            "hit_fraction": 80,
            "throughput": 80,
            "power": 90,
            "centroid": 170,
            "rms": 75,
            "span": 170,
        }
        for column in columns:
            table.heading(column, text=headings[column])
            table.column(column, width=widths[column], anchor=("e" if column not in {"source", "model", "loss", "centroid", "span"} else "w"))
        table.grid(row=2, column=0, sticky="nsew", padx=8, pady=(0, 8))
        yscroll = ttk.Scrollbar(window, orient="vertical", command=table.yview)
        yscroll.grid(row=2, column=1, sticky="ns", pady=(0, 8))
        table.configure(yscrollcommand=yscroll.set)
        table.bind("<<TreeviewSelect>>", lambda _event: self._refresh_source_illumination_detail(), add="+")

        detail_frame = ttk.LabelFrame(window, text="Selected source details", padding=(8, 6, 8, 8))
        detail_frame.grid(row=3, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 8))
        detail_frame.columnconfigure(0, weight=1)
        detail_text = tk.Text(detail_frame, height=6, wrap="word", borderwidth=0, relief="flat")
        detail_text.grid(row=0, column=0, sticky="ew")
        detail_text.configure(state="disabled")
        self._bind_text_copy_shortcuts(detail_text)
        self._bind_text_context_menu(detail_text)

        self._source_illumination_window = window
        self._source_illumination_table = table
        self._source_illumination_detail_text = detail_text
        self._refresh_source_illumination_report()

    def _close_source_illumination_report(self) -> None:
        window = self._source_illumination_window
        self._source_illumination_window = None
        self._source_illumination_summary_var = None
        self._source_illumination_target_var = None
        self._source_illumination_target_menu = None
        self._source_illumination_table = None
        self._source_illumination_detail_text = None
        self._source_illumination_records = []
        if window is not None:
            try:
                window.destroy()
            except tk.TclError:
                pass

    def _set_source_illumination_detail_text(self, text: str) -> None:
        widget = self._source_illumination_detail_text
        if widget is None:
            return
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("1.0", str(text or ""))
        widget.configure(state="disabled")

    def _source_illumination_record_detail_text(self, record: dict[str, object]) -> str:
        target_surface = record.get("target_surface", "")
        target_name = str(record.get("target_name", "") or "")
        target = f"S{target_surface}: {target_name}" if str(target_surface).strip() != "" else target_name or "None"
        input_power = float(record.get("input_power", 0.0) or 0.0)
        hit_power = float(record.get("hit_power", 0.0) or 0.0)
        missed_power = float(record.get("missed_power", 0.0) or 0.0)
        return "\n".join(
            [
                f"Source: {record.get('source_id', '')} ({record.get('source_name', '')}) | {record.get('source_model', '')}",
                f"Target: {target}",
                (
                    f"Rays: launched={int(record.get('launched_rays', 0) or 0)}, "
                    f"hit={int(record.get('hit_rays', 0) or 0)} "
                    f"({self._format_percent_value(record.get('hit_fraction'))}), "
                    f"missed={int(record.get('missed_rays', 0) or 0)} "
                    f"({self._format_percent_value(record.get('vignetted_fraction'))})"
                ),
                (
                    f"Power: input={input_power:.6g}, hit={hit_power:.6g}, "
                    f"missed={missed_power:.6g}, throughput={self._format_percent_value(record.get('throughput'))}"
                ),
                (
                    f"Loss: dominant={record.get('dominant_loss', 'None')}; "
                    f"all missed terminals={record.get('missed_terminal_breakdown', 'None')}"
                ),
                (
                    "Footprint: "
                    f"centroid=({float(record.get('centroid_x', np.nan)):.6g}, "
                    f"{float(record.get('centroid_y', np.nan)):.6g}, "
                    f"{float(record.get('centroid_z', np.nan)):.6g}) mm; "
                    f"RMS r={float(record.get('rms_radius', np.nan)):.6g} mm; "
                    f"span=({float(record.get('span_x', np.nan)):.6g}, "
                    f"{float(record.get('span_y', np.nan)):.6g}, "
                    f"{float(record.get('span_z', np.nan)):.6g}) mm"
                ),
            ]
        )

    def _refresh_source_illumination_detail(self) -> None:
        table = self._source_illumination_table
        if table is None:
            return
        selection = table.selection()
        if not selection:
            self._set_source_illumination_detail_text("Select a source row to inspect loss and footprint diagnostics.")
            return
        try:
            index = int(str(selection[0]).rsplit("_", 1)[-1])
        except Exception:
            index = -1
        if not (0 <= index < len(self._source_illumination_records)):
            self._set_source_illumination_detail_text("Selected source record is no longer available. Click Refresh.")
            return
        self._set_source_illumination_detail_text(
            self._source_illumination_record_detail_text(self._source_illumination_records[index])
        )

    def _refresh_source_illumination_report_if_open(self) -> None:
        window = self._source_illumination_window
        if window is None:
            return
        if not window.winfo_exists():
            self._close_source_illumination_report()
            return
        self._refresh_source_illumination_report()

    def _refresh_source_illumination_report(self) -> None:
        table = self._source_illumination_table
        if table is None:
            return
        if self._source_illumination_target_menu is not None:
            self._source_illumination_target_menu["values"] = self._source_illumination_target_choices()
        target_index = self._source_illumination_target_index()
        records = self._collect_source_illumination_records(target_index)
        self._source_illumination_records = records
        table.delete(*table.get_children())
        target_label = "None" if target_index is None else f"S{target_index}: {self.rows[target_index].name}"
        if self._source_illumination_summary_var is not None:
            if records:
                total_input = float(sum(float(record.get("input_power", 0.0) or 0.0) for record in records))
                total_hit = float(sum(float(record.get("hit_power", 0.0) or 0.0) for record in records))
                total_launched = int(sum(int(record.get("launched_rays", 0) or 0) for record in records))
                total_hit_rays = int(sum(int(record.get("hit_rays", 0) or 0) for record in records))
                self._source_illumination_summary_var.set(
                    f"Target {target_label}: {total_hit_rays}/{total_launched} source rays hit | "
                    f"power throughput={self._format_percent_value(total_hit / total_input if total_input > 0 else np.nan)}"
                )
            else:
                self._source_illumination_summary_var.set(f"Target {target_label}: no source illumination records. Click Update first.")
        for index, record in enumerate(records):
            centroid = (
                f"{float(record.get('centroid_x', np.nan)):.5g}, "
                f"{float(record.get('centroid_y', np.nan)):.5g}, "
                f"{float(record.get('centroid_z', np.nan)):.5g}"
            )
            span = (
                f"{float(record.get('span_x', np.nan)):.5g}, "
                f"{float(record.get('span_y', np.nan)):.5g}, "
                f"{float(record.get('span_z', np.nan)):.5g}"
            )
            table.insert(
                "",
                "end",
                iid=f"source_illum_{index}",
                values=(
                    f"{record.get('source_id', '')}: {record.get('source_name', '')}",
                    record.get("source_model", ""),
                    int(record.get("launched_rays", 0) or 0),
                    int(record.get("hit_rays", 0) or 0),
                    int(record.get("missed_rays", 0) or 0),
                    record.get("dominant_loss", "None"),
                    int(record.get("hit_events", 0) or 0),
                    self._format_percent_value(record.get("hit_fraction")),
                    self._format_percent_value(record.get("throughput")),
                    f"{float(record.get('hit_power', 0.0) or 0.0):.6g}",
                    centroid,
                    f"{float(record.get('rms_radius', np.nan)):.6g}",
                    span,
                ),
            )
        if records:
            first_iid = "source_illum_0"
            table.selection_set(first_iid)
            table.focus(first_iid)
            self._refresh_source_illumination_detail()
        else:
            self._set_source_illumination_detail_text(
                "No source illumination records. Click Update, then choose a target surface or leave Target as Auto."
            )

    def _source_illumination_report_text(self) -> str:
        target_index = self._source_illumination_target_index()
        records = self._collect_source_illumination_records(target_index)
        if target_index is None:
            target_label = "None"
        else:
            target_label = f"S{target_index}: {self.rows[target_index].name}"
        if not records:
            return f"# KrakenOS Source Illumination Report\n\nTarget: {target_label}\n\nNo source illumination records. Click Update first.\n"
        total_input = float(sum(float(record.get("input_power", 0.0) or 0.0) for record in records))
        total_hit = float(sum(float(record.get("hit_power", 0.0) or 0.0) for record in records))
        lines = [
            "# KrakenOS Source Illumination Report",
            "",
            f"Target: {target_label}",
            f"Total source power throughput: {self._format_percent_value(total_hit / total_input if total_input > 0.0 else np.nan)}",
            "",
        ]
        for record in records:
            lines.append(
                "- {source_id} ({source_name}) | launched={launched} | hit={hit} | missed={missed} | "
                "hit_fraction={hit_fraction} | power={power:.6g} | throughput={throughput} | "
                "dominant_loss={dominant_loss} | missed_terminals={missed_terminals} | "
                "centroid=({cx:.6g}, {cy:.6g}, {cz:.6g}) mm | rms={rms:.6g} mm".format(
                    source_id=record.get("source_id", ""),
                    source_name=record.get("source_name", ""),
                    launched=int(record.get("launched_rays", 0) or 0),
                    hit=int(record.get("hit_rays", 0) or 0),
                    missed=int(record.get("missed_rays", 0) or 0),
                    hit_fraction=self._format_percent_value(record.get("hit_fraction")),
                    power=float(record.get("hit_power", 0.0) or 0.0),
                    throughput=self._format_percent_value(record.get("throughput")),
                    dominant_loss=record.get("dominant_loss", "None"),
                    missed_terminals=record.get("missed_terminal_breakdown", "None"),
                    cx=float(record.get("centroid_x", np.nan)),
                    cy=float(record.get("centroid_y", np.nan)),
                    cz=float(record.get("centroid_z", np.nan)),
                    rms=float(record.get("rms_radius", np.nan)),
                )
            )
        return "\n".join(lines) + "\n"

    def copy_source_illumination_report_to_clipboard(self) -> None:
        try:
            text = self._source_illumination_report_text()
            ok, backend = self._copy_text_to_clipboard(text)
            self.append_debug(text)
            if ok:
                self.status_var.set(f"Source illumination report copied to clipboard ({backend}).")
            else:
                self.status_var.set("Source illumination report written to Debug; clipboard unavailable.")
        except Exception as exc:
            self.append_debug(f"Source illumination report failed: {exc}")

    def export_source_illumination_csv(self) -> None:
        target_index = self._source_illumination_target_index()
        records = self._collect_source_illumination_records(target_index)
        if not records:
            messagebox.showinfo("Export Source Illumination", "No source illumination records. Click Update first.", parent=self)
            return
        path = filedialog.asksaveasfilename(
            title="Export Source Illumination CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        columns = (
            "source_id",
            "source_name",
            "source_model",
            "target_surface",
            "target_name",
            "launched_rays",
            "hit_rays",
            "missed_rays",
            "hit_events",
            "input_power",
            "hit_power",
            "missed_power",
            "throughput",
            "hit_fraction",
            "vignetted_fraction",
            "dominant_loss",
            "missed_terminal_breakdown",
            "centroid_x",
            "centroid_y",
            "centroid_z",
            "rms_radius",
            "span_x",
            "span_y",
            "span_z",
        )
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=columns)
            writer.writeheader()
            for record in records:
                writer.writerow({column: record.get(column, "") for column in columns})
        self.status_var.set(f"Source illumination CSV exported: {Path(path).name}")

    def open_branch_throughput_report(self) -> None:
        window = self._branch_throughput_window
        if window is not None and window.winfo_exists():
            self._refresh_branch_throughput_report()
            window.deiconify()
            window.lift()
            window.focus_force()
            return

        window = tk.Toplevel(self)
        window.withdraw()
        window.title("Path Throughput Report")
        window.geometry("1120x560")
        window.minsize(820, 360)
        window.transient(self)
        window.protocol("WM_DELETE_WINDOW", self._close_branch_throughput_report)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(2, weight=1)

        toolbar = ttk.Frame(window, padding=(8, 8, 8, 0))
        toolbar.grid(row=0, column=0, sticky="ew")
        ttk.Button(toolbar, text="Refresh", command=self._refresh_branch_throughput_report).pack(side="left")
        ttk.Button(toolbar, text="Copy", command=self.copy_branch_throughput_report_to_clipboard).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Export CSV", command=self.export_branch_throughput_csv).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Close", command=self._close_branch_throughput_report).pack(side="left", padx=(6, 0))
        ttk.Label(toolbar, text="Filter").pack(side="left", padx=(18, 4))
        self._branch_throughput_filter_var = tk.StringVar(master=window, value=ANALYSIS_PATH_FILTER_DEFAULT)
        self._branch_throughput_filter_menu = ttk.Combobox(
            toolbar,
            textvariable=self._branch_throughput_filter_var,
            state="readonly",
            width=36,
            values=[ANALYSIS_PATH_FILTER_DEFAULT],
        )
        self._branch_throughput_filter_menu.pack(side="left")
        self._branch_throughput_filter_menu.bind("<<ComboboxSelected>>", lambda _event: self._refresh_branch_throughput_report(), add="+")

        self._branch_throughput_summary_var = tk.StringVar(master=window, value="No trace data. Click Update.")
        ttk.Label(
            window,
            textvariable=self._branch_throughput_summary_var,
            padding=(8, 6, 8, 0),
            anchor="w",
            justify="left",
        ).grid(row=1, column=0, sticky="ew")

        table_frame = ttk.Frame(window, padding=8)
        table_frame.grid(row=2, column=0, sticky="nsew")
        table_frame.columnconfigure(0, weight=1)
        table_frame.rowconfigure(0, weight=1)
        columns = ("output", "code", "terminal", "rays", "sources", "detector", "power", "throughput", "op", "distance", "path")
        table = ttk.Treeview(table_frame, columns=columns, show="headings", selectmode="browse")
        headings = {
            "output": "Output / path",
            "code": "Code",
            "terminal": "Terminal",
            "rays": "Rays",
            "sources": "Sources",
            "detector": "Detector hits",
            "power": "Power sum",
            "throughput": "Throughput",
            "op": "Mean OP [mm]",
            "distance": "Mean dist [mm]",
            "path": "Trace path",
        }
        for column, heading in headings.items():
            table.heading(column, text=heading)
        for column, width, anchor in (
            ("output", 150, "w"),
            ("code", 70, "center"),
            ("terminal", 220, "w"),
            ("rays", 70, "center"),
            ("sources", 70, "center"),
            ("detector", 90, "center"),
            ("power", 95, "e"),
            ("throughput", 90, "e"),
            ("op", 95, "e"),
            ("distance", 105, "e"),
            ("path", 260, "w"),
        ):
            table.column(column, width=width, anchor=anchor, stretch=column in {"terminal", "path"})
        table.grid(row=0, column=0, sticky="nsew")
        y_scroll = ttk.Scrollbar(table_frame, orient="vertical", command=table.yview)
        y_scroll.grid(row=0, column=1, sticky="ns")
        x_scroll = ttk.Scrollbar(table_frame, orient="horizontal", command=table.xview)
        x_scroll.grid(row=1, column=0, sticky="ew")
        table.configure(yscrollcommand=y_scroll.set, xscrollcommand=x_scroll.set)

        self._branch_throughput_window = window
        self._branch_throughput_table = table
        self._show_centered_dialog(window)
        self._refresh_branch_throughput_report()

    def _close_branch_throughput_report(self) -> None:
        window = self._branch_throughput_window
        self._branch_throughput_window = None
        self._branch_throughput_summary_var = None
        self._branch_throughput_filter_var = None
        self._branch_throughput_filter_menu = None
        self._branch_throughput_table = None
        self._branch_throughput_records = []
        if window is not None and window.winfo_exists():
            window.destroy()

    def _refresh_branch_throughput_report_if_open(self) -> None:
        window = self._branch_throughput_window
        if window is None:
            return
        if not window.winfo_exists():
            self._close_branch_throughput_report()
            return
        self._refresh_branch_throughput_report()

    @staticmethod
    def _branch_throughput_filter_choices(records: list[dict[str, object]]) -> list[str]:
        choices = [ANALYSIS_PATH_FILTER_DEFAULT]
        for prefix, key in (
            ("Output", "output"),
            ("Code", "branch_code"),
            ("Terminal", "terminal"),
        ):
            values = sorted({str(record.get(key, "") or "").strip() for record in records})
            for value in values:
                if value:
                    choices.append(f"{prefix}: {value}")
        return choices

    @staticmethod
    def _branch_throughput_filter_matches(record: dict[str, object], filter_text: str) -> bool:
        text = _normalize_path_filter_label(filter_text)
        if _is_all_path_filter(text):
            return True
        prefix, separator, value = text.partition(":")
        if not separator:
            return True
        key = {
            "Output": "output",
            "Code": "branch_code",
            "Terminal": "terminal",
        }.get(prefix.strip())
        if not key:
            return True
        return str(record.get(key, "") or "").strip() == value.strip()

    def _filtered_branch_throughput_records(self, records: list[dict[str, object]]) -> list[dict[str, object]]:
        filter_text = (
            self._branch_throughput_filter_var.get()
            if self._branch_throughput_filter_var is not None
            else ANALYSIS_PATH_FILTER_DEFAULT
        )
        return [record for record in records if self._branch_throughput_filter_matches(record, filter_text)]

    def _current_analysis_branch_filter(self) -> str:
        value = ANALYSIS_PATH_FILTER_DEFAULT
        var = getattr(self, "analysis_branch_filter_var", None)
        if var is not None:
            try:
                value = _normalize_path_filter_label(var.get())
            except Exception:
                value = ANALYSIS_PATH_FILTER_DEFAULT
        return _normalize_path_filter_label(value)

    def _current_coherent_sum_mode(self) -> str:
        value = COHERENT_SUM_MODE_DEFAULT
        var = getattr(self, "coherent_sum_mode_var", None)
        if var is not None:
            try:
                value = _normalize_coherent_sum_mode(var.get())
            except Exception:
                value = COHERENT_SUM_MODE_DEFAULT
        return _normalize_coherent_sum_mode(value)

    @staticmethod
    def _normalize_ray_display_mode(value) -> str:
        text = str(value or RAY_DISPLAY_DEFAULT).strip()
        aliases = {
            "all": RAY_DISPLAY_ALL,
            "all traced rays": RAY_DISPLAY_ALL,
            "all rays": RAY_DISPLAY_ALL,
            "detector": RAY_DISPLAY_DETECTOR,
            "detector hits": RAY_DISPLAY_DETECTOR,
            "image": RAY_DISPLAY_DETECTOR,
            "image hits": RAY_DISPLAY_DETECTOR,
            "split": RAY_DISPLAY_SPLITTER,
            "splitter": RAY_DISPLAY_SPLITTER,
            "beam splitter": RAY_DISPLAY_SPLITTER,
            "beam-splitter": RAY_DISPLAY_SPLITTER,
            "beam-splitter paths": RAY_DISPLAY_SPLITTER,
            "hide direct": RAY_DISPLAY_SPLITTER,
            "hide direct source rays": RAY_DISPLAY_SPLITTER,
            "useful": RAY_DISPLAY_SPLITTER,
            "useful paths": RAY_DISPLAY_SPLITTER,
        }
        return aliases.get(text.lower(), text if text in RAY_DISPLAY_VALUES else RAY_DISPLAY_DEFAULT)

    def _current_ray_display_mode(self) -> str:
        var = getattr(self, "ray_display_mode_var", None)
        if var is None:
            return RAY_DISPLAY_DEFAULT
        try:
            return self._normalize_ray_display_mode(var.get())
        except Exception:
            return RAY_DISPLAY_DEFAULT

    def _refresh_analysis_branch_choices(self) -> None:
        menu = getattr(self, "analysis_branch_filter_menu", None)
        var = getattr(self, "analysis_branch_filter_var", None)
        if menu is None or var is None:
            return
        records = self._collect_branch_throughput_records()
        choices = self._branch_throughput_filter_choices(records)
        current = self._current_analysis_branch_filter()
        if current not in choices and not records:
            choices.append(current)
        menu["values"] = choices
        if current not in choices:
            var.set(ANALYSIS_PATH_FILTER_DEFAULT)

    def _ray_record_branch_filter_matches(self, record: dict[str, object], filter_text: str) -> bool:
        branch_path = str(record.get("branch_path", "") or "").strip()
        last_surface = record.get("last_surface")
        terminal = self._terminal_surface_label(last_surface, str(record.get("last_name", "") or ""))
        pseudo_record = {
            "output": self._branch_output_label(branch_path),
            "branch_code": "".join(self._branch_path_selector_sequence(branch_path)) or "primary",
            "terminal": terminal,
        }
        return self._branch_throughput_filter_matches(pseudo_record, filter_text)

    def _record_terminal_hit_local_xy(self, system, record: dict[str, object]) -> tuple[float, float, str]:
        hits = list(record.get("hits", []) or [])
        if not hits:
            return (np.nan, np.nan, "world")
        hit = hits[-1]
        try:
            surface_index = int(record.get("last_surface"))
        except Exception:
            surface_index = -1
        return self._hit_local_xy(system, surface_index, hit)

    def _hit_local_xy(self, system, surface_index: int, hit: dict[str, object]) -> tuple[float, float, str]:
        try:
            world = np.asarray(
                [
                    float(hit.get("x", np.nan)),
                    float(hit.get("y", np.nan)),
                    float(hit.get("z", np.nan)),
                    1.0,
                ],
                dtype=float,
            )
        except Exception:
            return (np.nan, np.nan, "world")
        if not np.all(np.isfinite(world[:3])):
            return (np.nan, np.nan, "world")
        transforms = self._system_transform_list(system)
        if transforms is not None and 0 <= surface_index < len(transforms):
            try:
                transform = np.asarray(transforms[surface_index], dtype=float)
                local = np.linalg.inv(transform) @ world
                if np.all(np.isfinite(local[:2])):
                    return (float(local[0]), float(local[1]), "local")
            except Exception:
                pass
        return (float(world[0]), float(world[1]), "world")

    def _source_illumination_hit_samples(self, system, target_surface_index: int | None = None) -> dict[str, object]:
        if target_surface_index is None:
            target_surface_index = self._source_illumination_target_index()
        if target_surface_index is None or not (0 <= int(target_surface_index) < len(self.rows)):
            return {
                "x": np.asarray([], dtype=float),
                "y": np.asarray([], dtype=float),
                "weights": np.asarray([], dtype=float),
                "source_ids": [],
                "source_names": [],
                "coord": "local",
                "target_surface": None,
                "target_name": "",
                "launched_rays": 0,
                "hit_rays": 0,
                "missed_rays": 0,
                "input_power": 0.0,
                "hit_power": 0.0,
                "source_count": 0,
            }
        target_surface_index = int(target_surface_index)
        x_values: list[float] = []
        y_values: list[float] = []
        weights: list[float] = []
        source_ids: list[str] = []
        source_names: list[str] = []
        coord_modes: set[str] = set()
        launched_keys: set[tuple[str, int]] = set()
        hit_keys: set[tuple[str, int]] = set()
        source_input: dict[tuple[str, int], float] = {}

        for record in self._collect_ray_inspector_records():
            source_id = str(record.get("source_id", "") or "source:0")
            source_name = str(record.get("source_name", "") or source_id)
            source_ray_index = int(record.get("source_ray_index", record.get("ray_index", 0)) or 0)
            source_key = (source_id, source_ray_index)
            source_weight = self._safe_positive_float(record.get("source_weight"), 1.0)
            source_power = self._safe_positive_float(record.get("source_power"), 1.0)
            input_power = source_weight * source_power
            source_input[source_key] = max(float(source_input.get(source_key, 0.0)), input_power)
            launched_keys.add(source_key)
            hits = [
                hit
                for hit in list(record.get("hits", []) or [])
                if str(hit.get("surface", "")).strip() not in {"", "-"}
                and int(hit.get("surface")) == target_surface_index
            ]
            if not hits:
                continue
            branch_power = self._safe_positive_float(record.get("branch_power"), np.nan)
            if not np.isfinite(branch_power):
                branch_power = self._safe_positive_float(record.get("transmission"), 1.0)
            effective_power = max(float(input_power * branch_power), 0.0)
            hit_keys.add(source_key)
            for hit in hits:
                x_value, y_value, coord_mode = self._hit_local_xy(system, target_surface_index, hit)
                if not np.isfinite(x_value) or not np.isfinite(y_value):
                    continue
                x_values.append(float(x_value))
                y_values.append(float(y_value))
                weights.append(effective_power)
                source_ids.append(source_id)
                source_names.append(source_name)
                coord_modes.add(coord_mode)

        input_total = float(sum(source_input.get(key, 0.0) for key in launched_keys))
        hit_total = float(sum(weights))
        coord = "local" if coord_modes == {"local"} or not coord_modes else "world"
        diagnostic_records = self._collect_source_illumination_records(target_surface_index)
        loss_parts = [
            f"{record.get('source_id', '')}: {record.get('dominant_loss', 'None')}"
            for record in diagnostic_records
            if int(record.get("missed_rays", 0) or 0) > 0
        ]
        return {
            "x": np.asarray(x_values, dtype=float),
            "y": np.asarray(y_values, dtype=float),
            "weights": np.asarray(weights, dtype=float),
            "source_ids": source_ids,
            "source_names": source_names,
            "coord": coord,
            "target_surface": target_surface_index,
            "target_name": self.rows[target_surface_index].name,
            "launched_rays": len(launched_keys),
            "hit_rays": len(hit_keys),
            "missed_rays": max(len(launched_keys) - len(hit_keys), 0),
            "input_power": input_total,
            "hit_power": hit_total,
            "source_count": len({source_id for source_id in source_ids}),
            "loss_summary": "; ".join(loss_parts) if loss_parts else "None",
        }

    def _source_illumination_map_extent(
        self,
        samples: dict[str, object],
        x_values: np.ndarray,
        y_values: np.ndarray,
    ) -> tuple[float, float, float, float]:
        target_index = samples.get("target_surface")
        if samples.get("coord") == "local" and self._surface_index_is_detector(target_index):
            settings = self._detector_settings_for_surface(target_index)
            active_width = float(settings.get("active_width_mm", 0.0) or 0.0)
            active_height = float(settings.get("active_height_mm", 0.0) or 0.0)
            try:
                diameter = self._safe_positive_float(getattr(self.rows[int(target_index)], "diameter", 0.0), 0.0)
            except Exception:
                diameter = 0.0
            if active_width <= 0.0 and diameter > 0.0:
                active_width = diameter
            if active_height <= 0.0 and diameter > 0.0:
                active_height = diameter
            if active_width > 0.0 and active_height > 0.0:
                return (-0.5 * active_width, 0.5 * active_width, -0.5 * active_height, 0.5 * active_height)
        x_min = float(np.min(x_values))
        x_max = float(np.max(x_values))
        y_min = float(np.min(y_values))
        y_max = float(np.max(y_values))
        x_span = max(x_max - x_min, 1e-6)
        y_span = max(y_max - y_min, 1e-6)
        pad = max(x_span, y_span, 1e-3) * 0.2
        return (x_min - pad, x_max + pad, y_min - pad, y_max + pad)

    def _plot_source_illumination_map_analysis(self, analysis_ax, system) -> None:
        target_index = self._source_illumination_target_index()
        samples = self._source_illumination_hit_samples(system, target_index)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        y_values = np.asarray(samples.get("y", np.asarray([])), dtype=float)
        weights = np.asarray(samples.get("weights", np.asarray([])), dtype=float)
        if x_values.size == 0 or y_values.size == 0:
            raise RuntimeError("No source illumination hits on the selected target. Click Update and select Object, Detector, or Image.")
        if weights.size != x_values.size or float(np.sum(weights)) <= 0.0:
            weights = np.ones_like(x_values, dtype=float)
        x_min, x_max, y_min, y_max = self._source_illumination_map_extent(samples, x_values, y_values)
        bins = min(max(24, int(np.sqrt(max(x_values.size, 1)) * 3)), 128)
        hist, x_edges, y_edges = np.histogram2d(
            x_values,
            y_values,
            bins=bins,
            range=[[x_min, x_max], [y_min, y_max]],
            weights=weights,
        )
        if not np.any(hist > 0.0):
            raise RuntimeError("Source illumination map has no finite bins.")
        density = hist.T / max(float(np.max(hist)), 1e-12)
        extent = [float(x_edges[0]), float(x_edges[-1]), float(y_edges[0]), float(y_edges[-1])]
        image = analysis_ax.imshow(density, origin="lower", extent=extent, cmap="magma", aspect="auto")
        source_ids = list(samples.get("source_ids", []) or [])
        source_names = list(samples.get("source_names", []) or [])
        colors = self._field_colors(max(1, len(set(source_ids))))
        color_by_source = {source_id: colors[index % len(colors)] for index, source_id in enumerate(sorted(set(source_ids)))}
        for source_id in sorted(set(source_ids)):
            mask = np.asarray([item == source_id for item in source_ids], dtype=bool)
            if not np.any(mask):
                continue
            source_weights = np.maximum(weights[mask], 0.0)
            if float(np.sum(source_weights)) > 0.0:
                cx = float(np.average(x_values[mask], weights=source_weights))
                cy = float(np.average(y_values[mask], weights=source_weights))
            else:
                cx = float(np.mean(x_values[mask]))
                cy = float(np.mean(y_values[mask]))
            try:
                first_name = source_names[next(index for index, item in enumerate(source_ids) if item == source_id)]
            except Exception:
                first_name = source_id
            analysis_ax.scatter(
                [cx],
                [cy],
                s=42,
                color=color_by_source[source_id],
                edgecolors="white",
                linewidths=0.8,
                label=str(first_name or source_id),
                zorder=5,
            )
        if len(set(source_ids)) > 1:
            analysis_ax.legend(loc="upper right", fontsize=7, title="Source centroid")
        coordinate_label = "target local" if samples.get("coord") == "local" else "world"
        target_label = (
            f"S{int(samples['target_surface'])}: {samples.get('target_name', '')}"
            if samples.get("target_surface") is not None
            else "target"
        )
        input_power = float(samples.get("input_power", 0.0) or 0.0)
        hit_power = float(samples.get("hit_power", 0.0) or 0.0)
        throughput = hit_power / input_power if input_power > 0.0 else np.nan
        hit_rays = int(samples.get("hit_rays", 0) or 0)
        launched_rays = int(samples.get("launched_rays", 0) or 0)
        missed_rays = int(samples.get("missed_rays", 0) or 0)
        loss_summary = str(samples.get("loss_summary", "") or "None")
        analysis_ax.set_title(f"Source Illumination Map | {target_label}")
        analysis_ax.set_xlabel(f"X [{coordinate_label}, mm]")
        analysis_ax.set_ylabel(f"Y [{coordinate_label}, mm]")
        analysis_ax.set_box_aspect(0.72)
        analysis_ax.grid(False)
        self.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04, label="Relative hit power density")
        analysis_ax.text(
            0.02,
            0.98,
            (
                f"sources={int(samples.get('source_count', 0) or 0)} | events={x_values.size}\n"
                f"rays hit={hit_rays}/{launched_rays}, missed={missed_rays}\n"
                f"power throughput={self._format_percent_value(throughput)}"
                + (f"\nloss: {loss_summary}" if missed_rays > 0 and loss_summary != "None" else "")
            ),
            transform=analysis_ax.transAxes,
            ha="left",
            va="top",
            fontsize=7.5,
            bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.82, "pad": 3},
        )
        self.append_debug(
            f"Source illumination map ok: target={target_label}, events={x_values.size}, "
            f"sources={samples.get('source_count')}, throughput={throughput:.6g}"
        )

    def _branch_detector_spot_samples(self, system, filter_text: str, *, require_detector: bool = False) -> dict[str, object]:
        ray_records = [
            record
            for record in self._collect_ray_inspector_records()
            if self._ray_record_branch_filter_matches(record, filter_text)
        ]
        if not ray_records:
            return {
                "x": np.asarray([]),
                "y": np.asarray([]),
                "weights": np.asarray([]),
                "terminals": [],
                "terminal_surfaces": [],
                "coord": "local",
                "used_detector_only": False,
                "matched_ray_count": 0,
            }

        detector_records = [
            record for record in ray_records if self._surface_index_is_detector(record.get("last_surface"))
        ]
        if require_detector and not detector_records:
            return {
                "x": np.asarray([]),
                "y": np.asarray([]),
                "weights": np.asarray([]),
                "terminals": [
                    self._terminal_surface_label(record.get("last_surface"), str(record.get("last_name", "") or ""))
                    for record in ray_records
                ],
                "terminal_surfaces": [record.get("last_surface") for record in ray_records],
                "coord": "local",
                "used_detector_only": False,
                "matched_ray_count": len(ray_records),
            }
        samples = detector_records if detector_records else ray_records
        x_values: list[float] = []
        y_values: list[float] = []
        weights: list[float] = []
        terminals: list[str] = []
        terminal_surfaces: list[object] = []
        coord_modes: set[str] = set()
        for record in samples:
            x_value, y_value, coord_mode = self._record_terminal_hit_local_xy(system, record)
            if not np.isfinite(x_value) or not np.isfinite(y_value):
                continue
            branch_power = self._safe_positive_float(record.get("branch_power"), np.nan)
            if not np.isfinite(branch_power):
                branch_power = self._safe_positive_float(record.get("transmission"), 1.0)
            source_weight = self._safe_positive_float(record.get("source_weight"), 1.0)
            source_power = self._safe_positive_float(record.get("source_power"), 1.0)
            x_values.append(float(x_value))
            y_values.append(float(y_value))
            weights.append(float(max(branch_power * source_weight * source_power, 0.0)))
            terminals.append(
                self._terminal_surface_label(record.get("last_surface"), str(record.get("last_name", "") or ""))
            )
            terminal_surfaces.append(record.get("last_surface"))
            coord_modes.add(coord_mode)

        coord = "local" if coord_modes == {"local"} else "world"
        return {
            "x": np.asarray(x_values, dtype=float),
            "y": np.asarray(y_values, dtype=float),
            "weights": np.asarray(weights, dtype=float),
            "terminals": terminals,
            "terminal_surfaces": terminal_surfaces,
            "coord": coord,
            "used_detector_only": bool(detector_records),
            "matched_ray_count": len(ray_records),
        }

    def _plot_branch_detector_spot_analysis(self, analysis_ax, system, mode: str) -> None:
        filter_text = self._current_analysis_branch_filter()
        self._set_analysis_parallel_status("Path Spot" if mode == "spot" else "Path RMS", 1, False)
        samples = self._branch_detector_spot_samples(system, filter_text)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        y_values = np.asarray(samples.get("y", np.asarray([])), dtype=float)
        weights = np.asarray(samples.get("weights", np.asarray([])), dtype=float)
        if x_values.size == 0 or y_values.size == 0:
            analysis_ax.text(
                0.5,
                0.5,
                f"No detector hit data for\n{filter_text}",
                ha="center",
                va="center",
            )
            analysis_ax.set_axis_off()
            self.append_debug(f"Path {mode} analysis: no detector hit data for filter={filter_text}")
            return

        spot_mode = self._current_spot_view_mode()
        center_weights = np.maximum(weights, 1e-12) if weights.size == x_values.size else None
        center_x = (
            float(np.average(x_values, weights=center_weights))
            if center_weights is not None
            else float(np.mean(x_values))
        )
        center_y = (
            float(np.average(y_values, weights=center_weights))
            if center_weights is not None
            else float(np.mean(y_values))
        )
        if spot_mode == "Absolute":
            plot_x = x_values
            plot_y = y_values
        else:
            plot_x = x_values - center_x
            plot_y = y_values - center_y

        radii = np.sqrt((x_values - center_x) ** 2 + (y_values - center_y) ** 2)
        if weights.size == radii.size and float(np.sum(weights)) > 0.0:
            rms = float(np.sqrt(np.average(radii * radii, weights=np.maximum(weights, 0.0))))
        else:
            rms = float(np.sqrt(np.mean(radii * radii)))
        coordinate_label = "detector local" if samples.get("coord") == "local" else "world"

        if mode == "rms":
            bins = min(max(5, int(np.sqrt(max(len(radii), 1)))), 24)
            analysis_ax.hist(
                radii,
                bins=bins,
                weights=weights if weights.size == radii.size else None,
                color="#2563eb",
                edgecolor="white",
            )
            analysis_ax.set_title(f"Path Spot Radius | RMS={rms:.4g} mm")
            analysis_ax.set_xlabel("Radius from weighted centroid [mm]")
            analysis_ax.set_ylabel("Power-weighted count" if weights.size == radii.size else "Count")
            analysis_ax.set_box_aspect(0.52)
            analysis_ax.grid(True, axis="y", alpha=0.2)
        else:
            marker_sizes = np.full(plot_x.shape, 22.0, dtype=float)
            max_weight = float(np.nanmax(weights)) if weights.size == plot_x.size else 0.0
            if max_weight > 0.0:
                marker_sizes = 14.0 + 38.0 * np.sqrt(np.clip(weights / max_weight, 0.0, 1.0))
            scatter = analysis_ax.scatter(
                plot_x,
                plot_y,
                s=marker_sizes,
                c=weights if weights.size == plot_x.size else "#c0392b",
                cmap="viridis",
                alpha=0.82,
                edgecolors="#111827",
                linewidths=0.25,
            )
            if max_weight > 0.0:
                self.figure.colorbar(scatter, ax=analysis_ax, fraction=0.046, pad=0.04, label="Relative path power")
            analysis_ax.axhline(0.0, color="#2c3e50", linewidth=0.6, alpha=0.5)
            analysis_ax.axvline(0.0, color="#2c3e50", linewidth=0.6, alpha=0.5)
            title_suffix = "Absolute" if spot_mode == "Absolute" else "Centroid Referenced"
            analysis_ax.set_title(f"Path Detector Spot ({title_suffix})")
            analysis_ax.set_xlabel(f"X [{coordinate_label}, mm]")
            analysis_ax.set_ylabel(f"Y [{coordinate_label}, mm]")
            analysis_ax.set_aspect("auto")
            analysis_ax.set_box_aspect(0.62)
            analysis_ax.grid(True, alpha=0.2)

        terminal_count = len(set(samples.get("terminals", []) or []))
        analysis_ax.text(
            0.02,
            0.98,
            f"{filter_text}\nrays={x_values.size}/{int(samples.get('matched_ray_count', x_values.size) or x_values.size)} | terminals={terminal_count}",
            transform=analysis_ax.transAxes,
            ha="left",
            va="top",
            fontsize=7.5,
            bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
        )
        self.append_debug(
            f"Path {mode} analysis ok: filter={filter_text}, rays={x_values.size}, "
            f"terminals={terminal_count}, rms={rms:.6g}, coord={coordinate_label}"
        )

    def _detector_map_extent(self, samples: dict[str, object], x_values: np.ndarray, y_values: np.ndarray) -> tuple[float, float, float, float]:
        model = self._detector_model_for_samples(samples)
        active_width = float(model.get("active_width_mm", 0.0))
        active_height = float(model.get("active_height_mm", 0.0))
        if samples.get("coord") == "local" and active_width > 0.0 and active_height > 0.0:
            return (-0.5 * active_width, 0.5 * active_width, -0.5 * active_height, 0.5 * active_height)

        x_min = float(np.min(x_values))
        x_max = float(np.max(x_values))
        y_min = float(np.min(y_values))
        y_max = float(np.max(y_values))
        x_span = max(x_max - x_min, 1e-6)
        y_span = max(y_max - y_min, 1e-6)
        pad = max(x_span, y_span, 1e-3) * 0.2
        return (x_min - pad, x_max + pad, y_min - pad, y_max + pad)

    def _branch_detector_map_data(self, system, filter_text: str | None = None) -> dict[str, object]:
        filter_text = self._current_analysis_branch_filter() if filter_text is None else _normalize_path_filter_label(filter_text)
        samples = self._branch_detector_spot_samples(system, filter_text, require_detector=True)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        y_values = np.asarray(samples.get("y", np.asarray([])), dtype=float)
        weights = np.asarray(samples.get("weights", np.asarray([])), dtype=float)
        terminal_labels = list(samples.get("terminals", []) or [])
        terminal_count = len(set(terminal_labels))

        if x_values.size == 0 or y_values.size == 0:
            raise RuntimeError(
                f"No detector hits for {filter_text}. DetMap needs rays that terminate on a Detector row. "
                "Try Layouts -> Beam Splitters / Folds -> Beam Splitter Two Path Doublets, "
                "Michelson Interferometer (Interferogram), Mach-Zehnder Interferometer (Interferogram), "
                "or Twyman-Green Interferometer (Interferogram); click Update; then choose a detector "
                "Analysis path such as Output: Detector output port or a Terminal: ... Detector entry."
            )
        if terminal_count > 1:
            raise RuntimeError("Detector map needs one terminal plane. Choose a specific Terminal or output path.")

        weights_for_hist = weights if weights.size == x_values.size else None
        if weights_for_hist is None or float(np.sum(weights_for_hist)) <= 0.0:
            weights_for_hist = np.ones_like(x_values, dtype=float)
        extent = self._detector_map_extent(samples, x_values, y_values)
        x_min, x_max, y_min, y_max = extent
        detector_model = self._detector_model_for_samples(samples)
        bins = self._current_detector_bin_count(int(x_values.size), coherent=False, detector_model=detector_model)
        hist, x_edges, y_edges = np.histogram2d(
            x_values,
            y_values,
            bins=bins,
            range=[[x_min, x_max], [y_min, y_max]],
            weights=weights_for_hist,
        )
        if not np.any(hist > 0.0):
            raise RuntimeError("Detector map has no finite bins.")

        terminal_label = terminal_labels[0] if terminal_labels else "Detector"
        coordinate_label = "detector local" if samples.get("coord") == "local" else "world"
        return {
            "filter_text": filter_text,
            "samples": samples,
            "x_values": x_values,
            "y_values": y_values,
            "weights": weights_for_hist,
            "hist": hist,
            "x_edges": x_edges,
            "y_edges": y_edges,
            "bins": bins,
            "terminal_label": terminal_label,
            "terminal_count": terminal_count,
            "coordinate_label": coordinate_label,
            "total_power": float(np.sum(weights_for_hist)),
            "peak_power": float(np.max(hist)),
            "detector_model": detector_model,
        }

    def _branch_detector_psf_data(self, system, filter_text: str | None = None) -> dict[str, object]:
        filter_text = self._current_analysis_branch_filter() if filter_text is None else _normalize_path_filter_label(filter_text)
        samples = self._branch_detector_spot_samples(system, filter_text, require_detector=True)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        y_values = np.asarray(samples.get("y", np.asarray([])), dtype=float)
        weights = np.asarray(samples.get("weights", np.asarray([])), dtype=float)
        terminal_labels = list(samples.get("terminals", []) or [])
        terminal_count = len(set(terminal_labels))
        if x_values.size == 0 or y_values.size == 0:
            raise RuntimeError(f"No detector hits for {filter_text}. Choose a detector path/terminal and click Update.")
        if terminal_count > 1:
            raise RuntimeError("Path PSF/MTF needs one terminal plane. Choose a specific Terminal or output path.")

        weights_for_hist = weights if weights.size == x_values.size else None
        if weights_for_hist is None or float(np.sum(weights_for_hist)) <= 0.0:
            weights_for_hist = np.ones_like(x_values, dtype=float)
        centroid_x = float(np.average(x_values, weights=np.maximum(weights_for_hist, 0.0)))
        centroid_y = float(np.average(y_values, weights=np.maximum(weights_for_hist, 0.0)))
        centered_x = x_values - centroid_x
        centered_y = y_values - centroid_y
        span = max(float(np.ptp(centered_x)), float(np.ptp(centered_y)), 1e-3) * 1.25
        detector_model = self._detector_model_for_samples(samples)
        bins = self._current_detector_bin_count(int(x_values.size), coherent=False, detector_model=detector_model)
        hist, x_edges, y_edges = np.histogram2d(
            centered_x,
            centered_y,
            bins=bins,
            range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
            weights=weights_for_hist,
        )
        if not np.any(hist > 0.0):
            raise RuntimeError("Path detector PSF has no finite bins.")
        terminal_label = terminal_labels[0] if terminal_labels else "Detector"
        coordinate_label = "detector local" if samples.get("coord") == "local" else "world"
        return {
            "filter_text": filter_text,
            "samples": samples,
            "x_values": x_values,
            "y_values": y_values,
            "centered_x": centered_x,
            "centered_y": centered_y,
            "weights": weights_for_hist,
            "hist": hist,
            "x_edges": x_edges,
            "y_edges": y_edges,
            "bins": bins,
            "span": span,
            "centroid_x": centroid_x,
            "centroid_y": centroid_y,
            "terminal_label": terminal_label,
            "terminal_count": terminal_count,
            "coordinate_label": coordinate_label,
            "total_power": float(np.sum(weights_for_hist)),
            "peak_power": float(np.max(hist)),
            "detector_model": detector_model,
        }

    def _plot_branch_detector_psf_analysis(self, analysis_ax, system, wavelength: float) -> None:
        filter_text = self._current_analysis_branch_filter()
        self._set_analysis_parallel_status("Path PSF", 1, False)
        try:
            data = self._branch_detector_psf_data(system, filter_text)
            hist = np.asarray(data["hist"], dtype=float)
            x_edges = np.asarray(data["x_edges"], dtype=float)
            y_edges = np.asarray(data["y_edges"], dtype=float)
            display = hist.T / max(float(data["peak_power"]), 1e-15)
            image = analysis_ax.imshow(
                display,
                origin="lower",
                extent=[float(x_edges[0]), float(x_edges[-1]), float(y_edges[0]), float(y_edges[-1])],
                interpolation="nearest",
                aspect="equal",
                cmap="inferno",
                vmin=0.0,
                vmax=1.0,
            )
            centered_x = np.asarray(data["centered_x"], dtype=float)
            centered_y = np.asarray(data["centered_y"], dtype=float)
            if centered_x.size <= 400:
                analysis_ax.scatter(centered_x, centered_y, s=6, c="white", alpha=0.45, linewidths=0.0)
            analysis_ax.set_title(f"Path Detector PSF  |  {wavelength:.4g} um")
            analysis_ax.set_xlabel(f"X [{data['coordinate_label']}, centroid mm]")
            analysis_ax.set_ylabel(f"Y [{data['coordinate_label']}, centroid mm]")
            analysis_ax.set_box_aspect(0.62)
            cbar = analysis_ax.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04)
            cbar.set_label("Normalized power")
            analysis_ax.text(
                0.02,
                0.98,
                f"{filter_text}\n{data['terminal_label']}\nrays={centered_x.size} | bins={int(data['bins'])}x{int(data['bins'])}\n"
                f"power={float(data['total_power']):.6g}",
                transform=analysis_ax.transAxes,
                ha="left",
                va="top",
                fontsize=7.5,
                bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
            )
            self.append_debug(
                f"Path PSF ok: filter={filter_text}, terminal={data['terminal_label']}, "
                f"rays={centered_x.size}, bins={int(data['bins'])}, power={float(data['total_power']):.6g}"
            )
        except Exception as exc:
            analysis_ax.text(0.5, 0.5, str(exc), ha="center", va="center")
            analysis_ax.set_axis_off()
            self.append_debug(f"Path PSF unavailable: {exc}")

    def _branch_detector_mtf_data(self, system, filter_text: str | None = None) -> dict[str, object]:
        data = self._branch_detector_psf_data(system, filter_text)
        hist = np.asarray(data["hist"], dtype=float)
        x_edges = np.asarray(data["x_edges"], dtype=float)
        if hist.size == 0 or hist.shape[0] < 2:
            raise RuntimeError("Path detector MTF needs at least two detector bins.")
        psf = hist / max(float(np.sum(hist)), 1e-15)
        otf = np.fft.fftshift(np.fft.fft2(psf))
        mtf = np.abs(otf)
        mtf /= max(float(np.max(mtf)), 1e-15)
        dx = float(x_edges[1] - x_edges[0])
        if not np.isfinite(dx) or dx <= 0.0:
            raise RuntimeError("Path detector MTF has invalid detector bin pitch.")
        bins = int(hist.shape[0])
        freq = np.fft.fftshift(np.fft.fftfreq(bins, d=dx))
        center = bins // 2
        plot_freq = np.asarray(freq[center:], dtype=float)
        plot_tan = np.asarray(mtf[center, center:], dtype=float)
        plot_sag = np.asarray(mtf[center:, center], dtype=float)
        count = min(plot_freq.size, plot_tan.size, plot_sag.size)
        if count == 0:
            raise RuntimeError("Path detector MTF has no positive frequency samples.")
        data.update(
            {
                "plot_freq": plot_freq[:count],
                "plot_tan": plot_tan[:count],
                "plot_sag": plot_sag[:count],
                "plot_avg": 0.5 * (plot_tan[:count] + plot_sag[:count]),
                "method": "Path Detector Geometric-PSF",
            }
        )
        return data

    def _plot_branch_detector_mtf_analysis(self, analysis_ax, system, wavelength: float) -> None:
        filter_text = self._current_analysis_branch_filter()
        self._set_analysis_parallel_status("Path MTF", 1, False)
        try:
            data = self._branch_detector_mtf_data(system, filter_text)
            plot_freq = np.asarray(data["plot_freq"], dtype=float)
            plot_tan = np.asarray(data["plot_tan"], dtype=float)
            plot_sag = np.asarray(data["plot_sag"], dtype=float)
            plot_avg = np.asarray(data["plot_avg"], dtype=float)
            target_freq = self._current_mtf_frequency()
            mtf_mode = self._operand_mtf_mode("MTF @ freq")
            if mtf_mode == "tangential":
                selected_curve = plot_tan
                selected_label = "Tangential"
            elif mtf_mode == "sagittal":
                selected_curve = plot_sag
                selected_label = "Sagittal"
            else:
                selected_curve = plot_avg
                selected_label = "Average"
            selected_value = float(np.interp(target_freq, plot_freq, selected_curve, left=selected_curve[0], right=selected_curve[-1]))

            analysis_ax.plot(plot_freq, plot_tan, color="#2563eb", linewidth=1.4, label="Tangential")
            analysis_ax.plot(plot_freq, plot_sag, color="#dc2626", linewidth=1.2, linestyle=(0, (6, 3)), label="Sagittal")
            if mtf_mode == "average":
                analysis_ax.plot(plot_freq, plot_avg, color="#111827", linewidth=1.0, linestyle=(0, (2, 2)), label="Average")
            analysis_ax.axvline(target_freq, color="#475569", linewidth=0.9, linestyle=(0, (2, 2)), alpha=0.8)
            analysis_ax.set_title(f"Path Detector MTF  |  {wavelength:.4g} um")
            analysis_ax.set_xlabel("Spatial frequency [cycles/mm]")
            analysis_ax.set_ylabel("MTF")
            analysis_ax.set_ylim(0.0, 1.05)
            x_max = max(float(plot_freq[-1]), max(10.0, target_freq * 1.2))
            analysis_ax.set_xlim(0.0, x_max)
            analysis_ax.set_box_aspect(0.62)
            analysis_ax.grid(True, alpha=0.2)
            analysis_ax.legend(loc="best", fontsize=7)
            analysis_ax.text(
                0.02,
                0.98,
                f"{filter_text}\n{data['terminal_label']}\n{selected_label} @ {target_freq:.3g} cy/mm = {selected_value:.4g}\n"
                f"rays={len(data['x_values'])} | bins={int(data['bins'])}x{int(data['bins'])}",
                transform=analysis_ax.transAxes,
                ha="left",
                va="top",
                fontsize=7.5,
                bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
            )
            self.append_debug(
                f"Path MTF ok: filter={filter_text}, terminal={data['terminal_label']}, "
                f"rays={len(data['x_values'])}, bins={int(data['bins'])}, target={target_freq:.6g}, value={selected_value:.6g}"
            )
        except Exception as exc:
            analysis_ax.text(0.5, 0.5, str(exc), ha="center", va="center")
            analysis_ax.set_axis_off()
            self.append_debug(f"Path MTF unavailable: {exc}")

    @staticmethod
    def _branch_psf_csv_columns() -> tuple[str, ...]:
        return (
            "filter",
            "terminal",
            "coordinate",
            "ray_count",
            "bins",
            "centroid_x_mm",
            "centroid_y_mm",
            "bin_x",
            "bin_y",
            "x_min_centered_mm",
            "x_max_centered_mm",
            "y_min_centered_mm",
            "y_max_centered_mm",
            "x_center_centered_mm",
            "y_center_centered_mm",
            "power",
            "normalized_power",
            "total_power",
            "peak_power",
        )

    def _branch_detector_psf_csv_rows(self, data: dict[str, object]) -> list[dict[str, object]]:
        hist = np.asarray(data["hist"], dtype=float)
        x_edges = np.asarray(data["x_edges"], dtype=float)
        y_edges = np.asarray(data["y_edges"], dtype=float)
        x_values = np.asarray(data["x_values"], dtype=float)
        filter_text = str(data["filter_text"])
        terminal_label = str(data["terminal_label"])
        coordinate_label = str(data["coordinate_label"])
        bins = int(data["bins"])
        centroid_x = float(data["centroid_x"])
        centroid_y = float(data["centroid_y"])
        total_power = float(data["total_power"])
        peak_power = float(data["peak_power"])
        rows: list[dict[str, object]] = []
        for ix in range(hist.shape[0]):
            x_min = float(x_edges[ix])
            x_max = float(x_edges[ix + 1])
            x_center = 0.5 * (x_min + x_max)
            for iy in range(hist.shape[1]):
                y_min = float(y_edges[iy])
                y_max = float(y_edges[iy + 1])
                power = float(hist[ix, iy])
                rows.append(
                    {
                        "filter": filter_text,
                        "terminal": terminal_label,
                        "coordinate": coordinate_label,
                        "ray_count": int(x_values.size),
                        "bins": bins,
                        "centroid_x_mm": centroid_x,
                        "centroid_y_mm": centroid_y,
                        "bin_x": ix,
                        "bin_y": iy,
                        "x_min_centered_mm": x_min,
                        "x_max_centered_mm": x_max,
                        "y_min_centered_mm": y_min,
                        "y_max_centered_mm": y_max,
                        "x_center_centered_mm": x_center,
                        "y_center_centered_mm": 0.5 * (y_min + y_max),
                        "power": power,
                        "normalized_power": power / max(peak_power, 1e-15),
                        "total_power": total_power,
                        "peak_power": peak_power,
                    }
                )
        return rows

    @staticmethod
    def _branch_mtf_csv_columns() -> tuple[str, ...]:
        return (
            "filter",
            "terminal",
            "coordinate",
            "ray_count",
            "bins",
            "method",
            "frequency_cy_per_mm",
            "tangential_mtf",
            "sagittal_mtf",
            "average_mtf",
            "target_frequency_cy_per_mm",
            "selected_curve",
            "selected_mtf_at_target",
            "max_frequency_cy_per_mm",
        )

    def _branch_detector_mtf_csv_rows(
        self,
        data: dict[str, object],
        *,
        target_freq: float | None = None,
        mtf_mode: str | None = None,
    ) -> list[dict[str, object]]:
        plot_freq = np.asarray(data["plot_freq"], dtype=float)
        plot_tan = np.asarray(data["plot_tan"], dtype=float)
        plot_sag = np.asarray(data["plot_sag"], dtype=float)
        plot_avg = np.asarray(data["plot_avg"], dtype=float)
        count = min(plot_freq.size, plot_tan.size, plot_sag.size, plot_avg.size)
        if count == 0:
            return []
        target = float(self._current_mtf_frequency() if target_freq is None else target_freq)
        mode = str(self._operand_mtf_mode("MTF @ freq") if mtf_mode is None else mtf_mode).strip().lower()
        if mode == "tangential":
            selected_curve = plot_tan[:count]
            selected_label = "Tangential"
        elif mode == "sagittal":
            selected_curve = plot_sag[:count]
            selected_label = "Sagittal"
        else:
            selected_curve = plot_avg[:count]
            selected_label = "Average"
        selected_value = float(
            np.interp(
                target,
                plot_freq[:count],
                selected_curve,
                left=selected_curve[0],
                right=selected_curve[-1],
            )
        )
        x_values = np.asarray(data["x_values"], dtype=float)
        rows: list[dict[str, object]] = []
        for index in range(count):
            rows.append(
                {
                    "filter": str(data["filter_text"]),
                    "terminal": str(data["terminal_label"]),
                    "coordinate": str(data["coordinate_label"]),
                    "ray_count": int(x_values.size),
                    "bins": int(data["bins"]),
                    "method": str(data.get("method", "Path Detector Geometric-PSF")),
                    "frequency_cy_per_mm": float(plot_freq[index]),
                    "tangential_mtf": float(plot_tan[index]),
                    "sagittal_mtf": float(plot_sag[index]),
                    "average_mtf": float(plot_avg[index]),
                    "target_frequency_cy_per_mm": target,
                    "selected_curve": selected_label,
                    "selected_mtf_at_target": selected_value,
                    "max_frequency_cy_per_mm": float(plot_freq[count - 1]),
                }
            )
        return rows

    def export_branch_psf_csv(self) -> None:
        if self.last_system is None or self.last_rays is None:
            messagebox.showinfo(
                "Export Path PSF CSV",
                "No path PSF trace data. Click Update first, then choose an Analysis path.",
                parent=self,
            )
            return
        try:
            data = self._branch_detector_psf_data(self.last_system)
            rows = self._branch_detector_psf_csv_rows(data)
        except Exception as exc:
            messagebox.showinfo("Export Path PSF CSV", str(exc), parent=self)
            return

        path = filedialog.asksaveasfilename(
            title="Export Path PSF CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        columns = self._branch_psf_csv_columns()
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=columns)
            writer.writeheader()
            writer.writerows(rows)
        self.status_var.set(f"Path PSF CSV exported: {Path(path).name}")
        self.append_debug(
            f"Path PSF CSV exported: {path} | filter={data['filter_text']}, terminal={data['terminal_label']}, "
            f"rays={len(data['x_values'])}, bins={int(data['bins'])}, rows={len(rows)}"
        )

