            "valid_sample_count",
            "sample_std",
            "p95_abs_delta",
            "worst_sample",
            "worst_delta_norm",
            "slope_norm_merit_per_unit",
            "correlation",
            "variance_contribution",
            "merit_sigma_contribution",
            "contribution_fraction",
